namespace App\Http\Resources\Admin;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class StockTransferResource extends JsonResource
{
    /**
     * Transform the resource into an array.
     *
     * @return array<string, mixed>
     */
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'version' => $this->version,
            'transfer_number' => $this->transfer_number,
            'from_branch' => $this->whenLoaded('fromBranch', fn () => [
                'id' => $this->fromBranch->id,
                'name' => $this->fromBranch->name,
            ]),
            'to_branch' => $this->whenLoaded('toBranch', fn () => [
                'id' => $this->toBranch->id,
                'name' => $this->toBranch->name,
            ]),
            'status' => $this->status,
            'created_by' => $this->created_by,
            'creator_name' => $this->whenLoaded('creator', fn () => $this->creator?->name),
            'approved_by' => $this->approved_by,
            'shipped_at' => $this->shipped_at,
            'received_at' => $this->received_at,
            'notes' => $this->notes,
            'items' => $this->whenLoaded('items', fn () => $this->items->map(fn ($item) => [
                'id' => $item->id,
                'product_variant_id' => $item->product_variant_id,
                'sku' => $item->relationLoaded('variant') ? $item->variant?->sku : null,
                'variant' => $item->relationLoaded('variant') && $item->variant ? [
                    'id' => $item->variant->id,
                    'sku' => $item->variant->sku,
                    'barcode' => $item->variant->barcode,
                    'product_name' => $item->variant->relationLoaded('product')
                        ? ($item->variant->product?->name_ar ?? $item->variant->product?->name_en)
                        : null,
                    'variant_name' => $item->variant->color_name_ar ?? $item->variant->color_name_en,
                ] : null,
                'from_location' => $item->relationLoaded('fromLocation') && $item->fromLocation ? [
                    'id' => $item->fromLocation->id, 'name' => $item->fromLocation->name,
                ] : null,
                'to_location' => $item->relationLoaded('toLocation') && $item->toLocation ? [
                    'id' => $item->toLocation->id, 'name' => $item->toLocation->name,
                ] : null,
                'requested_qty' => $item->requested_qty,
                'approved_qty' => $item->approved_qty,
                'shipped_qty' => $item->shipped_qty,
                'received_qty' => $item->received_qty,
            ])->all()),
            'created_at' => $this->created_at,
            'updated_at' => $this->updated_at,
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\LocationType;
use Database\Factories\LocationFactory;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

#[Fillable(['branch_id', 'name', 'code', 'type', 'is_active'])]
/**
 * Specific storage area, aisle, or bin within a physical branch.
 */
class Location extends Model
{
    /** @use HasFactory<LocationFactory> */
    use HasFactory;

    public function branch(): BelongsTo
    {
        return $this->belongsTo(Branch::class);
    }

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'type' => LocationType::class,
            'is_active' => 'boolean',
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\OrderStatus;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\MorphTo;

/**
 * Append-only order status transition history; created exclusively by OrderService::changeStatus().
 */
class OrderStatusHistory extends Model
{
    public const UPDATED_AT = null;

    protected $fillable = [
        'order_id',
        'from_status',
        'to_status',
        'changed_by_type',
        'changed_by_id',
        'notes',
    ];

    protected function casts(): array
    {
        return [
            'from_status' => OrderStatus::class,
            'to_status' => OrderStatus::class,
        ];
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }

    /** @return MorphTo<Model, $this> */
    public function changedBy(): MorphTo
    {
        return $this->morphTo();
    }
}<?php

