export interface IconProps {
  n: string;
  s?: number;
  w?: number;
  className?: string;
  style?: React.CSSProperties;
}

export function Icon({ n, s = 18, w = 1.8, className, style }: IconProps) {
  return (
    <svg
      width={s}
      height={s}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={w}
      strokeLinecap="round"
      strokeLinejoin="round"
