}export const normAr = (s: string): string =>
  s
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[۰-۹]/g, (d) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[\u064B-\u0652\u0640]/g, '') // diacritics + tatweel
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .toLowerCase()
    .trim();/**
 * HID barcode scanners type characters faster than a human (<40ms apart) and end with Enter.
 * This detector turns that pattern into a scan, regardless of which element has focus.
 */
export interface ScanKeyEvent {
  key: string;
  target: EventTarget | null;
  preventDefault: () => void;
  ctrlKey?: boolean;
  altKey?: boolean;
  metaKey?: boolean;
}

export interface ScanDetectorOptions {
  onScan: (code: string) => void;
  now?: () => number;
  minLength?: number;
  gapMs?: number;
  ignore?: (target: EventTarget | null) => boolean;
}

/** textarea, the payment MoneyInput and the scan bar itself (which handles its own Enter). */
export function defaultScanIgnore(target: EventTarget | null): boolean {
  const el = target as { tagName?: string; closest?: (sel: string) => unknown } | null;
  if (!el) return false;
  if (el.tagName === 'TEXTAREA') return true;
  return Boolean(el.closest?.('[data-money-input]') || el.closest?.('[data-scan-input]'));
}

export function createScanDetector(opts: ScanDetectorOptions): (e: ScanKeyEvent) => void {
  const now = opts.now ?? (() => performance.now());
  const minLength = opts.minLength ?? 6;
  const gapMs = opts.gapMs ?? 40;
  const ignore = opts.ignore ?? defaultScanIgnore;
  let buf = '';
  let last = 0;

  return (e) => {
    if (ignore(e.target) || e.ctrlKey || e.altKey || e.metaKey) {
      buf = '';
      return;
    }
    const t = now();
    if (t - last > gapMs) buf = '';
    last = t;
    if (e.key === 'Enter') {
      if (buf.length >= minLength) {
        e.preventDefault();
        const code = buf;
        buf = '';
        opts.onScan(code);
      } else {
        buf = '';
      }
      return;
    }
    if (e.key.length === 1) buf += e.key;
  };
}import type { CreateSalePayload, QuoteResult } from '../types/pos.types';
import { fromCents, toCents } from './money';

interface CheckoutPayment {
  customerId: number | null;
  method: CreateSalePayload['payment_method'];
  cashCents: number;
  overridePrice: boolean;
  notes: string;
}

export function buildCheckoutPayload(quote: QuoteResult, payment: CheckoutPayment): CreateSalePayload {
  const totalCents = toCents(quote.grand_total);
  const cashCents = payment.method === 'cash' ? totalCents : payment.method === 'mixed' ? payment.cashCents : 0;
  return {
    items: quote.lines.map(({ product_variant_id, qty, unit_price, discount_amount }) => ({
      product_variant_id, qty, unit_price, discount_amount,
    })),
    customer_id: payment.customerId,
    payment_method: payment.method,
    cash_amount: fromCents(cashCents),
    card_amount: fromCents(totalCents - cashCents),
    ...(payment.overridePrice ? { override_price: true } : {}),
    notes: payment.notes,
  };
}export class PosApiError extends Error {
  constructor(
    public status: number,
    message: string,
    public code?: string,
    public fields?: Record<string, string[]>,
    public retryable = false,
  ) {
    super(message);
    this.name = 'PosApiError';
  }
}

export function isCancel(e: any): boolean {
  return e?.code === 'ERR_CANCELED' || e?.name === 'CanceledError' || e?.name === 'AbortError' || e?.__CANCEL__ === true;
}

/** Cancellations are rethrown untouched so callers can ignore them. */
export function normalizeError(e: any): PosApiError {
  if (isCancel(e)) throw e;
  if (e instanceof PosApiError) return e;
  const r = e?.response;
  if (!r) return new PosApiError(0, 'انقطع الاتصال بالسيرفر', 'network', undefined, true);
  const msg = r.data?.message ?? 'حدث خطأ غير متوقع';
  return new PosApiError(r.status, msg, r.data?.code, r.data?.errors, r.status === 409 && !/مفتاح عدم التكرار/.test(msg));
}import type { PosCartLine, Customer, Branch, CashierUser } from '../types/pos.types';

export interface ArchivedReceipt {
  invoiceNumber: string;
  total: number;
  method: 'cash' | 'card' | 'mixed';
  received: number;
  change: number;
  cashA: number;
  cardA: number;
  cart: PosCartLine[];
  customer: Customer | null;
  discount: number;
  notes?: string;
  branch?: Branch | null;
  cashier?: CashierUser | null;
  timestamp: number;
}

const MAX_RECEIPTS = 5;
const archive: ArchivedReceipt[] = [];

export function pushReceipt(receipt: ArchivedReceipt): void {
  archive.unshift(receipt);
  if (archive.length > MAX_RECEIPTS) {
    archive.length = MAX_RECEIPTS;
  }
}

export function getLastReceipt(): ArchivedReceipt | null {
  return archive[0] ?? null;
}

export function getReceiptArchive(): ArchivedReceipt[] {
  return [...archive];
}

export function clearReceiptArchive(): void {
  archive.length = 0;
}/** Audible feedback without audio files: one short high tone = added, a low double tone = not found / out of stock. */
let ctx: AudioContext | null = null;

function audio(): AudioContext | null {
  const Ctor: typeof AudioContext | undefined =
    typeof window !== 'undefined' ? (window.AudioContext ?? (window as any).webkitAudioContext) : undefined;
  if (!Ctor) return null;
  ctx ??= new Ctor();
  if (ctx.state === 'suspended') void ctx.resume();
  return ctx;
}

function tone(freq: number, seconds: number, type: OscillatorType, delay = 0): void {
  try {
    const c = audio();
    if (!c) return;
    const osc = c.createOscillator();
    const gain = c.createGain();
    const start = c.currentTime + delay;
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0.15, start);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + seconds);
    osc.connect(gain).connect(c.destination);
    osc.start(start);
    osc.stop(start + seconds);
  } catch {
    /* audio is best-effort */
  }
}

export const beepSuccess = (): void => tone(1200, 0.07, 'sine');

export const beepError = (): void => {
  tone(300, 0.12, 'square');
  tone(220, 0.18, 'square', 0.14);
};export interface TabCoordinatorOptions {
  channelName?: string;
  channelFactory?: () => any;
  onDuplicate?: () => void;
}

export function createTabCoordinator(opts: TabCoordinatorOptions = {}) {
  const channelName = opts.channelName ?? 'pos-tab-channel';
  const myId = globalThis.crypto?.randomUUID?.() ?? String(Math.random());
  let channel: any = null;

  const start = () => {
    try {
      if (opts.channelFactory) {
        channel = opts.channelFactory();
      } else if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
        channel = new window.BroadcastChannel(channelName);
      }
    } catch {
      return;
    }

    if (!channel) return;

    channel.onmessage = (event: MessageEvent) => {
      const data = event.data;
      if (!data || data.from === myId) return;

      if (data.type === 'hello') {
        // We were here first, tell the new tab we are active
        channel?.postMessage({ type: 'here', from: myId });
      } else if (data.type === 'here') {
        // An existing tab is already running!
        opts.onDuplicate?.();
      }
    };

    // Announce ourselves to see if an older tab exists
    channel.postMessage({ type: 'hello', from: myId });
  };

  const destroy = () => {
    try {
      channel?.close();
    } catch {
      // ignore
    }
    channel = null;
  };

  return {
    start,
    destroy,
  };
