namespace App\Enums;

/**
 * Supported payment channels for reimbursing approved customer return requests.
 */
enum RefundMethod: string
{
    case OriginalPayment = 'original_payment';
    case Wallet = 'wallet';
    case BankTransfer = 'bank_transfer';
    case Cash = 'cash';
}<?php

declare(strict_types=1);

namespace App\Enums;

/**
 * Return Merchandise Authorization (RMA) lifecycle statuses. Inventory movements occur only on Received.
 */
enum ReturnStatus: string
{
    case Pending = 'pending';
    case Approved = 'approved';
    case Rejected = 'rejected';
    case Received = 'received';
    case Refunded = 'refunded';
    case Cancelled = 'cancelled';
}<?php

declare(strict_types=1);

namespace App\Enums;

enum StaffRole: string
{
    case SuperAdmin = 'Super Admin';
    case Cashier = 'cashier';

    public static function normalizeName(string $name): string
    {
        return trim(\Normalizer::normalize($name, \Normalizer::FORM_KC) ?: $name);
    }

    public static function isReserved(string $name): bool
    {
        $name = mb_strtolower(self::normalizeName($name));
        foreach (self::cases() as $role) {
            if ($name === mb_strtolower($role->value)) {
                return true;
            }
        }

        return false;
    }
}<?php

declare(strict_types=1);

namespace App\Exceptions;

use Exception;
use Illuminate\Http\JsonResponse;

/**
 * Exception thrown when domain business constraints or state preconditions are violated.
 */
class BusinessException extends Exception
{
    public function __construct(
        string $message,
        public array $errors = [],
        public int $status = 422,
        public ?string $errorCode = null,
    ) {
        parent::__construct($message);
    }

    /**
     * Render the exception into a JSON HTTP response.
     */
    public function render(): JsonResponse
    {
        $payload = ['message' => $this->getMessage(), 'errors' => $this->errors];
        if ($this->errorCode !== null) {
            // Machine-readable error code for client error handling (e.g. 'credit_limit_exceeded').
            $payload['code'] = $this->errorCode;
        }

        $response = response()->json($payload, $this->status);
        if ($this->status === 503) {
            $response->headers->set('Retry-After', '1');
        }

        return $response;
    }
}<?php

declare(strict_types=1);

namespace App\Http\Middleware;

use App\Enums\PosShiftStatus;
use App\Models\PosShift;
use App\Models\User;
use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

/**
 * Ensures the authenticated cashier has an active, open shift at their assigned branch.
 * Injects the open shift model into request attributes under 'pos_shift'.
 */
class EnsureOpenPosShift
{
    /**
     * Handle incoming POS request and verify active shift presence.
     */
    public function handle(Request $request, Closure $next): Response
    {
        $user = $request->user('staff');

        if (! $user instanceof User || $user->branch_id === null) {
            return response()->json([
                'message' => 'لا يمكن استخدام نقطة البيع بدون ارتباط بفرع.',
            ], 403);
        }

        $shift = PosShift::query()
            ->where('user_id', $user->id)
            ->where('branch_id', $user->branch_id)
            ->where('status', PosShiftStatus::Open)
            ->latest('id')
            ->first();

        if ($shift === null) {
            return response()->json([
                'message' => 'لا توجد وردية مفتوحة. افتح وردية أولًا لإتمام العملية.',
                'code'    => 'no_open_shift',
            ], 403);
        }

        $request->attributes->set('pos_shift', $shift);

        return $next($request);
    }
}<?php

declare(strict_types=1);

namespace App\Http\Requests\Admin\Transfer;

use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Transfer stage item quantity requests (approval, shipment, receipt).
 * Items are optional; omitted items default to previous stage quantities.
 */
class TransferItemsQtyRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    /** Quantity field name for the active transfer stage (specialized in child classes). */
    protected string $qtyField = 'approved_qty';

    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        $transferId = $this->route('transfer')?->id;

        return [
            'expected_version' => ['nullable', 'integer', 'min:1'],
            'expected_updated_at' => ['nullable', 'date'],
            'items' => ['nullable', 'array', 'max:100'],
            'items.*.id' => [
                'required', 'bail', 'integer', 'min:1', 'distinct',
                Rule::exists('stock_transfer_items', 'id')->where('stock_transfer_id', $transferId),
            ],
            "items.*.{$this->qtyField}" => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
        ];
    }

    /**
     * Map of [item_id => quantity] formatted for service execution.
     *
     * @return array<int, float>
     */
    public function quantitiesByItemId(): array
    {
        $map = [];

        foreach ($this->validated('items', []) ?? [] as $item) {
            $map[(int) $item['id']] = (float) $item[$this->qtyField];
        }

        return $map;
    }

    public function expectedVersion(): ?int
    {
        return $this->filled('expected_version') ? (int) $this->validated('expected_version') : null;
    }

    public function expectedUpdatedAt(): ?string
    {
        return $this->validated('expected_updated_at');
    }
}<?php

declare(strict_types=1);

namespace App\Http\Resources\Admin;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

/**
 * Administrative stock level resource representation detailing on-hand, reserved, and low-stock indicators.
 */
class StockLevelResource extends JsonResource
{
    /**
     * Transform the resource into an array.
     *
     * @return array<string, mixed>
     */
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'product_variant_id' => $this->product_variant_id,
            'variant' => $this->whenLoaded('variant', fn () => [
                'id' => $this->variant->id,
                'sku' => $this->variant->sku,
                'barcode' => $this->variant->barcode,
                'product_id' => $this->variant->product_id,
                'product_name_ar' => $this->variant->relationLoaded('product') ? $this->variant->product?->name_ar : null,
                'product_name_en' => $this->variant->relationLoaded('product') ? $this->variant->product?->name_en : null,
            ]),
            'branch' => $this->whenLoaded('branch', fn () => [
                'id' => $this->branch->id,
                'name' => $this->branch->name,
            ]),
            'location' => $this->whenLoaded('location', fn () => $this->location ? [
                'id' => $this->location->id,
                'name' => $this->location->name,
                'code' => $this->location->code,
            ] : null),
            'on_hand' => $this->on_hand,
            'reserved' => $this->reserved,
            'damaged' => $this->damaged,
            'in_transit' => $this->in_transit,
            'available' => number_format($this->available, 4, '.', ''),
            // Effective reorder threshold: row-level threshold if set (> 0), falling back to variant-level threshold.
            'reorder_level' => $this->effectiveReorderLevel(),
            // Row-level low stock indicator: rows without an effective threshold (> 0) are not marked as low.
            // For branch-aggregated low stock filtering, refer to StockLevel::whereLowStock.
            'is_low_stock' => $this->effectiveReorderLevel() > 0 && $this->available <= $this->effectiveReorderLevel(),
            'updated_at' => $this->updated_at,
        ];
    }

    /** Resolve effective reorder threshold (row-specific override or variant default). */
    private function effectiveReorderLevel(): float
    {
        if ((float) $this->reorder_level > 0) {
            return (float) $this->reorder_level;
        }

        return $this->relationLoaded('variant') ? (float) ($this->variant?->reorder_level ?? 0) : 0.0;
    }
}<?php

declare(strict_types=1);

namespace App\Http\Resources\Admin;

use App\Enums\StocktakeStatus;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

/**
 * Administrative stocktake resource representation.
 *
 * Enforces blind counting by masking expected inventory quantities and variances until approval or authorized inspection.
 */
class StocktakeResource extends JsonResource
{
    /**
     * Transform the resource into an array.
     *
     * @return array<string, mixed>
     */
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'stocktake_number' => $this->stocktake_number,
            'branch' => $this->whenLoaded('branch', fn () => [
                'id' => $this->branch->id,
                'name' => $this->branch->name,
            ]),
            'location' => $this->whenLoaded('location', fn () => $this->location ? [
                'id' => $this->location->id,
                'name' => $this->location->name,
            ] : null),
            'status' => $this->status,
            'items_count' => $this->whenCounted('items'),
            'created_by' => $this->created_by,
            'creator_name' => $this->whenLoaded('creator', fn () => $this->creator?->name),
            'approved_by' => $this->approved_by,
            'approved_at' => $this->approved_at,
            'notes' => $this->notes,
            // Blind stocktake: hide expected book qty and variance from counters until approved or inspected by approvers.
            'items' => $this->whenLoaded('items', function () use ($request) {
                $reveal = $this->status === StocktakeStatus::Approved
                    || $request->user()?->can('stocktakes.approve');

                return $this->items->map(function ($item) use ($reveal) {
                    $row = [
                        'id' => $item->id,
                        'product_variant_id' => $item->product_variant_id,
                        'sku' => $item->relationLoaded('variant') ? $item->variant?->sku : null,
                    ];
                    if ($reveal) {
                        $row['system_qty'] = $item->system_qty;
                    }
                    $row['counted_qty'] = $item->counted_qty;
                    if ($reveal) {
                        $row['difference'] = $item->difference;
                    }

                    return $row;
                })->all();
            }),
            'created_at' => $this->created_at,
            'updated_at' => $this->updated_at,
        ];
    }
}<?php

