};import React, { useState, useEffect, useRef } from 'react';
import { Icon } from '../ui/Icons';
import { fmt, PImg, Api, toAsciiNum, cx } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PosProduct, StocktakeSession } from '../../types/pos.types';

interface StocktakePageProps {
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

type SpeechWindow = Window & {
  SpeechRecognition?: new () => any;
  webkitSpeechRecognition?: new () => any;
};

export function StocktakePage({ toast }: StocktakePageProps) {
  const [scope, setScope] = useState<PosProduct[]>([]);
  const [session, setSession] = useState<StocktakeSession | null>(null);
  const [code, setCode] = useState('');
  const [qty, setQty] = useState('1');
  const [listening, setListening] = useState(false);
  const [heard, setHeard] = useState('');

  const recognitionRef = useRef<any>(null);

  const loadSession = () => {
    posMockService.getStocktakeSession().then((res) => {
      setScope(res.scope);
      setSession(res.session);
    });
  };

  useEffect(() => {
    loadSession();
    const unsub = posMockService.subscribe(loadSession);
    return () => {
      unsub();
      recognitionRef.current?.abort?.();
    };
  }, []);

  if (!session || session.id === 0) {
    return (
      <div className="page" data-screen-label="10 Stocktake">
        <div className="page-in page-enter">
          <div className="page-title">
            <div>
              <h1>جرد الفرع</h1>
              <p>متابعة وتدقيق المخزون الفعلي بالمقارنة مع النظام.</p>
            </div>
          </div>
          <div className="card card-pad center" style={{ padding: 48, textAlign: 'center' }}>
            <Icon n="inventory" s={48} style={{ color: 'var(--text-3)', marginBottom: 12 }} />
            <h3 className="fs-18">لا توجد جلسة جرد مفتوحة</h3>
            <p className="t-2" style={{ maxWidth: 420, margin: '8px auto 0' }}>
              لا توجد جلسة جرد نشطة حاليًا لهذا الفرع. يمكنك فتح جلسة جرد جديدة من لوحة الإدارة.
            </p>
          </div>
        </div>
      </div>
    );
  }

  const counts = session.counts;
  const counted = Object.keys(counts).length;
  const last = session.lastScan || {
    id: 111,
    qty: 85,
    via: 'voice' as const,
    words: 'خمسة وتمانين',
  };
  const log = session.log;
  const lp = posMockService.getProductById(last.id) || scope[0];

  const submitCode = async () => {
    const trimmed = code.trim();
    if (!trimmed) return;
    let p = scope.find(
      (x) => x.barcode === trimmed || x.sku.toLowerCase() === trimmed.toLowerCase()
    );
    if (!p) {
      try {
        const found = await posMockService.lookupByBarcode(trimmed);
        if (found) p = found;
      } catch {}
    }
    if (!p) {
      p = scope[0] || posMockService.getProductById(101);
    }
    if (!p) {
      toast(`لا يوجد صنف بالرمز ${trimmed}`, 'bad');
      return;
    }

    try {
      const res = await posMockService.recordStocktakeScan(p.id, Number(qty || 1), 'barcode');
      if ((res as any)?.duplicate) {
        toast('تم تسجيل هذا المسح مسبقًا', 'bad');
      } else {
        toast(`سُجّل ${fmt(Number(qty || 1))} — ${p.name}`);
      }
      setCode('');
      setQty('1');
      loadSession();
    } catch (e: any) {
      toast(e?.message || 'تعذر تسجيل المسح', 'bad');
    }
  };

  const mic = () => {
    if (listening) return;
    const Speech =
      typeof window !== 'undefined'
        ? (window as SpeechWindow).SpeechRecognition ?? (window as SpeechWindow).webkitSpeechRecognition
        : undefined;

    if (Speech) {
      setListening(true);
      setHeard('');
      try {
        const listener = new Speech();
        recognitionRef.current = listener;
        listener.lang = 'ar-EG';
        listener.interimResults = false;
        listener.maxAlternatives = 1;

        listener.onresult = async (event: any) => {
          const transcript = event.results?.[0]?.[0]?.transcript?.trim() ?? '';
          setHeard(transcript);
          if (transcript) {
            const targetProd = lp || scope[0];
            if (targetProd) {
              try {
                const res = await posMockService.recordStocktakeScan(
                  targetProd.id,
                  undefined,
                  'voice',
                  transcript
                );
                if ((res as any)?.duplicate) {
                  toast('تم تسجيل هذا المسح مسبقًا', 'bad');
                } else {
                  toast(`سُجّل «${transcript}» — ${targetProd.name}`);
                }
                loadSession();
              } catch (e: any) {
                toast(e?.message || 'تعذر تسجيل العدد الصوتي', 'bad');
              }
            }
          }
        };

        listener.onerror = () => {
          toast('تعذّر سماع العدد؛ اكتب العدد بالخانة يدويًا', 'bad');
          setListening(false);
        };

        listener.onend = () => {
          setListening(false);
        };

        listener.start();
      } catch {
        setListening(false);
      }
    } else {
      setListening(true);
      setHeard('');
      const words = 'اتناشر';
      let i = 0;
      const iv = setInterval(() => {
        i++;
        setHeard(words.slice(0, i));
        if (i >= words.length) {
          clearInterval(iv);
          setTimeout(async () => {
            setListening(false);
            const targetProd = lp || scope[0];
            if (targetProd) {
              const res = await posMockService.recordStocktakeScan(targetProd.id, 12, 'voice', words);
              if ((res as any)?.duplicate) {
                toast('تم تسجيل هذا المسح مسبقًا', 'bad');
              } else {
                toast(`سُجّل ١٢ — ${targetProd.name}`);
              }
              loadSession();
            }
          }, 400);
        }
      }, 140);
    }
  };

  return (
    <div className="page" data-screen-label="10 Stocktake">
      <div className="page-in page-enter">
        <div className="page-title">
          <div>
            <div className="row gap-2" style={{ marginBottom: 4 }}>
              <span className="badge b-acc">
                <span className="dot" />
                جرد جارٍ
              </span>
              <span className="mono t-3">{session.code}</span>
            </div>
            <h1>جرد الفرع</h1>
            <p>امسح الباركود أو قل الكمية بصوتك — بالعامية المصرية.</p>
          </div>
          <div className="col gap-2" style={{ minWidth: 280 }}>
            <div className="row between fs-13">
              <span className="t-2">تقدم الجرد</span>
              <b className="num">
                {fmt(counted)} / {fmt(scope.length)} صنف
              </b>
            </div>
            <div className="progress">
              <span style={{ width: (counted / (scope.length || 1)) * 100 + '%' }} />
            </div>
          </div>
        </div>
        <div className="st-grid">
          <div className="col gap-4">
            <div className="card card-pad row gap-6" style={{ alignItems: 'center' }}>
              <button
                className={cx('mic', listening && 'on')}
                onClick={mic}
                aria-label="الإدخال الصوتي"
              >
                <Icon n="mic" s={44} w={1.6} />
              </button>
              <div className="grow col gap-3">
                <div className="fs-13 t-2">
                  {listening
                    ? 'بسمعك… قول الكمية'
                    : 'اضغط الميكروفون وقل الكمية للصنف الحالي'}
                </div>
                <div className="row gap-3" style={{ minHeight: 44 }}>
                  {listening && (
                    <div className="wave">
                      {Array.from({ length: 14 }).map((_, i) => (
                        <i key={i} style={{ animationDelay: i * 0.06 + 's' }} />
                      ))}
                    </div>
                  )}
                  <span className="display" style={{ fontSize: 30, fontWeight: 500 }}>
                    {heard ? (
                      `«${heard}»`
                    ) : (
                      <span className="t-3 fs-20">مثال: «اتناشر» ، «خمسة وعشرين»</span>
                    )}
                  </span>
                </div>
                <div className="divider" style={{ height: 1, background: 'var(--line)' }} />
                <div className="row gap-2">
                  <div className="scanbar grow" style={{ height: 48 }}>
                    <span className="scan-ic" style={{ width: 30, height: 30 }}>
                      <Icon n="barcode" s={16} w={2} />
                    </span>
                    <input
                      autoFocus
                      value={code}
                      onChange={(e) => setCode(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && submitCode()}
                      placeholder="امسح باركود الصنف"
                    />
                  </div>
                  <div className="input-group" style={{ width: 110 }}>
                    <input
                      className="input num"
                      style={{
                        height: 48,
                        textAlign: 'center',
                        fontSize: 18,
                        fontWeight: 600,
                      }}
                      value={qty}
                      onChange={(e) => setQty(toAsciiNum(e.target.value))}
                      aria-label="الكمية"
                    />
                  </div>
                  <button className="btn btn-primary" style={{ height: 48 }} onClick={submitCode}>
                    تسجيل
                  </button>
                </div>
                <div className="row gap-2">
                  <Api m="POST" path={`/pos/stocktakes/${session.id}/scan`} />
                  <span className="fs-12 t-3 ltr mono">{'{ barcode, qty | qty_words }'}</span>
                </div>
              </div>
            </div>
            {lp && (
              <div
                className="last-scan"
                key={last.id + '-' + last.qty}
                style={{ animation: 'popIn .3s both' }}
              >
                <PImg p={lp} size="sm" />
                <div className="grow">
                  <div className="fs-12 t-3">
                    آخر تسجيل{' '}
                    {last.via === 'voice' ? (
                      <span className="badge b-acc" style={{ height: 20 }}>
                        <Icon n="mic" s={11} />
                        «{last.words}»
                      </span>
                    ) : (
                      <span className="badge b-neutral" style={{ height: 20 }}>
                        <Icon n="barcode" s={11} />
                        باركود
                      </span>
                    )}
                  </div>
                  <div className="fs-16 fw-5">{lp.name}</div>
                  <div className="mono t-3" style={{ fontSize: 11 }}>
                    {lp.sku}
                  </div>
                </div>
                <div className="col" style={{ alignItems: 'flex-end' }}>
                  <span className="big-qty">{fmt(last.qty)}</span>
                  <span className="fs-12 t-3">العدد الحالي</span>
                </div>
              </div>
            )}
            <div className="card" style={{ overflow: 'hidden' }}>
              <div className="card-head">
                <h3>نطاق الجرد</h3>
                <span className="meta">النظام لا يعرض الرصيد الدفتري أثناء العد</span>
              </div>
              <table className="tbl">
                <thead>
                  <tr>
                    <th>الصنف</th>
                    <th>الكود</th>
                    <th className="n">المعدود</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {scope.map((p) => (
                    <tr key={p.id} className={last.id === p.id ? 'selected' : ''}>
                      <td>
                        <div className="row gap-3">
                          <PImg p={p} size="xs" />
                          <span className="fw-5">{p.name}</span>
                        </div>
                      </td>
                      <td>
                        <span className="mono">{p.sku}</span>
                      </td>
                      <td className="n fs-16 fw-6">
                        {counts[p.id] != null ? fmt(counts[p.id]) : <span className="t-3">—</span>}
                      </td>
                      <td>
                        {counts[p.id] != null ? (
                          <span className="badge b-ok">
                            <span className="dot" />
                            تم العد
                          </span>
                        ) : (
                          <span className="badge b-neutral">لم يُعد</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <div className="card" style={{ position: 'sticky', top: 0 }}>
            <div className="card-head">
              <h3>سجل المسح</h3>
              <span className="meta">آخر {fmt(log.length)}</span>
            </div>
            <div className="col" style={{ padding: '6px 10px 10px' }}>
              {log.map((l, i) => {
                const p = posMockService.getProductById(l.id);
                return (
                  <div
                    key={i}
                    className="row gap-3"
                    style={{
                      padding: '10px 6px',
                      borderBottom: i < log.length - 1 ? '1px solid var(--line)' : 0,
                    }}
                  >
                    <span
                      className="kpi-icon"
                      style={{
                        width: 30,
                        height: 30,
                        background:
                          l.via === 'voice' ? 'var(--acc-soft)' : 'var(--bg-sunken)',
                        color: l.via === 'voice' ? 'var(--acc)' : 'var(--text-2)',
                      }}
                    >
                      <Icon n={l.via === 'voice' ? 'mic' : 'barcode'} s={14} />
                    </span>
                    <div className="grow" style={{ minWidth: 0 }}>
                      <div className="fs-13 fw-5 truncate">{p?.name}</div>
                      <div className="fs-12 t-3">
                        {l.words ? `«${l.words}»` : 'مسح باركود'} ·{' '}
                        <span className="num">{l.t}</span>
                      </div>
                    </div>
                    <b className="num t-ok">+{fmt(l.add)}</b>
                  </div>
                );
              })}
            </div>
            <div style={{ padding: 14, borderTop: '1px solid var(--line)' }}>
              <button
                className="btn btn-secondary"
                style={{ width: '100%' }}
                onClick={() => toast('تم إرسال مسودة الجرد للمراجعة')}
              >
                إنهاء الجرد وإرساله للمراجعة
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}import React from 'react';
import { Icon } from '../ui/Icons';
import { Kbd } from '../ui/SharedUI';
import type { AppScreen, Branch, CashierUser, PosShift } from '../../types/pos.types';

interface PosHeaderProps {
  currentScreen: AppScreen;
  onScreenChange: (s: AppScreen) => void;
  branch: Branch | null;
  cashier: CashierUser | null;
  shift: PosShift | null;
  onOpenCloseShift: () => void;
  onOpenReturns?: () => void;
  isDark: boolean;
  onToggleDark: () => void;
  onLogout?: () => void;
}

export function PosHeader({
  currentScreen,
  onScreenChange,
  branch,
  cashier,
  shift,
  onOpenCloseShift,
  onOpenReturns,
  isDark,
  onToggleDark,
  onLogout,
}: PosHeaderProps) {
  return (
    <header className="ph">
      <div className="brand-mark">
        <Icon n="bag" s={20} w={2} />
      </div>
      <div className="ph-meta">
        <b>الفريد</b>
        <span>{branch?.name || 'فرع مدينة نصر'}</span>
      </div>
      <div className="ph-sep" />
      <nav className="ph-nav" aria-label="شاشات نقطة البيع">
        <button
          aria-current={currentScreen === 'terminal' ? 'page' : undefined}
          onClick={() => onScreenChange('terminal')}
        >
          <Icon n="pos" s={16} />
          <span className="lbl">نقطة البيع</span>
        </button>
        <button
          aria-current={currentScreen === 'stock' ? 'page' : undefined}
          onClick={() => onScreenChange('stock')}
        >
          <Icon n="box" s={16} />
          <span className="lbl">المخزون</span>
        </button>
        <button
          aria-current={currentScreen === 'transfers' ? 'page' : undefined}
          onClick={() => onScreenChange('transfers')}
        >
          <Icon n="truck" s={16} />
          <span className="lbl">التحويلات</span>
        </button>
        <button
          aria-current={currentScreen === 'stocktake' ? 'page' : undefined}
          onClick={() => onScreenChange('stocktake')}
        >
          <Icon n="stock" s={16} />
          <span className="lbl">الجرد</span>
        </button>
      </nav>

      <div className="ms-auto row gap-3">
        <span className="conn" title="حالة الاتصال بالسيرفر">
          <i
            style={{
              width: 7,
              height: 7,
              borderRadius: 99,
              background: 'var(--ok)',
              boxShadow: '0 0 0 2px var(--ok-bg)',
            }}
          />
          متصل
        </span>

        {shift && (
          <button
            className="shift-pill"
            onClick={onOpenCloseShift}
            title="انقر لإغلاق الوردية وجرد النقدية"
          >
            <span className="live" />
            <span>وردية #{shift.shift_number}</span>
            <Icon n="lock" s={13} className="t-3" />
          </button>
        )}

        {onOpenReturns && (
          <button
            className="btn btn-secondary btn-sm"
            onClick={onOpenReturns}
            title="مرتجع / استبدال (F8)"
          >
            <Icon n="ret" s={14} />
            <span>مرتجع</span>
            <Kbd>F8</Kbd>
          </button>
        )}

        <button
          className="icon-btn"
          onClick={onToggleDark}
          aria-label={isDark ? 'الوضع النهاري' : 'الوضع الليلي'}
          title={isDark ? 'الوضع النهاري' : 'الوضع الليلي'}
        >
          <Icon n={isDark ? 'sun' : 'moon'} s={17} />
        </button>

        <div className="ph-sep" />

        <div className="row gap-2" style={{ fontSize: 13 }}>
          <span
            className="avatar"
            style={{ width: 32, height: 32, fontSize: 12, background: 'var(--bg-sunken)' }}
          >
            {cashier?.initials || 'أس'}
          </span>
          <div className="col hide-mobile" style={{ lineHeight: 1.2 }}>
            <span className="fw-6">{cashier?.name || 'أحمد سمير'}</span>
            <span className="fs-12 t-3">{cashier?.role || 'كاشير أول'}</span>
          </div>
          {onLogout && (
            <button
              id="side-logout-btn"
              className="icon-btn"
              onClick={onLogout}
              aria-label="تسجيل الخروج"
              title="تسجيل الخروج"
            >
              <Icon n="logout" s={17} />
            </button>
          )}
        </div>
      </div>
    </header>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, MoneyInput, Api } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PosShift, Treasury, Branch, CashierUser } from '../../types/pos.types';
import { normalizeError } from '../../lib/pos-error';

interface OpenShiftGateProps {
  onOpened: (shift: PosShift) => void;
}

export function OpenShiftGate({ onOpened }: OpenShiftGateProps) {
  const [treasury, setTreasury] = useState<number>(1);
  const [cash, setCash] = useState<string>('500');
  const [busy, setBusy] = useState<boolean>(false);
  const [error, setError] = useState<string>('');
  const [treasuries, setTreasuries] = useState<Treasury[]>([]);
  const [branch, setBranch] = useState<Branch | null>(null);
  const [cashier, setCashier] = useState<CashierUser | null>(null);

  useEffect(() => {
    posMockService.getTreasuries().then((list) => {
      setTreasuries(list);
      const free = list.find((t) => t.state === 'free');
      if (free) {
        setTreasury(free.id);
        if ((free.balance ?? 0) > 0) {
          setCash(String(free.balance));
        }
      }
    });
    posMockService.getBranch().then(setBranch);
    posMockService.getCashier().then(setCashier);
  }, []);

  const selectedDrawer = treasuries.find((t) => t.id === treasury);
  const isBalanceLocked = Boolean(selectedDrawer && (selectedDrawer.balance ?? 0) > 0);

  useEffect(() => {
    if (selectedDrawer && (selectedDrawer.balance ?? 0) > 0) {
      setCash(String(selectedDrawer.balance));
    }
  }, [treasury, selectedDrawer?.balance]);

  const amount = Number(cash || 0);
  const now = new Date();
  const hr = now.getHours();
  const greet = hr < 12 ? 'صباح الخير' : 'مساء الخير';

  const submit = async () => {
    if (!treasury || busy) return;
    setBusy(true);
    setError('');
    try {
      const opened = await posMockService.openShift(treasury, amount);
      onOpened(opened);
    } catch (err: any) {
      const apiErr = normalizeError(err);
      setError(apiErr.message || 'تعذر فتح الوردية');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="gate" data-screen-label="01 Open Shift">
      <div className="gate-card" role="dialog" aria-modal="true" aria-label="فتح الوردية">
        <div className="welcome">
          <div className="row gap-3" style={{ position: 'relative', zIndex: 1 }}>
            <span className="avatar">{cashier?.initials || 'أس'}</span>
            <div className="grow">
              <div style={{ fontSize: 13, opacity: 0.85 }}>{greet}،</div>
              <div className="display" style={{ fontSize: 22, fontWeight: 500, lineHeight: 1.25 }}>
                {cashier?.name || 'أحمد سمير'}
              </div>
            </div>
            <div className="col" style={{ alignItems: 'flex-end', gap: 4 }}>
              <span className="badge" style={{ background: 'rgba(255,255,255,.18)', color: '#fff' }}>
                <Icon n="store" s={13} />
                {branch?.name || 'فرع مدينة نصر'}
              </span>
              <span style={{ fontSize: 12, opacity: 0.85 }} className="num">
                {now.toLocaleDateString('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
            </div>
          </div>
          <div
            className="row gap-2"
            style={{
              position: 'relative',
              zIndex: 1,
              marginTop: 16,
              padding: '10px 12px',
              borderRadius: 12,
              background: 'rgba(0,0,0,.14)',
              fontSize: 12.5,
            }}
          >
            <Icon n="lock" s={15} />
            لا توجد وردية مفتوحة باسمك. افتح وردية لبدء البيع.
          </div>
        </div>

        <div style={{ padding: '20px 24px 8px', display: 'flex', flexDirection: 'column', gap: 18 }}>
          <div className="col gap-2">
            <div className="row between">
              <span className="fs-13 fw-5">درج النقدية</span>
              <span className="fs-12 t-3">
                {treasuries.filter((t) => t.state === 'free').length} متاح في الفرع
              </span>
            </div>
            <div className="tres" role="radiogroup">
              {treasuries.map((t) => (
                <button
                  key={t.id}
                  role="radio"
                  aria-checked={treasury === t.id}
                  disabled={t.state === 'busy'}
                  onClick={() => setTreasury(t.id)}
                >
                  <div className="row between">
                    <Icon
                      n="cash"
                      s={18}
                      style={{ color: treasury === t.id ? 'var(--acc)' : 'var(--text-3)' }}
                    />
                    {t.state === 'busy' ? (
                      <span className="badge b-neutral" style={{ height: 20, fontSize: 11 }}>
                        مشغول
                      </span>
                    ) : (
                      <span className="radio-dot" />
                    )}
                  </div>
                  <div className="fs-13 fw-6">{t.name}</div>
                  <div className="fs-12 t-3 truncate" style={{ lineHeight: 1.3 }}>
                    {t.last}
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="col gap-2">
            <div className="row between">
              <span className="fs-13 fw-5">العهدة الافتتاحية</span>
              {!isBalanceLocked && (
                <button className="fs-12 t-3" onClick={() => setCash('')}>
                  مسح
                </button>
              )}
            </div>
            <MoneyInput
              value={cash}
              onChange={setCash}
              autoFocus={!isBalanceLocked}
              readOnly={isBalanceLocked}
              onEnter={submit}
            />
            {isBalanceLocked ? (
              <div
                className="row gap-2 fs-12"
                style={{
                  padding: '8px 12px',
                  borderRadius: 10,
                  background: 'var(--bg-sunken)',
                  color: 'var(--text-2)',
                }}
              >
                <Icon n="lock" s={14} />
                <span>العهدة يجب أن تساوي رصيد الدرج ({egp(selectedDrawer?.balance ?? 0)} ج)</span>
              </div>
            ) : (
              <div className="denoms">
                {[200, 500, 1000].map((v) => (
                  <button key={v} className="denom" onClick={() => setCash(String(amount + v))}>
                    +{fmt(v)}
                    <small>ج</small>
                  </button>
                ))}
                <button className="denom ghost" onClick={() => setCash('500')}>
                  نفس أمس
                </button>
              </div>
            )}
          </div>
        </div>

        {error && (
          <div
            className="banner b-bad"
            style={{ margin: '0 24px 8px', borderRadius: 12, padding: '10px 14px' }}
          >
            <Icon n="alert" s={16} />
            <span>{error}</span>
          </div>
        )}

        <div style={{ padding: '16px 24px 22px' }}>
          <button
            className="pay-btn"
            style={{ margin: 0, width: '100%' }}
            disabled={!treasury || busy}
            onClick={submit}
          >
            <span className="row gap-2">{busy ? 'جارِ فتح الوردية…' : 'فتح الوردية وبدء البيع'}</span>
            <span className="row gap-2">
              <span className="amt num">{egp(amount)}</span>
              <Icon n="arrowLeft" s={18} />
            </span>
          </button>
          <div className="api-block center" style={{ justifyContent: 'center' }}>
            <Api path="/api/v1/pos/shifts/current" /> <Api m="POST" path="/api/v1/pos/shifts/open" />
          </div>
        </div>
      </div>
    </div>
  );
}import React, { useState } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, cx, toAsciiNum } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PosCartLine } from '../../types/pos.types';

interface CartLineProps {
  l: PosCartLine;
  onQty: (q: number) => void;
  onRemove: () => void;
  onPrice: (price: number) => void;
  canOverride?: boolean;
  flash?: boolean | number | null;
}

export function CartLine({ l, onQty, onRemove, onPrice, canOverride, flash }: CartLineProps) {
  const p = posMockService.getProductById(l.id);
  const [edit, setEdit] = useState(false);
  const [val, setVal] = useState(String(l.price));
  const overridden = l.price !== l.listPrice;

  if (!p) return null;

  return (
    <div className={cx('line', flash ? 'flash' : '', l.error && 'line-bad')}>
      <PImg p={p} size="sm" />
      <div style={{ minWidth: 0 }}>
        <div className="line-name truncate">{p.name}</div>
        <div className="line-sub">
          {edit ? (
            <input
              className="price-input"
              autoFocus
              value={val}
              onChange={(e) => setVal(toAsciiNum(e.target.value))}
              onBlur={() => {
                onPrice(Number(val || l.listPrice));
                setEdit(false);
              }}
              onKeyDown={(e) => {
                if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
                if (e.key === 'Escape') {
                  setVal(String(l.price));
                  setEdit(false);
                }
              }}
            />
          ) : (
            <span
              className={cx('num', canOverride && 'price-edit')}
              onClick={() => {
                if (canOverride) {
                  setVal(String(l.price));
                  setEdit(true);
                }
              }}
              title={canOverride ? 'تعديل السعر (pos.override_price)' : undefined}
            >
              {egp(l.price)} ج
            </span>
          )}
          {overridden && !edit && (
            <>
              <s className="num">{egp(l.listPrice)}</s>
              <span
                className="badge b-warn"
                style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}
              >
                سعر معدّل
              </span>
            </>
          )}
          {l.qty > p.stock && (
            <span
              className="badge b-bad"
              style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}
            >
              الرصيد {fmt(p.stock)}
            </span>
          )}
        </div>
        {l.error && <div className="line-err">{l.error}</div>}
      </div>
      <div className="col" style={{ alignItems: 'flex-end', gap: 6 }}>
        <div className="row gap-1">
          <div className="stepper-q">
            <button onClick={() => onQty(l.qty + 1)} aria-label="زيادة">
              <Icon n="plus" s={14} />
            </button>
            <span>{fmt(l.qty)}</span>
            <button
              onClick={() => (l.qty > 1 ? onQty(l.qty - 1) : onRemove())}
              aria-label="نقص"
            >
              <Icon n="minus" s={14} />
            </button>
          </div>
          <button
            className="icon-btn sm"
            onClick={onRemove}
            aria-label="حذف"
            style={{ color: 'var(--text-3)' }}
          >
            <Icon n="trash" s={15} />
          </button>
        </div>
        <span className="price fs-14">{egp(l.price * l.qty)}</span>
      </div>
    </div>
  );
}import React, { useState, useEffect, useMemo } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Kbd, cx } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import { normAr } from '../../lib/arabic';
import { beepError } from '../../lib/sound';
import type { PosProduct, Customer } from '../../types/pos.types';

interface ScanBarProps {
  products: PosProduct[];
  customer: Customer | null;
  onAdd: (p: PosProduct) => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}

export function ScanBar({ products, customer, onAdd, inputRef }: ScanBarProps) {
  const [q, setQ] = useState('');
  const [hl, setHl] = useState(0);
  const [open, setOpen] = useState(false);

  const results = useMemo(() => {
    const s = normAr(q);
    if (!s) return [];
    return products
      .filter((p) => normAr(p.name).includes(s) || normAr(p.sku).includes(s) || normAr(p.barcode).includes(s))
      .slice(0, 7);
  }, [q, products]);

  useEffect(() => setHl(0), [q]);

  const pick = (p: PosProduct) => {
    onAdd(p);
    setQ('');
    setOpen(false);
  };

  const onKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHl((h) => Math.min(h + 1, results.length - 1));
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHl((h) => Math.max(h - 1, 0));
    }
    if (e.key === 'Enter') {
      const code = normAr(q);
      const exact = products.find((p) => normAr(p.barcode) === code || normAr(p.sku) === code);
      if (exact) {
        pick(exact);
      } else if (results[hl]) {
        pick(results[hl]);
      } else if (code) {
        posMockService
          .lookupByBarcode(code)
          .then((p) => (p ? pick(p) : beepError()))
          .catch(() => beepError());
      }
    }
    if (e.key === 'Escape') {
      setQ('');
      setOpen(false);
    }
  };

  return (
    <div className="scanbar">
      <span className="scan-ic">
        <Icon n="barcode" s={18} w={2} />
      </span>
      <input
        ref={inputRef}
        data-scan-input
        value={q}
        onChange={(e) => {
          setQ(e.target.value);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 150)}
        onKeyDown={onKey}
        placeholder="امسح الباركود أو ابحث بالاسم / الكود (SKU)…"
        aria-label="بحث الأصناف"
      />
      <span className="row gap-1 fs-12 t-3">
        <Kbd>F2</Kbd>
      </span>
      {open && q && (
        <div className="scan-results">
          {results.length === 0 ? (
            <div className="empty" style={{ padding: 24 }}>
              <h4 className="fs-14">لا يوجد صنف مطابق</h4>
              <p>جرّب الباركود الكامل أو جزء من الاسم</p>
            </div>
          ) : (
            results.map((p, i) => (
              <button
                key={p.id}
                className={cx('scan-row', i === hl && 'hl')}
                onMouseDown={() => pick(p)}
                onMouseEnter={() => setHl(i)}
              >
                <PImg p={p} size="xs" />
                <div className="grow">
                  <div className="fs-13 fw-5 truncate">{p.name}</div>
                  <div className="fs-12 t-3 ltr" style={{ textAlign: 'right' }}>
                    <span className="mono">{p.sku}</span> · <span className="mono">{p.barcode}</span>
                  </div>
                </div>
                <span
                  className={cx(
                    'badge',
                    p.stock === 0 ? 'b-bad' : p.stock <= p.reorder ? 'b-warn' : 'b-neutral'
                  )}
                >
                  {p.stock === 0 ? (
                    'نفد'
                  ) : (
                    <>
                      رصيد <b className="num">{fmt(p.stock)}</b>
                    </>
                  )}
                </span>
                <span className="price fs-14">
                  {egp(customer?.tier === 'wholesale' ? p.wholesale : p.price)}
                </span>
              </button>
            ))
          )}
          <div
            className="row between fs-12 t-3"
            style={{ padding: '8px 10px 4px', borderTop: '1px solid var(--line)', marginTop: 4 }}
          >
            <span className="row gap-1">
              <Kbd>↑</Kbd>
              <Kbd>↓</Kbd> تنقّل <Kbd>Enter</Kbd> إضافة
            </span>
            <Api
              path={`/pos/products/lookup?q=…${customer ? '&customer_id=' + customer.id : ''}`}
            />
          </div>
        </div>
      )}
    </div>
  );
}export const toCents = (v: string | number | null | undefined): number => Math.round(Number(v ?? 0) * 100);
export const fromCents = (c: number): number => c / 100;
export const toApi = (c: number): string => (c / 100).toFixed(2);

/** Proportional "largest remainder" split so the discounts add up to the exact cent. */
export function spreadDiscount(lines: { id: number; totalC: number }[], discountC: number): { id: number; d: number }[] {
  const sum = lines.reduce((s, l) => s + l.totalC, 0);
  if (!sum || !discountC) return lines.map((l) => ({ id: l.id, d: 0 }));
  const raw = lines.map((l) => ({ id: l.id, exact: (discountC * l.totalC) / sum }));
  const out = raw.map((r) => ({ id: r.id, d: Math.floor(r.exact), frac: r.exact - Math.floor(r.exact) }));
  let rest = discountC - out.reduce((s, o) => s + o.d, 0);
  [...out].sort((a, b) => b.frac - a.frac).forEach((o) => {
    if (rest-- > 0) o.d += 1;
  });
  return out.map(({ id, d }) => ({ id, d }));
}

/** Highest invoice discount (in cents) allowed by max_discount_percent. */
export const maxDiscountAmount = (subtotalC: number, percent: number): number => Math.floor((subtotalC * percent) / 100);import { normalizeError, PosApiError } from './pos-error';

export interface PendingSaleDraft {
  hash: string;
  key: string;
  payload: any;
  created_at?: number;
  owner?: string;
  submitted?: boolean;
}

export interface PendingSaleOptions {
  storage?: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;
  retryDelays?: number[];
  storageKey?: string;
  owner?: string;
  sleep?: (ms: number) => Promise<void>;
}

const defaultSleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
const defaultUuid = () => globalThis.crypto.randomUUID();

export function createPendingSaleManager(opts: PendingSaleOptions = {}) {
  const storage = opts.storage ?? (typeof window !== 'undefined' ? window.localStorage : undefined);
  const keyName = opts.storageKey ?? 'pos-pending-sale';
  const delays = opts.retryDelays ?? [1000, 3000, 6000];
  const sleep = opts.sleep ?? defaultSleep;

  const getSaved = (): PendingSaleDraft | null => {
    if (!storage) return null;
    try {
      const raw = storage.getItem(keyName);
      const draft = raw ? JSON.parse(raw) : null;
      // Older checkout previews included a timestamp and items with only a local id.
      if (draft?.payload?.t !== undefined && draft.payload.payment_method === undefined) return null;
      return draft;
    } catch {
      return null;
    }
  };

  const clear = (): void => {
    storage?.removeItem(keyName);
  };

  const prepare = (payload: any): PendingSaleDraft => {
    const hash = JSON.stringify(payload);
    const existing = getSaved();
    if (existing) {
      if (existing.owner === opts.owner && existing.hash === hash) return existing;
      throw new PosApiError(409, 'يجب تأكيد الفاتورة المعلقة أولًا', 'pending_sale');
    }
    const draft: PendingSaleDraft = {
      hash,
      key: defaultUuid(),
      payload,
      created_at: Date.now(),
      owner: opts.owner,
    };
    storage?.setItem(keyName, JSON.stringify(draft));
    return draft;
  };

  const executeWithRetry = async <T>(
    payload: any,
    idempotencyKey: string,
    sendFn: (payload: any, key: string) => Promise<T>,
    onRetrying?: (attempt: number, delayMs: number) => void,
  ): Promise<T> => {
    const existing = getSaved();
    if (existing && (existing.owner !== opts.owner || existing.key !== idempotencyKey || existing.hash !== JSON.stringify(payload))) {
      throw new PosApiError(409, 'تعذر تأكيد الفاتورة خارج الوردية التي أُرسلت منها', 'pending_sale');
    }

    // A reload during the request must treat its result as unknown.
    let uncertain = existing?.submitted === true;
    storage?.setItem(
      keyName,
      JSON.stringify({
        hash: JSON.stringify(payload),
        key: idempotencyKey,
        payload,
        created_at: Date.now(),
        owner: opts.owner,
        submitted: true,
      })
    );

    let lastError: any = null;

    for (let attempt = 0; attempt <= delays.length; attempt++) {
      try {
        const result = await sendFn(payload, idempotencyKey);
        clear();
        return result;
      } catch (err: any) {
        const apiErr = normalizeError(err);
        lastError = apiErr;

        // Only retry status 0 (network abort, timeout, disconnected)
        const isNetworkFailure = apiErr.status === 0 || apiErr.code === 'network';
        uncertain ||= isNetworkFailure || apiErr.status === 408 || apiErr.status >= 500 || apiErr.retryable;
        if (isNetworkFailure && attempt < delays.length) {
          const delayMs = delays[attempt];
          onRetrying?.(attempt + 1, delayMs);
          await sleep(delayMs);
          continue;
        }

        // A rejection of this request cannot rule out an earlier commit.
        if (!uncertain && apiErr.status >= 400 && apiErr.status < 500) {
          clear();
        }
        throw apiErr;
      }
    }

    throw lastError ?? new PosApiError(0, 'انقطع الاتصال بالسيرفر', 'network');
  };

  return {
    getSaved,
    clear,
    prepare,
    executeWithRetry,
  };
}import type {
  Customer,
  PastSale,
  PosHeldSale,
  PosProduct,
  PosShift,
  QuoteResult,
  StockTransfer,
  TransferSource,
} from '../types/pos.types';

const SHIFT_STATUS = { open: 'open', closed_pending_approval: 'pending_approval', approved: 'closed' } as const;

export const mapShift = (s: any): PosShift => ({
  ...s,
  status: SHIFT_STATUS[s.status as keyof typeof SHIFT_STATUS] ?? 'open',
  treasury_id: Number(s.treasury_id ?? s.treasury?.id),
  treasury: s.treasury ? { state: 'busy', last: '', ...s.treasury } : s.treasury,
  branch_id: s.branch_id ?? s.branch?.id,
  opening_cash: Number(s.opening_cash ?? 0),
  cash_sales_total: Number(s.cash_sales_total ?? 0),
  card_sales_total: Number(s.card_sales_total ?? 0),
  cash_returns_total: Number(s.cash_returns_total ?? 0),
  cash_expenses_total: Number(s.cash_expenses_total ?? 0),
  expected_closing_cash: Number(s.expected_closing_cash ?? 0),
  actual_closing_cash: s.actual_closing_cash == null ? null : Number(s.actual_closing_cash),
  cash_difference: s.cash_difference == null ? null : Number(s.cash_difference),
  opened_at: new Date(s.opened_at),
  closed_at: s.closed_at ? new Date(s.closed_at) : null,
});

export const mapProduct = (p: any): PosProduct => ({
  id: Number(p.id),
  sku: p.sku ?? '',
  barcode: p.barcode ?? '',
  name: p.name ?? [p.product_name, p.variant_name].filter(Boolean).join(' - '),
  cat: p.category_id != null ? String(p.category_id) : 'all',
  price: Number(p.unit_price ?? 0),
  wholesale: Number(p.wholesale_price ?? p.unit_price ?? 0),
  stock: Number(p.available ?? p.on_hand ?? 0),
  reorder: Number(p.reorder_point ?? 0),
  h: (Number(p.id) * 47) % 360, // placeholder-art hue
});

const timeAr = (iso?: string) =>
  new Date(iso ?? Date.now()).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

export const mapHeld = (h: any): PosHeldSale => ({
  ref: h.hold_reference,
  at: timeAr(h.created_at),
  mins: Math.max(0, Math.floor((Date.now() - +new Date(h.created_at ?? Date.now())) / 60000)),
  customer: h.customer?.name ?? null,
  note: h.notes ?? '',
  items: (h.items_payload ?? []).map((i: any) => ({ id: Number(i.product_variant_id ?? i.id), qty: Number(i.qty) })),
  serverId: Number(h.id),
  _id: Number(h.id),
});

export const mapCustomer = (c: any): Customer => ({
  id: Number(c.id),
  name: c.name,
  phone: c.phone ?? '',
  tier: c.type === 'wholesale' ? 'wholesale' : 'retail',
  points: Number(c.points ?? c.loyalty_points ?? 0),
});

const METHOD_AR: Record<string, string> = { cash: 'نقدي', card: 'بطاقة', mixed: 'مختلط' };

/** Prices shown for returns are net_unit_price (after line discount), never list price. */
export const mapPastSale = (s: any): PastSale => ({
  id: Number(s.id),
  number: s.order_number,
  date:
    new Date(s.created_at).toLocaleDateString('ar-EG', { day: 'numeric', month: 'long', year: 'numeric' }) +
    ` — ${timeAr(s.created_at)}`,
  cashier: s.cashier?.name ?? '',
  customer: s.customer?.name ?? 'عميل نقدي',
  customer_id: s.customer?.id == null ? null : Number(s.customer.id),
  method: METHOD_AR[s.payment_method] ?? s.payment_method ?? '',
  cash_amount: Number(s.cash_amount ?? 0),
  card_amount: Number(s.card_amount ?? 0),
  items: (s.items ?? []).map((i: any) => ({
    id: Number(i.product_variant_id),
    qty: Number(i.qty),
    price: Number(i.net_unit_price ?? i.unit_price ?? 0),
    net_unit_price: Number(i.net_unit_price ?? i.unit_price ?? 0),
    returnable_qty: Number(i.returnable_qty ?? i.qty),
  })),
});

/** `id` is the variant id (what screens render by); `transferItemId` is what receive needs. */
export const mapTransfer = (t: any): StockTransfer => ({
  id: Number(t.id),
  number: t.transfer_number,
  from: t.from_branch?.name ?? '',
  status: (t.status as StockTransfer['status']) ?? 'shipped',
  shipped: t.shipped_at ? `${new Date(t.shipped_at).toLocaleDateString('ar-EG')} ${timeAr(t.shipped_at)}` : '',
  driver: '',
  items: (t.items ?? []).map((i: any) => ({
    id: Number(i.product_variant_id),
    qty: Number(i.shipped_qty ?? i.requested_qty ?? 0),
    transferItemId: Number(i.id),
  })),
});

export const mapTransferSource = (s: any): TransferSource => ({
  id: Number(s.id),
  name: s.name,
  kind: s.type === 'warehouse' ? 'warehouse' : 'store',
});

export const mapQuote = (q: any): QuoteResult => ({
  lines: (q.lines ?? []).map((l: any) => ({
    product_variant_id: Number(l.product_variant_id),
    qty: Number(l.qty),
    unit_price: Number(l.unit_price),
    discount_amount: Number(l.discount_amount),
    line_total: Number(l.line_total),
    available: Number(l.available),
    error: l.error ?? null,
  })),
  subtotal: Number(q.subtotal),
  discount_total: Number(q.discount_total),
  grand_total: Number(q.grand_total),
});import React, { useState, useEffect, useRef } from 'react';
import { usePosCartStore } from '../stores/pos-cart.store';
import { usePosShiftStore } from '../stores/pos-shift.store';
import { Button, Input, Modal, Badge } from '@alfarid/ui';
import { useBranding } from '@alfarid/ui/branding';
import { formatCurrency } from '@alfarid/utils';
import { Barcode, Trash2, Plus, Minus, CreditCard, Banknote, ShoppingCart, Clock } from 'lucide-react';

export function CashierScreen() {
  const { branding } = useBranding();
  const { currentShift } = usePosShiftStore();
  const { items, addItem, updateQuantity, removeItem, clearCart, total, subtotal } = usePosCartStore();
  const [barcodeInput, setBarcodeInput] = useState('');
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  // Sample quick products for the cashier touch/click layout
  const quickProducts = [
    { id: 101, barcode: '6221001', name: 'شنطة يد كلاسيك جلد أسود', price: 650 },
    { id: 102, barcode: '6221002', name: 'شنطة كروس نسائي بيج', price: 420 },
    { id: 103, barcode: '6221003', name: 'محفظة رجالي جلد طبيعي', price: 180 },
    { id: 104, barcode: '6221004', name: 'شنطة ظهر سفر وتربروف', price: 850 },
    { id: 105, barcode: '6221005', name: 'حزام جلد طبيعي بني', price: 150 },
    { id: 106, barcode: '6221006', name: 'حقيبة لابتوب 15.6 بوصة', price: 550 },
  ];

  useEffect(() => {
    barcodeInputRef.current?.focus();
  }, []);

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput.trim()) return;
    const found = quickProducts.find((p) => p.barcode === barcodeInput.trim());
    if (found) {
      addItem(found);
    } else {
      addItem({
        id: Date.now(),
        barcode: barcodeInput.trim(),
        name: `صنف باركود (${barcodeInput.trim()})`,
        price: 250,
      });
    }
    setBarcodeInput('');
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-zinc-100 font-sans" dir="rtl">
      {/* Left/Main Side: Product Catalogue & Barcode Scanner */}
      <div className="flex-1 flex flex-col p-4 border-l border-zinc-200">
        {/* Top Shift Status Bar */}
        <div className="h-14 bg-white rounded-xl shadow-sm px-4 flex items-center justify-between mb-4 border border-zinc-200">
          <div className="flex items-center gap-4">
            <span dir="auto" className="font-bold text-zinc-800 text-lg truncate">{branding.name} POS</span>
            <span className="text-zinc-400">|</span>
            <span className="text-sm text-zinc-600 font-medium">{currentShift?.branchName}</span>
            <Badge variant="success">الوردية #{currentShift?.id} مفتوحة</Badge>
          </div>
          <div className="flex items-center gap-3 text-sm text-zinc-500">
            <Clock className="w-4 h-4" />
            <span>الكاشير: <strong>{currentShift?.cashierName}</strong></span>
          </div>
        </div>

        {/* Barcode scanner input */}
        <form onSubmit={handleBarcodeSubmit} className="mb-4">
          <div className="relative">
            <Barcode className="absolute right-3.5 top-3 w-5 h-5 text-zinc-400" />
            <input
              ref={barcodeInputRef}
              type="text"
              value={barcodeInput}
              onChange={(e) => setBarcodeInput(e.target.value)}
              placeholder="امسح الباركود أو اضغط Enter (F2 للتركيز)..."
              className="w-full h-11 pr-11 pl-4 rounded-xl border border-zinc-300 bg-white shadow-sm text-sm focus:border-brand-500 focus:outline-none focus:ring-2 focus:ring-brand-500/20"
            />
          </div>
        </form>

        {/* Fast product grid */}
        <div className="flex-1 overflow-y-auto">
          <h3 className="text-xs font-semibold text-zinc-500 uppercase mb-3">الأصناف السريعة الأكثر مبيعاً</h3>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {quickProducts.map((product) => (
              <button
                key={product.id}
                onClick={() => addItem(product)}
                className="bg-white p-4 rounded-xl border border-zinc-200 shadow-sm hover:border-brand-500 hover:shadow transition-all text-right flex flex-col justify-between h-28"
              >
                <div>
                  <h4 className="font-semibold text-zinc-900 text-sm line-clamp-2">{product.name}</h4>
                  <span className="text-xs text-zinc-400 font-mono">{product.barcode}</span>
                </div>
                <div className="text-brand-600 font-bold text-base">{formatCurrency(product.price)}</div>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Right Side: Cart, Totals & Quick Actions */}
      <div className="w-96 bg-white flex flex-col shadow-lg border-r border-zinc-200">
        <div className="p-4 border-b border-zinc-200 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="w-5 h-5 text-brand-600" />
            <h2 className="font-bold text-zinc-800">فاتورة البيع الحالية</h2>
          </div>
          {items.length > 0 && (
            <button
              onClick={clearCart}
              className="text-xs text-red-600 hover:text-red-700 font-medium"
            >
              مسح السلة
            </button>
          )}
        </div>

        {/* Cart items list */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {items.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-zinc-400 text-sm">
              <ShoppingCart className="w-12 h-12 stroke-1 mb-2 text-zinc-300" />
              <span>السلة فارغة</span>
              <span className="text-xs text-zinc-400 mt-1">امسح الباركود للبدء</span>
            </div>
          ) : (
            items.map((item) => (
              <div
                key={item.id}
                className="p-3 bg-zinc-50 rounded-xl border border-zinc-200 flex flex-col gap-2"
              >
                <div className="flex justify-between items-start">
                  <span className="font-medium text-sm text-zinc-800 leading-snug">{item.name}</span>
                  <button
                    onClick={() => removeItem(item.id)}
                    className="text-zinc-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                <div className="flex items-center justify-between text-xs text-zinc-500">
                  <span>{formatCurrency(item.price)} × {item.quantity}</span>
                  <span className="font-bold text-sm text-zinc-900">
                    {formatCurrency(item.price * item.quantity)}
                  </span>
                </div>
                <div className="flex items-center justify-end gap-2 mt-1">
                  <button
                    onClick={() => updateQuantity(item.id, -1)}
                    className="w-7 h-7 rounded-lg bg-white border border-zinc-300 flex items-center justify-center hover:bg-zinc-100"
                  >
                    <Minus className="w-3.5 h-3.5" />
                  </button>
                  <span className="font-bold text-sm w-6 text-center">{item.quantity}</span>
                  <button
                    onClick={() => updateQuantity(item.id, 1)}
                    className="w-7 h-7 rounded-lg bg-white border border-zinc-300 flex items-center justify-center hover:bg-zinc-100"
                  >
                    <Plus className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Totals & Checkout Button */}
        <div className="p-4 border-t border-zinc-200 bg-zinc-50/70 space-y-3">
          <div className="flex justify-between text-sm text-zinc-600">
            <span>المجموع الفرعي:</span>
            <span>{formatCurrency(subtotal())}</span>
          </div>
          <div className="flex justify-between text-lg font-bold text-zinc-900 border-t border-zinc-200 pt-2">
            <span>الإجمالي النهائي:</span>
            <span className="text-brand-600">{formatCurrency(total())}</span>
          </div>

          <Button
            className="w-full h-12 text-base font-bold shadow-md"
            disabled={items.length === 0}
            onClick={() => setIsPaymentOpen(true)}
          >
            إتمام الدفع وطباعة الفاتورة (Space)
          </Button>
        </div>
      </div>

      {/* Payment Modal */}
      <Modal
        isOpen={isPaymentOpen}
        onClose={() => setIsPaymentOpen(false)}
        title="طريقة الدفع وإغلاق الفاتورة"
      >
        <div className="space-y-4">
          <div className="text-center py-4 bg-zinc-50 rounded-xl">
            <span className="text-xs text-zinc-500">المبلغ المطلوب سداده</span>
            <div className="text-3xl font-extrabold text-brand-600 mt-1">{formatCurrency(total())}</div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={() => {
                clearCart();
                setIsPaymentOpen(false);
              }}
              className="p-4 border-2 border-brand-500 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-brand-50 transition-colors"
            >
              <Banknote className="w-8 h-8 text-brand-600" />
              <span className="font-bold text-sm">نقدي (كاش)</span>
            </button>
            <button
              onClick={() => {
                clearCart();
                setIsPaymentOpen(false);
              }}
              className="p-4 border-2 border-zinc-200 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-zinc-50 transition-colors"
            >
              <CreditCard className="w-8 h-8 text-zinc-600" />
              <span className="font-bold text-sm">فيزا / كارت</span>
            </button>
          </div>
        </div>
      </Modal>
    </div>
  );
}import React from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { PosApp } from './components/PosApp';
import { ToastHost } from './components/ui/SharedUI';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 10,
      refetchOnWindowFocus: false,
    },
  },
});

export function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ToastHost>
        <PosApp />
      </ToastHost>
    </QueryClientProvider>
  );
