  --acc: #e0491f;
  --acc-hover: #c93d16;
  --acc-2: #f37c59;
  --acc-soft: #fdebe5;
  --acc-tint: #fff7f4;
  /* Semantic */
  --ok: #15803d;   --ok-bg: #e3f6e9;
  --warn: #b45309; --warn-bg: #fdf1d8;
  --bad: #d61f45;  --bad-bg: #fde7ec;
  --info: #4338ca; --info-bg: #e7e9fd;
  --neutral-bg: rgba(24, 21, 28, 0.06);
  /* Elevation */
  --sh-1: 0 1px 2px rgba(24, 21, 28, 0.04);
  --sh-2: 0 4px 14px -6px rgba(24, 21, 28, 0.12), 0 1px 2px rgba(24, 21, 28, 0.04);
  --sh-pop: 0 20px 48px -16px rgba(24, 21, 28, 0.28), 0 2px 6px rgba(24, 21, 28, 0.06);
  --overlay: rgba(24, 21, 28, 0.36);
  --ring: 0 0 0 3px rgba(224, 73, 31, 0.22);
  --hatch: repeating-linear-gradient(-45deg, var(--acc) 0 2.5px, var(--acc-2) 2.5px 5px);
  --hatch-track: repeating-linear-gradient(-60deg, rgba(24,21,28,.13) 0 1.5px, transparent 1.5px 5px);
  color-scheme: light;
}
.theme-dark {
  --bg-canvas: #0f0d12;
  --bg-card: #18151b;
  --bg-sunken: #1d1a21;
  --bg-hover: #242029;
  --bg-active: #2c2732;
  --bg-ink: #f5f3f7;
  --on-ink: #141117;
  --text-1: #f5f3f7;
  --text-2: #a39eaa;
  --text-3: #6f6a76;
  --line: rgba(255, 255, 255, 0.07);
  --line-strong: rgba(255, 255, 255, 0.13);
  --acc: #ec5a2f;
  --acc-hover: #f26c43;
  --acc-soft: rgba(236, 90, 47, 0.16);
  --acc-tint: rgba(236, 90, 47, 0.07);
  --ok: #4ade80;   --ok-bg: rgba(22, 101, 52, 0.35);
  --warn: #fbbf24; --warn-bg: rgba(120, 53, 15, 0.4);
  --bad: #fb7185;  --bad-bg: rgba(136, 19, 55, 0.4);
  --info: #a5b4fc; --info-bg: rgba(49, 46, 129, 0.45);
  --neutral-bg: rgba(255, 255, 255, 0.07);
  --sh-1: none;
  --sh-2: 0 4px 14px -6px rgba(0, 0, 0, 0.5);
  --sh-pop: 0 20px 48px -12px rgba(0, 0, 0, 0.7);
  --overlay: rgba(0, 0, 0, 0.6);
  --hatch-track: repeating-linear-gradient(-60deg, rgba(255,255,255,.14) 0 1.5px, transparent 1.5px 5px);
  color-scheme: dark;
}

/* Type scale: 12 / 13 / 14 / 16 / 20 / 26 / 32 */
:root {
  --f-body: 'IBM Plex Sans Arabic', system-ui, sans-serif;
  --f-display: 'Readex Pro', 'IBM Plex Sans Arabic', sans-serif;
  --r-sm: 8px; --r-md: 12px; --r-lg: 18px; --r-xl: 24px;
}
* { box-sizing: border-box; -webkit-font-smoothing: antialiased; }
html, body { margin: 0; padding: 0; }
body { font-family: var(--f-body); font-size: 14px; line-height: 1.55; background: var(--bg-canvas); color: var(--text-1); }
button, input, select, textarea { font: inherit; color: inherit; }
button { background: none; border: 0; padding: 0; cursor: pointer; }
h1, h2, h3, h4 { margin: 0; font-family: var(--f-display); font-weight: 500; letter-spacing: -0.01em; }
p { margin: 0; }
a { color: inherit; text-decoration: none; }
.num, bdi.num { font-family: var(--f-display); font-variant-numeric: tabular-nums; }
.ltr { direction: ltr; unicode-bidi: isolate; }
.mono { font-family: ui-monospace, 'SF Mono', Menlo, monospace; font-size: 12px; letter-spacing: 0; }
.t-1 { color: var(--text-1); } .t-2 { color: var(--text-2); } .t-3 { color: var(--text-3); }
.t-acc { color: var(--acc); } .t-ok { color: var(--ok); } .t-bad { color: var(--bad); } .t-warn { color: var(--warn); }
.fs-12 { font-size: 12px; } .fs-13 { font-size: 13px; } .fs-14 { font-size: 14px; } .fs-16 { font-size: 16px; }
.fs-20 { font-size: 20px; } .fs-26 { font-size: 26px; } .fs-32 { font-size: 32px; }
.fw-5 { font-weight: 500; } .fw-6 { font-weight: 600; } .fw-7 { font-weight: 700; }
.display { font-family: var(--f-display); }
:focus-visible { outline: none; box-shadow: var(--ring); border-radius: 8px; }
::selection { background: var(--acc-soft); }
::-webkit-scrollbar { width: 8px; height: 8px; }
