::-webkit-scrollbar-track { background: transparent; }

/* Layout helpers */
.row { display: flex; align-items: center; }
.col { display: flex; flex-direction: column; }
.gap-1 { gap: 4px; } .gap-2 { gap: 8px; } .gap-3 { gap: 12px; } .gap-4 { gap: 16px; } .gap-5 { gap: 20px; } .gap-6 { gap: 24px; }
.wrap { flex-wrap: wrap; } .grow { flex: 1; min-width: 0; } .ms-auto { margin-inline-start: auto; }
.between { justify-content: space-between; } .center { justify-content: center; }
.stack > * + * { margin-top: 20px; }
.grid { display: grid; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ---------- Card ---------- */
.card { background: var(--bg-card); border: 1px solid var(--line); border-radius: var(--r-lg); box-shadow: var(--sh-1); }
.card-pad { padding: 20px; }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 20px; border-bottom: 1px solid var(--line); min-height: 60px; }
.card-head h3 { font-size: 16px; font-weight: 500; }
.card-head .meta { font-size: 12px; color: var(--text-3); }
.sunken { background: var(--bg-sunken); border-radius: var(--r-md); }

/* ---------- Buttons ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 16px; border-radius: var(--r-md); font-size: 13px; font-weight: 600; white-space: nowrap; border: 1px solid transparent; transition: background-color .15s, border-color .15s, color .15s, transform .08s, opacity .15s; user-select: none; }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled, .btn[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.btn-sm { height: 32px; padding: 0 12px; font-size: 12px; gap: 6px; border-radius: 10px; }
.btn-lg { height: 48px; padding: 0 22px; font-size: 14px; }
.btn-primary { background: var(--bg-ink); color: var(--on-ink); }
.btn-primary:hover:not(:disabled) { opacity: .88; }
.btn-accent { background: var(--acc); color: #fff; }
