};import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Kbd, MoneyInput, Field, cx, useEsc } from '../ui/SharedUI';
import { ReceiptDone } from './ReceiptDone';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PosCartLine, Customer, Branch, CashierUser, QuoteResult } from '../../types/pos.types';
import { toCents, fromCents } from '../../lib/money';
import { buildCheckoutPayload } from '../../lib/checkout';
import { createPendingSaleManager } from '../../lib/pending-sale';
import { pushReceipt, type ArchivedReceipt } from '../../lib/receipt-archive';
import { normalizeError } from '../../lib/pos-error';

interface CheckoutModalProps {
  open: boolean;
  onClose: () => void;
  cart: PosCartLine[];
  customer: Customer | null;
  quote: QuoteResult | null;
  isQuoting: boolean;
  onPaid: () => void;
  onAttemptSettled: () => void;
  pendingOwner: string | undefined;
  branch?: Branch | null;
  cashier?: CashierUser | null;
}

export function CheckoutModal({
  open,
  onClose,
  cart,
  customer,
  quote,
  isQuoting,
  onPaid,
  onAttemptSettled,
  pendingOwner,
  branch,
  cashier,
}: CheckoutModalProps) {
  const [method, setMethod] = useState<'cash' | 'card' | 'mixed'>('cash');
  const [received, setReceived] = useState<string>('');
  const [cashPart, setCashPart] = useState<string>('');
  const [notes, setNotes] = useState<string>('');
  const [cardDigits, setCardDigits] = useState<string>('');
  const [stage, setStage] = useState<'pay' | 'sending' | 'done'>('pay');
  const [retryStatus, setRetryStatus] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [idem, setIdem] = useState<string>('');
  const [receipt, setReceipt] = useState<ArchivedReceipt | null>(null);

  const isSubmittingRef = useRef(false);

  const subtotal = quote?.subtotal ?? 0;
  const discount = quote?.discount_total ?? 0;
  const totalCents = toCents(quote?.grand_total);
  const total = fromCents(totalCents);

  useEffect(() => {
    if (open) {
      setMethod('cash');
      setReceived('');
      setCashPart('');
      setNotes('');
      setCardDigits('');
      setStage('pay');
      setRetryStatus('');
      setErrorMsg('');
      setIdem('');
      setReceipt(null);
    }
  }, [open]);

  useEffect(() => {
    if (!open || stage !== 'pay') return;
    const h = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === 'TEXTAREA' || (e.target as HTMLElement).tagName === 'INPUT') return;
      if (e.key === 'F1') {
        e.preventDefault();
        setMethod('cash');
      }
      if (e.key === 'F3') {
        e.preventDefault();
        setMethod('card');
      }
      if (e.key === 'F4') {
        e.preventDefault();
        setMethod('mixed');
      }
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, [open, stage]);

  useEsc(() => stage !== 'sending' && onClose(), open);
  if (!open) return null;

  const receivedCents = toCents(received);
  const cashCents = Math.min(toCents(cashPart), totalCents);
  const rec = fromCents(receivedCents);
  const change = fromCents(receivedCents - totalCents);
  const cashA = fromCents(cashCents);
  const cardA = fromCents(totalCents - cashCents);

  const valid = quote && !isQuoting && quote.lines.length > 0 && !quote.lines.some((line) => line.error) && (
    method === 'card' ||
    (method === 'cash' && receivedCents >= totalCents) ||
    (method === 'mixed' && cashCents > 0 && cashCents < totalCents)
  );

  const roundUps = [
    ...new Set([
      total,
      Math.ceil(total / 50) * 50,
      Math.ceil(total / 100) * 100,
      Math.ceil(total / 200) * 200,
      Math.ceil(total / 500) * 500,
    ]),
  ]
    .filter((v) => v >= total)
    .slice(0, 4);

  const press = (k: string) => {
    const set = method === 'mixed' ? setCashPart : setReceived;
    const cur = method === 'mixed' ? cashPart : received;
    if (k === '⌫') set(cur.slice(0, -1));
    else if (k === '.') {
      if (!cur.includes('.')) set((cur || '0') + '.');
    } else set(cur + k);
  };

  const confirm = async () => {
    if (!pendingOwner || !quote || !valid || stage !== 'pay' || isSubmittingRef.current) return;
    isSubmittingRef.current = true;
    setStage('sending');
    setRetryStatus('');
    setErrorMsg('');

    const finalNotes = (method === 'card' || method === 'mixed') && cardDigits.trim()
      ? (notes.trim() ? `كارت ****${cardDigits.trim()} · ${notes.trim()}` : `كارت ****${cardDigits.trim()}`)
      : notes.trim();

    const payload = buildCheckoutPayload(quote, {
      customerId: customer?.id ?? null,
      method,
      cashCents,
      overridePrice: cart.some((line) => line.manualPrice),
      notes: finalNotes,
    });

    try {
      const pendingManager = createPendingSaleManager({ owner: pendingOwner });
      const draft = pendingManager.prepare(payload);
      setIdem(draft.key);
      const res = await pendingManager.executeWithRetry(
        draft.payload,
        draft.key,
        (p, k) => posMockService.createSale(p, k),
        (attempt) => {
          setRetryStatus(`جاري التأكد… (محاولة ${attempt})`);
        }
      );

      const completedReceipt = {
        invoiceNumber: res.invoiceNumber,
        total,
        method,
        received: rec,
        change,
        cashA,
        cardA,
        cart,
        customer,
        discount,
        notes: finalNotes,
        branch,
        cashier,
        timestamp: Date.now(),
      };
      pushReceipt(completedReceipt);
      setReceipt(completedReceipt);
      setStage('done');
      onPaid();
    } catch (err: any) {
      const apiErr = normalizeError(err);
      setErrorMsg(apiErr.status === 0 ? 'لم يتأكد تسجيل الفاتورة بعد. أعد المحاولة لتأكيدها.' : apiErr.message);
      setStage('pay');
    } finally {
      isSubmittingRef.current = false;
      onAttemptSettled();
    }
  };

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={() => stage === 'pay' && onClose()} />
      <div
        className="modal"
        style={{ width: 'min(960px, calc(100vw - 32px))' }}
        data-screen-label="05 Checkout"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          {stage !== 'done' ? (
            <div className="co">
              <div className="co-main">
                <div className="row between">
                  <h3 className="fs-16">الدفع وطرق التحصيل</h3>
                  <button className="icon-btn sm" disabled={stage === 'sending'} onClick={onClose} aria-label="إغلاق">
                    <Icon n="x" s={16} />
                  </button>
                </div>
                <div className="due">
                  <div className="col gap-1">
                    <span className="fs-13 t-2">المطلوب سداده</span>
                    <span className="v">
                      {egp(total)}
                      <small>ج.م</small>
                    </span>
                  </div>
                  {customer && (
                    <span className="badge b-neutral">
                      <Icon n="users" s={13} />
                      {customer.name}
                    </span>
                  )}
                </div>
                <div className="methods" role="radiogroup">
                  {(
                    [
                      ['cash', 'نقدي', 'cash', 'F1'],
                      ['card', 'بطاقة / فيزا', 'card', 'F3'],
                      ['mixed', 'دفع مختلط', 'split', 'F4'],
                    ] as const
                  ).map(([v, l, ic, k]) => (
                    <button
                      key={v}
                      role="radio"
                      className="method"
                      aria-checked={method === v}
                      onClick={() => setMethod(v)}
                    >
                      <Kbd>{k}</Kbd>
                      <Icon n={ic} s={24} w={1.6} />
                      {l}
                    </button>
                  ))}
                </div>

                {method === 'cash' && (
                  <div className="grid" style={{ gridTemplateColumns: '1fr 220px', gap: 16 }}>
                    <div className="col gap-3">
                      <span className="fs-13 fw-5">المبلغ المستلم من العميل</span>
                      <MoneyInput
                        value={received}
                        onChange={setReceived}
                        autoFocus
                        placeholder={String(total)}
                        onEnter={confirm}
                      />
                      <div className="denoms">
                        {roundUps.map((v, i) => (
                          <button
                            key={v}
                            className="denom"
                            onClick={() => setReceived(String(v))}
                          >
                            {i === 0 && v === total ? (
                              <span className="fs-13" style={{ fontFamily: 'var(--f-body)' }}>
                                المبلغ بالضبط
                              </span>
                            ) : (
                              <>
                                {fmt(v)}
                                <small>ج</small>
                              </>
                            )}
                          </button>
                        ))}
                      </div>
                      <div className={cx('change', change < 0 && received && 'neg')}>
                        <span className="col">
                          <span className="fs-12" style={{ opacity: 0.75 }}>
                            {change < 0 && received
                              ? 'المبلغ غير كافٍ — متبقٍ'
                              : 'المتبقي للعميل (الفكة)'}
                          </span>
                        </span>
                        <span className="v">
                          {received ? egp(Math.abs(change)) : '٠'}
                          <small className="fs-13" style={{ opacity: 0.6, marginInlineStart: 4 }}>
                            ج
                          </small>
                        </span>
                      </div>
                    </div>
                    <div className="keypad">
                      {['7', '8', '9', '4', '5', '6', '1', '2', '3', '.', '0', '⌫'].map((k) => (
                        <button key={k} onClick={() => press(k)}>
                          {k}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {method === 'card' && (
                  <div className="col gap-3">
                    <div
                      className="card card-pad row gap-4"
                      style={{ background: 'var(--bg-sunken)' }}
                    >
                      <div
                        style={{
                          width: 64,
                          height: 88,
                          borderRadius: 12,
                          background: 'var(--bg-ink)',
                          color: 'var(--on-ink)',
                          display: 'grid',
                          placeItems: 'center',
                          flexShrink: 0,
                        }}
                      >
                        <Icon n="card" s={26} w={1.5} />
                      </div>
                      <div className="col gap-1 grow">
                        <b className="fs-14">ادفع على ماكينة البطاقات</b>
                        <p className="fs-13 t-2">
                          أدخل مبلغ <b className="num t-1">{egp(total)} ج</b> على الماكينة، وبعد
                          خروج إيصال الموافقة اضغط «تأكيد الدفع».
                        </p>
                      </div>
                    </div>
                    <Field
                      label="آخر ٤ أرقام / رقم الموافقة"
                      hint="اختياري — يظهر في تقرير الوردية"
                    >
                      <input
                        className="input ltr num"
                        style={{ textAlign: 'right', maxWidth: 240 }}
                        placeholder="•••• 4821"
                        value={cardDigits}
                        onChange={(e) => setCardDigits(e.target.value.replace(/\D/g, '').slice(-4))}
                      />
                    </Field>
                  </div>
                )}

                {method === 'mixed' && (
                  <div className="col gap-3">
                    <div className="grid" style={{ gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      <div className="col gap-2">
                        <span className="fs-13 fw-5 row gap-2">
                          <Icon n="cash" s={16} />
                          الجزء النقدي
                        </span>
                        <MoneyInput
                          size="md"
                          value={cashPart}
                          onChange={(v) =>
                            setCashPart(String(Math.min(Number(v || 0), total) || ''))
                          }
                          autoFocus
                          placeholder="0"
                        />
                      </div>
                      <div className="col gap-2">
                        <span className="fs-13 fw-5 row gap-2">
                          <Icon n="card" s={16} />
                          الجزء بالبطاقة <span className="t-3 fs-12">(تلقائي)</span>
                        </span>
                        <div
                          className="money-in md"
                          style={{ background: 'var(--bg-sunken)' }}
                        >
                          <span className="cur">ج.م</span>
                          <input
                            readOnly
                            value={cashPart ? String(cardA) : ''}
                            placeholder="—"
                          />
                        </div>
                      </div>
                    </div>
                    <div className="split-bar">
                      <span
                        style={{
                          width: `${total ? (cashA / total) * 100 : 0}%`,
                          background: 'var(--ok)',
                        }}
                      />
                      <span
                        style={{
                          width: `${total && cashPart ? (cardA / total) * 100 : 0}%`,
                          background: 'var(--info)',
                        }}
                      />
                    </div>
                    <div className="row between fs-12">
                      <span className="row gap-3">
                        <span className="row gap-1">
                          <i
                            style={{
                              width: 8,
                              height: 8,
                              borderRadius: 99,
                              background: 'var(--ok)',
                            }}
                          />
                          نقدي <b className="num">{egp(cashA)}</b>
                        </span>
                        <span className="row gap-1">
                          <i
                            style={{
                              width: 8,
                              height: 8,
                              borderRadius: 99,
                              background: 'var(--info)',
                            }}
                          />
                          بطاقة <b className="num">{egp(cashPart ? cardA : 0)}</b>
                        </span>
                      </span>
                      {valid ? (
                        <span className="t-ok row gap-1 fw-6">
                          <Icon n="check" s={14} w={2.5} />
                          المجموع = إجمالي الفاتورة
                        </span>
                      ) : (
                        <span className="t-3">حدد جزءًا نقديًا أقل من الإجمالي</span>
                      )}
                    </div>
                    <div className="row gap-2">
                      {[0.25, 0.5, 0.75].map((r) => (
                        <button
                          key={r}
                          className="note-chip"
                          onClick={() => setCashPart(String(Math.round(total * r)))}
                        >
                          {fmt(r * 100)}٪ نقدي
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <Field
                  label={
                    <>
                      ملاحظات على الفاتورة <span className="t-3 fs-12">(اختياري)</span>
                    </>
                  }
                >
                  <input
                    className="input"
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="تظهر في أسفل الإيصال"
                  />
                </Field>
                {errorMsg && (
                  <div className="banner b-bad" style={{ margin: '8px 0' }}>
                    <Icon n="alert" s={16} />
                    {errorMsg}
                  </div>
                )}
                <div className="row gap-2" style={{ marginTop: 'auto' }}>
                  <button className="btn btn-secondary btn-lg" disabled={stage === 'sending'} onClick={onClose}>
                    رجوع
                  </button>
                  <button
                    className="pay-btn grow"
                    style={{ margin: 0 }}
                    disabled={!valid || stage === 'sending'}
                    onClick={confirm}
                  >
                    <span className="row gap-2">
                      <Icon n="printer" s={18} />
                      {stage === 'sending' ? (retryStatus || 'جارِ تسجيل البيع…') : 'تأكيد الدفع وطباعة الإيصال'}
                    </span>
                    <span
                      className="kbd"
                      style={{
                        background: 'rgba(255,255,255,.15)',
                        borderColor: 'rgba(255,255,255,.35)',
                        color: '#fff',
                      }}
                    >
                      Enter
                    </span>
                  </button>
                </div>
              </div>
              <div className="co-side">
                <div className="row between">
                  <span className="section-label">ملخص الفاتورة</span>
                  <span className="fs-12 t-3 num">
                    {fmt(cart.reduce((s, l) => s + l.qty, 0))} قطعة
                  </span>
                </div>
                <div className="col gap-2" style={{ flex: 1, overflow: 'auto', maxHeight: 300 }}>
                  {cart.map((l) => {
                    const p = posMockService.getProductById(l.id);
                    if (!p) return null;
                    return (
                      <div key={l.id} className="row gap-2">
                        <PImg p={p} size="xs" />
                        <div className="grow" style={{ minWidth: 0 }}>
                          <div className="fs-12 fw-5 truncate">{p.name}</div>
                          <div className="fs-12 t-3 num">
                            {fmt(l.qty)} × {egp(l.price)}
                          </div>
                        </div>
                        <span className="price fs-13">{egp(l.qty * l.price)}</span>
                      </div>
                    );
                  })}
                </div>
                <div
                  className="col gap-1 fs-13"
                  style={{ borderTop: '1px dashed var(--line-strong)', paddingTop: 10 }}
                >
                  <div className="row between t-2">
                    <span>المجموع</span>
                    <span className="num">{egp(subtotal)}</span>
                  </div>
                  {discount > 0 && (
                    <div className="row between t-2">
                      <span>خصم</span>
                      <span className="num t-ok">−{egp(discount)}</span>
                    </div>
                  )}
                  <div className="row between fw-6">
                    <span>الإجمالي</span>
                    <span className="num fs-16">{egp(total)}</span>
                  </div>
                </div>
                <div
                  className="col gap-2"
                  style={{ borderTop: '1px solid var(--line)', paddingTop: 12 }}
                >
                  <Api m="POST" path="/api/v1/pos/sales" />
                  <div className="fs-12 t-3">Idempotency-Key</div>
                  <code
                    className="mono"
                    style={{
                      fontSize: 10.5,
                      direction: 'ltr',
                      wordBreak: 'break-all',
                      color: 'var(--text-2)',
                    }}
                  >
                    {idem}
                  </code>
                  <div className="fs-12 t-3">يمنع تكرار الخصم عند الضغط المزدوج</div>
                </div>
              </div>
            </div>
          ) : receipt && (
            <ReceiptDone
              {...receipt}
              onNew={onClose}
            />
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Empty, Seg, Check, Search, useEsc } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PastSale, PosProduct } from '../../types/pos.types';

interface ReturnModalProps {
  open: boolean;
  onClose: () => void;
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

export function ReturnModal({ open, onClose, toast }: ReturnModalProps) {
  const [num, setNum] = useState<string>('');
  const [sale, setSale] = useState<PastSale | null>(null);
  const [err, setErr] = useState<string>('');
  const [mode, setMode] = useState<'return' | 'exchange'>('return');
  const [sel, setSel] = useState<Record<number, { qty: number; to: 'on_hand' | 'damaged' }>>({});
  const [repl, setRepl] = useState<{ id: number; qty: number }[]>([]);
  const [rq, setRq] = useState<string>('');
  const [busy, setBusy] = useState<boolean>(false);
  const submitting = useRef(false);
  const [allProducts, setAllProducts] = useState<PosProduct[]>([]);
  const [replQuoteTotal, setReplQuoteTotal] = useState<number | null>(null);

  useEffect(() => {
    if (open) {
      setNum('');
      setSale(null);
      setErr('');
      setMode('return');
      setSel({});
      setRepl([]);
      setRq('');
      setBusy(false);
      setReplQuoteTotal(null);
      posMockService.getProducts().then(setAllProducts);
    }
  }, [open]);

  useEffect(() => {
    setReplQuoteTotal(null);
    if (!open || mode !== 'exchange' || !sale || !repl.length) return;
    const controller = new AbortController();
    const items = repl.map((r) => ({ product_variant_id: r.id, qty: r.qty }));
    void posMockService.quoteSale({ items, customer_id: sale.customer_id ?? null }, controller.signal)
      .then((q) => { if (!controller.signal.aborted) setReplQuoteTotal(q.grand_total); })
      .catch((error: Error) => { if (!controller.signal.aborted) toast(error.message, 'bad'); });
    return () => controller.abort();
  }, [open, mode, repl, sale, toast]);

  useEsc(onClose, open);
  if (!open) return null;

  const find = async () => {
    if (!num.trim()) return;
    const s = await posMockService.getPastSale(num);
    if (s) {
      setSale(s);
      setErr('');
    } else {
      setSale(null);
      setErr('لم يتم العثور على فاتورة بهذا الرقم في الفرع');
    }
  };

  const loadExample = async () => {
    const s = await posMockService.getPastSale('POS-NSR-10233');
    if (s) {
      setNum('POS-NSR-10233');
      setSale(s);
      setErr('');
    }
  };

  const retTotal = sale
    ? sale.items.reduce((s, i) => s + (sel[i.id]?.qty || 0) * i.price, 0)
    : 0;

  const fallbackReplTotal = repl.reduce((s, r) => {
    const p = posMockService.getProductById(r.id);
    return s + (p?.price || 0) * r.qty;
  }, 0);
  const replTotal = replQuoteTotal != null ? replQuoteTotal : fallbackReplTotal;

  const net = replTotal - retTotal;
  const anySel = Object.values(sel).some((v) => v.qty > 0);
  const canSubmit = anySel && (mode === 'return' || replQuoteTotal != null) && !busy;

  const results = rq
    ? allProducts
        .filter(
          (p) =>
            p.name.includes(rq) ||
            p.sku.toLowerCase().includes(rq.toLowerCase())
        )
        .slice(0, 4)
    : [];

  const handleSubmit = async () => {
    if (!canSubmit || !sale || submitting.current) return;
    submitting.current = true;
    setBusy(true);
    try {
      const returnPayload = Object.entries(sel)
        .filter(([, v]) => v.qty > 0)
        .map(([id, v]) => ({
          id: Number(id),
          qty: v.qty,
          return_to: v.to,
        }));

      if (mode === 'return') {
        const res = await posMockService.processReturn(sale.id, returnPayload);
        const cardAmt = sale.card_amount ?? 0;
        const cardRefund = (res as any)?.card_refund_amount ?? (cardAmt > 0 ? Math.min(cardAmt, retTotal) : 0);
        if (cardRefund > 0) {
          toast(`تم تسجيل المرتجع. يجب رد ${cardRefund} جنيه على الكارت يدويًا`, 'ok');
        } else {
          toast('تم تسجيل المرتجع وتحديث المخزون', 'ok');
        }
      } else {
        const res = await posMockService.processExchange(sale.id, returnPayload, repl, net, sale.customer_id);
        const cardRefund = (res as any)?.card_refund_amount ?? 0;
        if (cardRefund > 0) {
          toast(`تم الاستبدال. يجب رد ${cardRefund} جنيه على الكارت يدويًا`, 'ok');
        } else {
          toast('تم الاستبدال وإصدار فاتورة جديدة', 'ok');
        }
      }
      onClose();
    } catch (error) {
      toast(error instanceof Error ? error.message : 'تعذر تسجيل العملية', 'bad');
    } finally {
      submitting.current = false;
      setBusy(false);
    }
  };

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={onClose} />
      <div
        className="modal"
        style={{ width: 'min(920px, calc(100vw - 32px))' }}
        data-screen-label="07 Return & Exchange"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          <div
            className="row gap-3"
            style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}
          >
            <div className="grow col">
              <h3 className="fs-16">مرتجع / استبدال</h3>
              <span className="perm">
                <Icon n="shield" s={12} />
                pos.sales.refund
              </span>
            </div>
            <Seg
              value={mode}
              onChange={setMode}
              options={[
                { value: 'return', label: 'إرجاع فقط' },
                { value: 'exchange', label: 'استبدال بصنف آخر' },
              ]}
            />
            <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق">
              <Icon n="x" s={16} />
            </button>
          </div>

          <div
            style={{
              padding: '18px 22px',
              display: 'flex',
              flexDirection: 'column',
              gap: 16,
            }}
          >
            <div className="ret-head">
              <div className="scanbar grow" style={{ height: 48 }}>
                <span className="scan-ic" style={{ width: 30, height: 30 }}>
                  <Icon n="barcode" s={16} w={2} />
                </span>
                <input
                  autoFocus
                  value={num}
                  onChange={(e) => setNum(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && find()}
                  placeholder="امسح باركود الإيصال أو اكتب رقم الفاتورة (order_number)"
                  className="ltr"
                  style={{ textAlign: 'right' }}
                />
              </div>
              <button className="btn btn-primary" style={{ height: 48 }} onClick={find}>
                بحث
              </button>
              {!sale && (
                <button className="btn btn-ghost" style={{ height: 48 }} onClick={loadExample}>
                  مثال
                </button>
              )}
            </div>
            {err && (
              <div className="banner b-bad">
                <Icon n="alert" s={16} />
                {err}
              </div>
            )}

            {!sale ? (
              <Empty
                icon="ret"
                title="ابدأ بمسح إيصال البيع الأصلي"
                body="سيتم عرض بنود الفاتورة لتختار الأصناف والكميات المرتجعة وحالتها."
              />
            ) : (
              <>
                <div className="order-meta">
                  <div>
                    <span>رقم الفاتورة</span>
                    <b className="mono">{sale.number}</b>
                  </div>
                  <div>
                    <span>التاريخ</span>
                    <b>{sale.date}</b>
                  </div>
                  <div>
                    <span>العميل</span>
                    <b>{sale.customer}</b>
                  </div>
                  <div>
                    <span>الدفع / الكاشير</span>
                    <b>
                      {sale.method} · {sale.cashier}
                    </b>
                  </div>
                </div>
                <div className="card" style={{ overflow: 'hidden' }}>
                  <table className="tbl">
                    <thead>
                      <tr>
                        <th style={{ width: 40 }}></th>
                        <th>الصنف</th>
                        <th className="n">السعر</th>
                        <th className="n">المباع</th>
                        <th style={{ textAlign: 'center' }}>كمية الإرجاع</th>
                        <th>حالة الصنف الراجع</th>
                        <th className="n">المسترد</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sale.items.map((i) => {
                        const p = posMockService.getProductById(i.id);
                        const s = sel[i.id] || { qty: 0, to: 'on_hand' };
                        const retMax = i.returnable_qty != null ? i.returnable_qty : i.qty;
                        const fullyReturned = retMax <= 0;
                        const on = !fullyReturned && s.qty > 0;
                        const upd = (v: Partial<{ qty: number; to: 'on_hand' | 'damaged' }>) =>
                          setSel((x) => ({ ...x, [i.id]: { ...s, ...v } }));

                        return (
                          <tr key={i.id} className={on ? 'selected' : ''}>
                            <td>
                              {fullyReturned ? (
                                <span className="badge b-neutral" style={{ fontSize: 10, padding: '2px 4px' }}>
                                  —
                                </span>
                              ) : (
                                <Check
                                  on={on}
                                  onChange={(v) => upd({ qty: v ? 1 : 0 })}
                                />
                              )}
                            </td>
                            <td>
                              <div className="row gap-2">
                                <PImg p={p} size="xs" />
                                <div>
                                  <div className="fs-13 fw-5">{p?.name}</div>
                                  <div className="mono t-3" style={{ fontSize: 11 }}>
                                    {p?.sku}
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="n">{egp(i.price)}</td>
                            <td className="n">
                              {fmt(i.qty)}
                              {i.returnable_qty != null && i.returnable_qty < i.qty && (
                                <div className="fs-11 t-3">متبقي {fmt(i.returnable_qty)}</div>
                              )}
                            </td>
                            <td style={{ textAlign: 'center' }}>
                              {fullyReturned ? (
                                <span className="badge b-neutral" style={{ fontSize: 11 }}>
                                  مرتجع بالكامل
                                </span>
                              ) : (
                                <div className="stepper-q" style={{ opacity: on ? 1 : 0.5 }}>
                                  <button
                                    disabled={s.qty >= retMax}
                                    onClick={() => upd({ qty: Math.min(retMax, s.qty + 1) })}
                                  >
                                    <Icon n="plus" s={13} />
                                  </button>
                                  <span>{fmt(s.qty)}</span>
                                  <button
                                    onClick={() => upd({ qty: Math.max(0, s.qty - 1) })}
                                  >
                                    <Icon n="minus" s={13} />
                                  </button>
                                </div>
                              )}
                            </td>
                            <td>
                              <div
                                className="seg"
                                style={{
                                  opacity: on ? 1 : 0.45,
                                  pointerEvents: on ? 'auto' : 'none',
                                }}
                              >
                                <button
                                  aria-pressed={s.to === 'on_hand'}
                                  onClick={() => upd({ to: 'on_hand' })}
                                >
                                  <span className="row gap-1">
                                    <i
                                      style={{
                                        width: 7,
                                        height: 7,
                                        borderRadius: 9,
                                        background: 'var(--ok)',
                                      }}
                                    />
                                    سليم
                                  </span>
                                </button>
                                <button
                                  aria-pressed={s.to === 'damaged'}
                                  onClick={() => upd({ to: 'damaged' })}
                                >
                                  <span className="row gap-1">
                                    <i
                                      style={{
                                        width: 7,
                                        height: 7,
                                        borderRadius: 9,
                                        background: 'var(--bad)',
                                      }}
                                    />
                                    تالف
                                  </span>
                                </button>
                              </div>
                            </td>
                            <td className="n fw-6">{on ? egp(s.qty * i.price) : '—'}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                {mode === 'exchange' && (
                  <div
                    className="card card-pad col gap-3"
                    style={{ background: 'var(--bg-sunken)' }}
                  >
                    <div className="row between">
                      <span className="section-label">الصنف البديل</span>
                      <span className="fs-12 t-3">
                        ينفَّذ الإرجاع والفاتورة الجديدة في عملية واحدة
                      </span>
                    </div>
                    <div style={{ position: 'relative' }}>
                      <Search
                        value={rq}
                        onChange={setRq}
                        placeholder="ابحث عن الصنف البديل بالاسم أو الكود…"
                      />
                      {results.length > 0 && (
                        <div className="scan-results" style={{ maxHeight: 240 }}>
                          {results.map((p) => (
                            <button
                              key={p.id}
                              className="scan-row"
                              onClick={() => {
                                setRepl((r) =>
                                  r.find((x) => x.id === p.id)
                                    ? r.map((x) =>
                                        x.id === p.id ? { ...x, qty: x.qty + 1 } : x
                                      )
                                    : [...r, { id: p.id, qty: 1 }]
                                );
                                setRq('');
                              }}
                            >
                              <PImg p={p} size="xs" />
                              <span className="grow fs-13">{p.name}</span>
                              <span className="badge b-neutral">رصيد {fmt(p.stock)}</span>
                              <span className="price">{egp(p.price)}</span>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    {repl.map((r) => {
                      const p = posMockService.getProductById(r.id);
                      if (!p) return null;
                      return (
                        <div
                          key={r.id}
                          className="row gap-3"
                          style={{
                            background: 'var(--bg-card)',
                            padding: 10,
                            borderRadius: 12,
                            border: '1px solid var(--line)',
                          }}
                        >
                          <PImg p={p} size="xs" />
                          <span className="grow fs-13 fw-5">{p.name}</span>
                          <div className="stepper-q">
                            <button
                              onClick={() =>
                                setRepl((x) =>
                                  x.map((y) => (y.id === r.id ? { ...y, qty: y.qty + 1 } : y))
                                )
                              }
                            >
                              <Icon n="plus" s={13} />
                            </button>
                            <span>{fmt(r.qty)}</span>
                            <button
                              onClick={() =>
                                setRepl((x) =>
                                  r.qty > 1
                                    ? x.map((y) =>
                                        y.id === r.id ? { ...y, qty: y.qty - 1 } : y
                                      )
                                    : x.filter((y) => y.id !== r.id)
                                )
                              }
                            >
                              <Icon n="minus" s={13} />
                            </button>
                          </div>
                          <span className="price" style={{ width: 80, textAlign: 'end' }}>
                            {egp(p.price * r.qty)}
                          </span>
                        </div>
                      );
                    })}
                    {repl.length === 0 && (
                      <div className="fs-13 t-3">لم يتم اختيار صنف بديل بعد.</div>
                    )}
                  </div>
                )}
              </>
            )}
          </div>

          {sale && (
            <div
              className="row gap-3"
              style={{
                padding: '14px 22px',
                borderTop: '1px solid var(--line)',
                background: 'var(--bg-card)',
              }}
            >
              {mode === 'return' ? (
                <div
                  className="net grow"
                  style={{
                    background: 'var(--bad-bg)',
                    color: 'var(--bad)',
                    padding: '10px 14px',
                  }}
                >
                  <Icon n="cash" s={18} />
                  <span className="fs-13 fw-6">رد نقدية للعميل</span>
                  <span className="ms-auto display fs-20 fw-6 num">{egp(retTotal)} ج</span>
                </div>
              ) : (
                <div
                  className="net grow"
                  style={{
                    background:
                      !anySel || !repl.length
                        ? 'var(--bg-sunken)'
                        : net > 0
                        ? 'var(--ok-bg)'
                        : net < 0
                        ? 'var(--bad-bg)'
                        : 'var(--info-bg)',
                    color:
                      !anySel || !repl.length
                        ? 'var(--text-2)'
                        : net > 0
                        ? 'var(--ok)'
                        : net < 0
                        ? 'var(--bad)'
                        : 'var(--info)',
                    padding: '10px 14px',
                  }}
                >
                  <span className="fs-12 t-2" style={{ color: 'inherit', opacity: 0.8 }}>
                    مرتجع {egp(retTotal)} ← بديل {egp(replTotal)}
                  </span>
                  <span className="fs-13 fw-6">
                    {net > 0
                      ? 'تحصيل فرق من العميل'
                      : net < 0
                      ? 'رد فرق للعميل'
                      : 'بدون فروق'}
                  </span>
                  <span className="ms-auto display fs-20 fw-6 num">{egp(Math.abs(net))} ج</span>
                </div>
              )}
              <Api m="POST" path={`/pos/sales/${sale.id}/${mode}`} />
              <button
                className="btn btn-primary btn-lg"
                disabled={!canSubmit}
                onClick={handleSubmit}
              >
                <Icon n="check" s={16} w={2.4} />
                {busy
                  ? 'جارِ التنفيذ…'
                  : mode === 'return'
                  ? 'تأكيد المرتجع'
                  : 'تأكيد الاستبدال'}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, MoneyInput, Api, Field, cx, useEsc } from '../ui/SharedUI';
import { pos as posMockService } from '../../services/pos-data-source';
import type { PosShift, ShiftStats } from '../../types/pos.types';
import { fromCents, toCents } from '../../lib/money';

interface CloseShiftModalProps {
  open: boolean;
  onClose: () => void;
  shift: PosShift | null;
  onClosed: (shift: PosShift) => void;
  onCommitted: (shift: PosShift) => void;
}

export function CloseShiftModal({ open, onClose, shift, onClosed, onCommitted }: CloseShiftModalProps) {
  const [actual, setActual] = useState<string>('');
  const [notes, setNotes] = useState<string>('');
  const [busy, setBusy] = useState<boolean>(false);
  const submitting = useRef(false);
  const [statsReady, setStatsReady] = useState(false);
  const [error, setError] = useState('');
  const [closedResult, setClosedResult] = useState<PosShift | null>(null);
  const [stats, setStats] = useState<ShiftStats>({
    cashSales: 0,
    cardSales: 0,
    returns: 0,
    expenses: 0,
    invoices: 0,
  });

  useEffect(() => {
    let active = true;
    if (open) {
      setActual('');
      setNotes('');
      setBusy(false);
      setClosedResult(null);
      setStatsReady(false);
      setError('');
      void posMockService.getShiftStats().then((summary) => {
        if (!active) return;
        setStats(summary);
        setStatsReady(true);
      }).catch((error: Error) => {
        if (active) setError(error.message);
      });
    }
    return () => { active = false; };
  }, [open]);

  const dismiss = () => {
    if (submitting.current) return;
    if (closedResult) onClosed(closedResult);
    else onClose();
  };
  useEsc(dismiss, open);
  if (!open || !shift) return null;

  const expectedCents = toCents(shift.opening_cash) + toCents(stats.cashSales) - toCents(stats.returns) - toCents(stats.expenses);
  const expected = fromCents(expectedCents);
  const has = actual !== '';
  const diff = fromCents(toCents(actual) - expectedCents);
  const state: 'idle' | 'ok' | 'over' | 'short' = !has
    ? 'idle'
    : Math.abs(diff) < 0.01
    ? 'ok'
    : diff > 0
    ? 'over'
    : 'short';

  const needNote = state === 'short' || state === 'over';
  const canSubmit = statsReady && has && (!needNote || notes.trim().length >= 3) && !busy;

  const diffLabel = {
    idle: 'أدخل النقد الفعلي لحساب الفرق',
    ok: 'مطابق تمامًا',
    over: 'زيادة في الدرج',
    short: 'عجز في الدرج',
  }[state];

  const diffIcon = {
    idle: 'info',
    ok: 'check',
    over: 'arrowUpLeft',
    short: 'alert',
  }[state];

  const started = new Date(shift.opened_at);

  const handleSubmit = async () => {
    if (!canSubmit || submitting.current) return;
    submitting.current = true;
    setError('');
    setBusy(true);
    try {
      const res = await posMockService.closeShift(Number(actual), notes);
      setClosedResult(res);
      onCommitted(res);
    } catch (error) {
      setError(error instanceof Error ? error.message : 'تعذر إغلاق الوردية');
    } finally {
      submitting.current = false;
      setBusy(false);
    }
  };

  if (closedResult) {
    return ReactDOM.createPortal(
      <div
        dir="rtl"
        className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
      >
        <div className="overlay" onClick={() => onClosed(closedResult)} />
        <div
          className="modal"
          style={{ width: 'min(520px, calc(100vw - 32px))' }}
          data-screen-label="02 Close Shift Done"
          role="dialog"
          aria-modal="true"
        >
          <div className="pop col gap-4" style={{ padding: 24, textAlign: 'center', alignItems: 'center' }}>
            <span
              style={{
                width: 56,
                height: 56,
                borderRadius: 18,
                background: 'var(--ok-bg)',
                color: 'var(--ok)',
                display: 'grid',
                placeItems: 'center',
              }}
            >
              <Icon n="check" s={28} w={2.4} />
            </span>
            <div>
              <h3 className="fs-18">تم إغلاق الوردية بنجاح</h3>
              <p className="t-2" style={{ marginTop: 4 }}>
                الوردية بانتظار اعتماد المدير
              </p>
            </div>

            <div className="receipt" style={{ width: '100%', maxWidth: 300, textAlign: 'right' }}>
              <div style={{ textAlign: 'center' }}>
                <b className="fs-14 display">ملخص إغلاق الوردية</b>
                <div className="num" style={{ color: '#6f6a76' }}>
                  {closedResult.shift_number} · {shift.treasury.name}
                </div>
              </div>
              <div className="dash" />
              <div className="rr">
                <span>العهدة الافتتاحية:</span>
                <span className="num">{egp(shift.opening_cash)} ج</span>
              </div>
              <div className="rr">
                <span>مبيعات نقدية:</span>
                <span className="num">{egp(stats.cashSales)} ج</span>
              </div>
              <div className="rr">
                <span>مبيعات بطاقة:</span>
                <span className="num">{egp(stats.cardSales)} ج</span>
              </div>
              <div className="rr">
                <span>مرتجعات نقدية:</span>
                <span className="num">{egp(stats.returns)} ج</span>
              </div>
              <div className="rr">
                <span>مصروفات:</span>
                <span className="num">{egp(stats.expenses)} ج</span>
              </div>
              <div className="dash" />
              <div className="rr">
                <span>النقد المتوقع:</span>
                <span className="num">{egp(expected)} ج</span>
              </div>
              <div className="rr" style={{ fontWeight: 700 }}>
                <span>النقد الفعلي:</span>
                <span className="num">{egp(Number(actual))} ج</span>
              </div>
              <div className="rr">
                <span>الفرق:</span>
                <span className="num">
                  {diff > 0 ? `+${egp(diff)}` : diff < 0 ? `−${egp(Math.abs(diff))}` : '٠'} ج
                </span>
              </div>
              {notes && (
                <div style={{ marginTop: 8, fontSize: 11, color: '#6f6a76' }}>
                  ملاحظات: {notes}
                </div>
              )}
            </div>

            <div className="row gap-2" style={{ width: '100%', justifyContent: 'center' }}>
              <button className="btn btn-secondary btn-lg" onClick={() => window.print()}>
                <Icon n="printer" s={16} />
                طباعة الملخص
              </button>
              <button className="btn btn-primary btn-lg" autoFocus onClick={() => onClosed(closedResult)}>
                إنهاء وخروج
              </button>
            </div>
          </div>
        </div>
      </div>,
      document.body
    );
  }

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={dismiss} />
      <div
        className="modal"
        style={{ width: 'min(860px, calc(100vw - 32px))' }}
        data-screen-label="02 Close Shift"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          <div
            className="row between"
            style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}
          >
            <div className="col">
              <h3 className="fs-16">إغلاق الوردية وجرد النقدية</h3>
              <div className="fs-12 t-3 row gap-1">
                <span className="num ltr">{shift.shift_number}</span>
                <span className="dot-sep" />
                {shift.treasury.name}
                <span className="dot-sep" />
                بدأت{' '}
                <span className="num">
                  {started.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            </div>
            <button className="icon-btn sm" disabled={busy} onClick={dismiss} aria-label="إغلاق">
              <Icon n="x" s={16} />
            </button>
          </div>
          {error && <div className="banner b-bad" role="alert">{error}</div>}

          <div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
            <div
              style={{
                padding: '18px 22px',
                borderInlineEnd: '1px solid var(--line)',
                background: 'var(--bg-sunken)',
              }}
            >
              <div className="section-label" style={{ marginBottom: 6 }}>
                ملخص حركة النقدية
              </div>
              <div className="ledger">
                <div className="lr">
                  <span className="op base">·</span>
                  العهدة الافتتاحية
                  <span className="amt">{egp(shift.opening_cash)}</span>
                </div>
                <div className="lr">
                  <span className="op plus">+</span>
                  مبيعات نقدية <span className="t-3 fs-12">({fmt(stats.invoices)} فاتورة)</span>
                  <span className="amt">{egp(stats.cashSales)}</span>
                </div>
                <div className="lr">
                  <span className="op minus">−</span>
                  مرتجعات نقدية
                  <span className="amt">{egp(stats.returns)}</span>
                </div>
                <div className="lr">
                  <span className="op minus">−</span>
                  مصروفات نثرية
                  <span className="amt">{egp(stats.expenses)}</span>
                </div>
                <div className="lr" style={{ paddingTop: 14 }}>
                  <span className="op eq">=</span>
                  <b>النقد المتوقع بالدرج</b>
                  <span className="amt fs-20 fw-6">{egp(expected)}</span>
                </div>
              </div>
              <div
                className="row gap-2 fs-12 t-3"
                style={{
                  marginTop: 10,
                  padding: '10px 12px',
                  borderRadius: 12,
                  border: '1px dashed var(--line-strong)',
                }}
              >
                <Icon n="card" s={15} />
                مبيعات البطاقة <b className="num t-1">{egp(stats.cardSales)}</b> ج — لا تدخل في جرد الدرج
              </div>
            </div>

            <div style={{ padding: '18px 22px', display: 'flex', flexDirection: 'column', gap: 14 }}>
              <div className="col gap-2">
                <span className="fs-13 fw-5">النقد الفعلي بالدرج</span>
                <MoneyInput
                  value={actual}
                  onChange={setActual}
                  autoFocus
                  placeholder={String(expected)}
                />
                <div className="row gap-2">
                  <button className="note-chip" onClick={() => setActual(String(expected))}>
                    مطابق للمتوقع
                  </button>
                </div>
              </div>
              <div className={cx('diff', state)}>
                <span className="diff-ic">
                  <Icon n={diffIcon} s={18} w={2} />
                </span>
                <div className="col">
                  <span className="fs-12" style={{ opacity: 0.8 }}>
                    الفرق
                  </span>
                  <b className="fs-13">{diffLabel}</b>
                </div>
                <span className="v">
                  {has
                    ? (diff > 0 ? '+' : diff < 0 ? '−' : '') + egp(Math.abs(diff))
                    : '—'}
                </span>
              </div>
              <Field
                label={
                  <>
                    ملاحظات{' '}
                    {needNote ? (
                      <span className="t-bad fs-12">(مطلوبة لتبرير الفرق)</span>
                    ) : (
                      <span className="t-3 fs-12">(اختياري)</span>
                    )}
                  </>
                }
              >
                <textarea
                  className={cx('input', needNote && notes.trim().length < 3 && 'is-error')}
                  rows={3}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder={
                    state === 'short'
                      ? `مثال: عجز ${egp(Math.abs(diff))} جنيه فرق فكة مع عميل`
                      : 'أي ملاحظات على الوردية…'
                  }
                />
              </Field>
            </div>
          </div>

          <div
            className="row gap-2"
            style={{ padding: '14px 22px', borderTop: '1px solid var(--line)' }}
          >
            <div className="row gap-2 fs-12 t-3 grow">
              <Icon n="info" s={14} />
              ستُرسل الوردية بحالة{' '}
              <span className="badge b-warn" style={{ height: 20 }}>
                بانتظار الاعتماد
              </span>
              <Api m="POST" path="/pos/shifts/close" />
            </div>
            <button className="btn btn-secondary" onClick={onClose}>
              رجوع للبيع
            </button>
            <button
              className="btn"
              style={{ background: 'var(--bad)', color: '#fff' }}
              disabled={!canSubmit}
              onClick={handleSubmit}
            >
              <Icon n="lock" s={16} />
              {busy ? 'جارِ الإغلاق…' : 'إغلاق الوردية وإرسالها للاعتماد'}
            </button>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}import React, { useState } from 'react';
import { CustomerBar } from './CustomerBar';
import { CartLine } from './CartLine';
import { Icon } from '../ui/Icons';
import { egp, fmt, Kbd, toAsciiNum } from '../ui/SharedUI';
import type { PosCartLine, Customer, CashierUser, QuoteResult } from '../../types/pos.types';
import { maxDiscountAmount, toCents, fromCents } from '../../lib/money';

interface CartProps {
  cart: PosCartLine[];
  setCart: React.Dispatch<React.SetStateAction<PosCartLine[]>>;
  customer: Customer | null;
  setCustomer: (c: Customer | null) => void;
  discount: number;
  setDiscount: (d: number) => void;
  onHold: () => void;
  onHeld: () => void;
  heldCount: number;
  onPay: () => void;
  onClear: () => void;
  lastAdded: { id: number; k: number } | null;
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
  cashier?: CashierUser | null;
  /** Latest server quote: the source of truth for totals once available. */
  quote?: QuoteResult | null;
  isQuoting?: boolean;
  maxDiscountPercent?: number;
}

export function Cart({
  cart,
  setCart,
  customer,
  setCustomer,
  discount,
  setDiscount,
  onHold,
  onHeld,
  heldCount,
  onPay,
  onClear,
  lastAdded,
  toast,
  cashier,
  quote,
  isQuoting,
  maxDiscountPercent = 100,
}: CartProps) {
  const canOverride = cashier?.perms?.includes('pos.override_price') ?? false;
  const canDiscount = cashier?.perms?.includes('pos.discount') ?? false;
  const subtotalCents = cart.reduce((sum, line) => sum + toCents(line.listPrice) * line.qty, 0);
  const pricedCents = cart.reduce((sum, line) => sum + toCents(line.price) * line.qty, 0);
  const subtotal = fromCents(subtotalCents);
  const lineAdj = fromCents(subtotalCents - pricedCents);
  const localTotal = fromCents(Math.max(0, pricedCents - toCents(discount)));
  // The screen total is the server's; the local figure only shows until the first quote lands.
  const total = quote ? quote.grand_total : localTotal;
  const items = cart.reduce((s, l) => s + l.qty, 0);
  const [discOpen, setDiscOpen] = useState(false);
  const [discVal, setDiscVal] = useState('');

  const applyDiscount = () => {
    const cap = fromCents(maxDiscountAmount(pricedCents, maxDiscountPercent));
    const wanted = Math.min(Number(discVal || 0), subtotal);
    if (wanted > cap) {
      toast(`الحد الأقصى للخصم ${maxDiscountPercent}% (${egp(cap)} ج)`, 'bad');
    }
    setDiscount(Math.min(wanted, cap));
    setDiscOpen(false);
  };

  return (
    <aside className="cart">
      <CustomerBar customer={customer} setCustomer={setCustomer} toast={toast} />
      <div className="cart-head">
        <div className="row gap-2">
          <h3 className="fs-16">الفاتورة الحالية</h3>
          {items > 0 && <span className="badge b-neutral num">{fmt(items)} قطعة</span>}
        </div>
        {cart.length > 0 && (
          <button className="btn btn-ghost btn-sm" onClick={onClear}>
            <Icon n="trash" s={14} />
            مسح
          </button>
        )}
      </div>
      <div className="cart-list">
        {cart.length === 0 ? (
          <div className="empty" style={{ paddingTop: 56 }}>
            <div className="empty-ic">
              <Icon n="barcode" s={24} />
            </div>
            <h4>الفاتورة فارغة</h4>
            <p>امسح باركود صنف أو اضغط على أي صنف من الكتالوج لإضافته.</p>
            <div className="row gap-2 fs-12 t-3" style={{ marginTop: 8 }}>
              <Kbd>F2</Kbd> بحث <Kbd>F6</Kbd> المعلقة
              {cashier?.perms?.includes('pos.sales.refund') && <><Kbd>F8</Kbd> مرتجع</>}
            </div>
          </div>
        ) : (
          cart.map((l) => (
            <CartLine
              key={l.id}
              l={l}
              canOverride={canOverride}
              flash={lastAdded?.id === l.id ? lastAdded.k : null}
              onQty={(q) =>
                setCart((c) => c.map((x) => (x.id === l.id ? { ...x, qty: q } : x)))
              }
              onPrice={(pr) =>
                setCart((c) =>
                  c.map((x) =>
                    x.id === l.id ? { ...x, price: pr, manualPrice: pr !== x.listPrice } : x,
                  ),
                )
              }
              onRemove={() => setCart((c) => c.filter((x) => x.id !== l.id))}
            />
          ))
        )}
      </div>
      <div className="totals">
        <div className="r">
          <span>المجموع الفرعي</span>
          <b>{egp(subtotal)}</b>
        </div>
        {lineAdj !== 0 && (
          <div className="r">
            <span>تعديلات الأسعار</span>
            <b className="t-warn">−{egp(lineAdj)}</b>
          </div>
        )}
        <div className="r">
          <span className="row gap-2">
            الخصم{' '}
            {discOpen ? (
              <span className="row gap-1">
                <input
                  className="price-input"
                  autoFocus
                  value={discVal}
                  onChange={(e) => setDiscVal(toAsciiNum(e.target.value))}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') applyDiscount();
                  }}
                  onBlur={applyDiscount}
                  placeholder="0"
                />
              </span>
            ) : (
              <button
                className="t-acc fs-12 fw-6"
                onClick={() => {
                  setDiscVal(discount ? String(discount) : '');
                  setDiscOpen(true);
                }}
                disabled={!cart.length || !canDiscount}
                title={canDiscount ? undefined : 'تحتاج صلاحية الخصم (pos.discount)'}
              >
                {discount ? 'تعديل' : '+ إضافة'}
              </button>
            )}
            {!canDiscount && <span className="fs-12 t-3">تحتاج صلاحية</span>}
          </span>
          <b className={discount ? 't-ok' : ''}>{discount ? '−' + egp(discount) : '٠'}</b>
        </div>
        <div className="grand">
          <span className="fs-13 t-2">الإجمالي</span>
          <span className={isQuoting ? 'v quoting' : 'v'}>
            {egp(total)}
            <small>ج.م</small>
          </span>
        </div>
      </div>
      <div className="actions">
        <button className="btn btn-secondary" disabled={!cart.length} onClick={onHold}>
          <Icon n="pause" s={15} />
          تعليق
        </button>
        <button className="btn btn-secondary" onClick={onHeld}>
          <Icon n="inbox" s={16} />
          المعلقة
          {heldCount > 0 && <span className="badge-count">{fmt(heldCount)}</span>}
          <Kbd>F6</Kbd>
        </button>
        <button
          className="btn btn-danger"
          disabled={!cart.length}
          onClick={onClear}
          aria-label="إلغاء ومسح الفاتورة"
          title="إلغاء ومسح الفاتورة"
        >
          <Icon n="x" s={18} />
        </button>
      </div>
      <button className="pay-btn" disabled={!cart.length} onClick={onPay}>
        <span className="row gap-2">
          إتمام الدفع{' '}
          <span
            className="kbd"
            style={{
              background: 'rgba(255,255,255,.15)',
              borderColor: 'rgba(255,255,255,.35)',
              color: '#fff',
            }}
          >
            Space
          </span>
        </span>
        <span className="amt num">{egp(total)} ج</span>
      </button>
    </aside>
  );
}import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
  createContext,
  useContext,
  ReactNode,
} from 'react';
import ReactDOM from 'react-dom';
import { Icon } from './Icons';
import type { PosProduct } from '../../types/pos.types';

export const cx = (...a: (string | boolean | undefined | null)[]): string =>
  a.filter(Boolean).join(' ');

export const nf = new Intl.NumberFormat('ar-EG', { maximumFractionDigits: 0 });
export const fmt = (v: number | string): string => nf.format(Number(v) || 0);

export const nf2 = new Intl.NumberFormat('ar-EG', {
  minimumFractionDigits: 0,
  maximumFractionDigits: 2,
});
export const egp = (v: number): string => nf2.format(Math.round(v * 100) / 100);

export const toAsciiNum = (s: string | number): string =>
  String(s)
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[^\d.]/g, '');

