}) {
  if (!p) return null;
  const icon =
    p.cat === 'hand' || p.cat === 'cross' || p.cat === 'back'
      ? 'bag'
      : p.cat === 'wallet'
      ? 'wallet'
      : p.cat === 'travel'
      ? 'truck'
      : p.cat === 'acc'
