export function MoneyInput({
  value,
  onChange,
  autoFocus,
  size,
  placeholder = '0',
  onEnter,
  disabled,
  readOnly,
}: {
  value: string;
  onChange: (v: string) => void;
  autoFocus?: boolean;
  size?: string;
  placeholder?: string;
  onEnter?: () => void;
  disabled?: boolean;
  readOnly?: boolean;
}) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (autoFocus && !disabled && !readOnly) {
      const timer = setTimeout(() => ref.current?.focus(), 60);
      return () => clearTimeout(timer);
    }
  }, [autoFocus, disabled, readOnly]);

  return (
    <label className={cx('money-in', size, (disabled || readOnly) && 'is-disabled')} data-money-input>
      <span className="cur">ج.م</span>
      <input
        ref={ref}
        inputMode="decimal"
        value={value}
        placeholder={placeholder}
        disabled={disabled}
        readOnly={readOnly}
        onChange={(e) => !disabled && !readOnly && onChange(toAsciiNum(e.target.value))}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && onEnter) onEnter();
        }}
      />
    </label>
  );
}

