  Treasury,
  TransferSource,
} from '../types/pos.types';
import { normAr } from '../lib/arabic';
import { normalizeError, PosApiError } from '../lib/pos-error';
import { toApi, toCents } from '../lib/money';
import {
  mapCustomer,
