const __twkSendChat = (text) =>
  window.parent.postMessage({ type: '__edit_mode_chat', text }, '*');

const __TWK_SPARK_STAR = 'M14.8299 10.378C15.1555 10.499 15.1827 10.9337 14.8747 11.0918L11.401 12.8747C11.3125 12.9202 11.2445 12.9955 11.2099 13.0864L9.95228 16.3963C9.82177 16.7397 9.31884 16.7397 9.18834 16.3963L7.93069 13.0864C7.89616 12.9955 7.82814 12.9202 7.73965 12.8747L4.2659 11.0918C3.95787 10.9337 3.98513 10.499 4.31067 10.378L7.69556 9.11947C7.81035 9.0768 7.89899 8.98625 7.93669 8.87317L9.18301 5.13503C9.30417 4.77165 9.83645 4.77165 9.9576 5.13503L11.2039 8.87317C11.2416 8.98626 11.3303 9.0768 11.4451 9.11947L14.8299 10.378Z';
const __TWK_SPARK_DOT = 'M6.0114 3.58637C6.35897 3.71564 6.35897 4.19061 6.0114 4.31988L4.98024 4.70337C4.86547 4.74605 4.77685 4.83659 4.73915 4.94965L4.33943 6.14853C4.21828 6.51191 3.686 6.51191 3.56485 6.14853L3.16513 4.94965C3.12743 4.83659 3.03881 4.74605 2.92404 4.70337L1.89288 4.31988C1.54531 4.19061 1.54531 3.71564 1.89288 3.58637L2.92404 3.20288C3.03881 3.1602 3.12743 3.06966 3.16513 2.9566L3.56485 1.75772C3.686 1.39434 4.21828 1.39434 4.33943 1.75772L4.73915 2.9566C4.77685 3.06966 4.86547 3.1602 4.98024 3.20288L6.0114 3.58637Z';

function __TwkSpark({ size = 12 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 17 18" fill="currentColor"
         style={{ display: 'inline-block', verticalAlign: '-1px' }}>
      <path d={__TWK_SPARK_STAR} />
      <path d={__TWK_SPARK_DOT} />
    </svg>
  );
}

// Typewriter-cycles through `suggestions`. Clicking the field while a
// suggestion is animating freezes it as ghost text; Tab accepts it into the
// input. Enter posts __edit_mode_chat (host drops the text into the chat
// composer for the user to send). After the cycle the static placeholder
// types in and "Ideas" appears — clicking asks for three more suggestions.
function TweakSuggestionBar({
  suggestions = [],
  placeholder = 'Describe a tweak…',
  ideasPrompt = 'Suggest three more tweak ideas for this design and update the suggestions on TweakSuggestionBar.',
}) {
  const [val, setVal] = React.useState('');
  const [ghost, setGhost] = React.useState('');
  const [focused, setFocused] = React.useState(false);
  const inputRef = React.useRef(null);
  const tw = useTwkTypewriter(suggestions, { placeholder, enabled: !val && !ghost && !focused });

  const freeze = () => {
    tw.markPlayed();
    if (val || ghost) return;
    const target = !tw.done ? suggestions[tw.idx] : '';
    if (target) setGhost(target);
    inputRef.current?.focus();
  };

  const submit = () => {
    const v = (val || ghost).trim();
    if (!v) return;
    __twkSendChat(v);
    setVal('');
    setGhost('');
  };

  const onKeyDown = (e) => {
    if (e.key === 'Tab' && ghost && !val) {
      e.preventDefault();
      setVal(ghost);
      setGhost('');
    } else if (e.key === 'Enter') {
      e.preventDefault();
      submit();
    } else if (e.key === 'Escape') {
      setGhost('');
    }
  };

  const requestIdeas = () => __twkSendChat(ideasPrompt);

  const showAnim = !val && !ghost && !focused && !tw.done;
  const showStatic = !val && !ghost && !focused && tw.done;

  return (
    <div className="twk-sugg" onMouseDown={freeze}>
      <div className="twk-sugg-field">
        <input
          ref={inputRef}
          value={val}
          placeholder={focused && !ghost ? placeholder : ''}
          onChange={(e) => { setVal(e.target.value); setGhost(''); }}
          onFocus={() => { setFocused(true); tw.markPlayed(); }}
          onBlur={() => { setFocused(false); if (!val) setGhost(''); }}
          onKeyDown={onKeyDown}
        />
        {showAnim && (
          <div className="twk-sugg-ghost">
            {tw.text}<span className="twk-sugg-caret" />
          </div>
        )}
        {showStatic && (
          <div className="twk-sugg-ghost">
            {tw.tail}{tw.tail.length < placeholder.length && <span className="twk-sugg-caret" />}
          </div>
        )}
        {ghost && !val && (
          <div className="twk-sugg-ghost hint">{ghost}</div>
        )}
      </div>
      {val || ghost ? (
        <button className="twk-sugg-send"
                onMouseDown={(e) => { e.stopPropagation(); e.preventDefault(); }}
                onClick={submit}>
          Add
        </button>
      ) : tw.done && !focused ? (
        <button className="twk-sugg-ideas"
                onMouseDown={(e) => { e.stopPropagation(); e.preventDefault(); }}
                onClick={requestIdeas}>
          Ideas <__TwkSpark />
        </button>
      ) : null}
    </div>
  );
}

// Minimal type→pause→erase cycler. Plays once per unique `items` content per
// session — a reload from a tweak-value write skips straight to done; a new
// suggestion set (after "Ideas") gets a fresh animation.
function useTwkTypewriter(items, { placeholder, typeMs = 35, eraseMs = 22, pauseMs = 1800, enabled = true } = {}) {
  // Dep mirrors the memo body verbatim so collidable joins like
  // ['a\nb','c'] vs ['a','b','c'] don't share a stale sessionStorage key
  // (gen-spark PR #28600 Bugbot R3 — minor divergence from Tiffany's
  // `items.join('\n')` dep; upstream report pending).
  const key = React.useMemo(() => '__twk_played:' + JSON.stringify(items), [JSON.stringify(items)]);
  const played = () => { try { return sessionStorage.getItem(key) === '1'; } catch { return false; } };

  const [text, setText] = React.useState('');
  const [tail, setTail] = React.useState(() => (items.length === 0 || played() ? placeholder : ''));
  const [idx, setIdx] = React.useState(0);
  const [done, setDone] = React.useState(() => items.length === 0 || played());
  const phase = React.useRef('type');
  const n = React.useRef(0);

  const markPlayed = React.useCallback(() => {
    try { sessionStorage.setItem(key, '1'); } catch {}
    setDone(true);
  }, [key]);

  React.useEffect(() => {
    const skip = items.length === 0 || played();
    setText(''); setIdx(0);
    setDone(skip);
    setTail(skip ? placeholder : '');
    phase.current = 'type'; n.current = 0;
  }, [key]);

  React.useEffect(() => {
    if (done || !enabled) return;
    const item = items[idx] ?? '';
    let t;
    const tick = () => {
      if (phase.current === 'type') {
        n.current++;
        setText(item.slice(0, n.current));
        if (n.current >= item.length) { phase.current = 'pause'; t = setTimeout(tick, pauseMs); }
        else t = setTimeout(tick, typeMs + Math.random() * 20);
      } else if (phase.current === 'pause') {
        phase.current = 'erase'; t = setTimeout(tick, eraseMs);
      } else {
        n.current--;
        setText(item.slice(0, n.current));
        if (n.current <= 0) {
          if (idx === items.length - 1) { markPlayed(); return; }
          phase.current = 'type'; setIdx((i) => i + 1);
        } else t = setTimeout(tick, eraseMs);
      }
    };
    phase.current = 'type'; n.current = 0; setText('');
    t = setTimeout(tick, 400);
    return () => clearTimeout(t);
  }, [idx, done, key, enabled, typeMs, eraseMs, pauseMs]);

  React.useEffect(() => {
    if (!done || tail === placeholder) return;
    let i = 0;
    const t = setInterval(() => {
      i++; setTail(placeholder.slice(0, i));
      if (i >= placeholder.length) clearInterval(t);
    }, 28);
    return () => clearInterval(t);
  }, [done, placeholder]);

  return { text, tail, idx, done, markPlayed };
}

Object.assign(window, { TweakSuggestionBar });<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Admin;

use App\Enums\PosShiftStatus;
use App\Http\Controllers\Controller;
use App\Models\PosShift;
use App\Models\User;
use App\Services\BranchAccess;
use App\Services\PosService;
use Carbon\Carbon;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Routing\Controllers\HasMiddleware;
use Illuminate\Routing\Controllers\Middleware;
use Illuminate\Validation\Rule;

/**
 * Admin controller for reviewing POS shifts, cash discrepancies, and authorizing closures.
 */
class PosShiftAdminController extends Controller implements HasMiddleware
{
    public static function middleware(): array
    {
        return [
            new Middleware('can:pos_shifts.view', only: ['index', 'show']),
            new Middleware('can:pos_shifts.approve', only: ['approve']),
        ];
    }

    public function __construct(
        private readonly PosService $pos,
        private readonly BranchAccess $branchAccess,
    ) {}

    /**
     * Lists paginated POS shifts for administrative audit and approval.
     *
     * @param Request $request Filter query request
     * @return JsonResponse Paginated shifts response
     */
    public function index(Request $request): JsonResponse
    {
        $filters = $request->validate([
            'branch_id' => ['nullable', 'integer', 'min:1'],
            'user_id' => ['nullable', 'integer', 'min:1'],
            'status' => ['nullable', Rule::in(array_column(PosShiftStatus::cases(), 'value'))],
            'from_date' => ['nullable', 'date_format:Y-m-d'],
            'to_date' => ['nullable', 'date_format:Y-m-d'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
        ]);

        $branch = $this->branchAccess->restrictedBranch($request->user());
        $shifts = PosShift::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
            ->with(['cashier', 'treasury', 'branch', 'approver'])
            ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
            ->when($filters['user_id'] ?? null, fn ($q, $v) => $q->where('user_id', $v))
            ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
            // Convert business timezone start/end bounds to UTC using an exclusive upper day boundary.
            ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '>=',
                Carbon::parse($v, (string) config('app.business_timezone'))->startOfDay()->utc()))
            ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '<',
                Carbon::parse($v, (string) config('app.business_timezone'))->startOfDay()->addDay()->utc()))
            ->orderByDesc('id')
            ->paginate($filters['per_page'] ?? 15);

        return response()->json($shifts);
    }

    /**
     * Retrieves full details and petty cash expenses of a specific shift.
     *
     * @param Request $request Incoming request
     * @param PosShift $shift Target shift model
     * @return JsonResponse Shift details response
     */
    public function show(Request $request, PosShift $shift): JsonResponse
    {
        $this->branchAccess->assertBranch($request->user()->id, $shift->branch_id);

        return response()->json([
            'data' => $shift->load(['cashier', 'treasury', 'branch', 'approver', 'expenses']),
        ]);
    }

    /**
     * Approves a closed shift, reconciling drawer variance and sweeping cash to the main safe.
     *
     * @param Request $request Approval request
     * @param PosShift $shift Shift awaiting approval
     * @return JsonResponse Approved shift response
     */
    public function approve(Request $request, PosShift $shift): JsonResponse
    {
        /** @var User $approver */
        $approver = $request->user();
        $this->branchAccess->assertBranch($approver->id, $shift->branch_id);

        $shift = $this->pos->approveShift($shift, $approver);

        return response()->json([
            'message' => 'تم اعتماد الوردية وترحيل النقدية للخزنة الرئيسية.',
            'data' => $shift->load(['cashier', 'treasury', 'branch', 'approver']),
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Current inventory balance per variant, branch, and location.
 * Direct mutation is prohibited; all updates occur exclusively via InventoryService::recordMovement.
 */
class StockLevel extends Model
{
    protected $fillable = [
        'product_variant_id', 'branch_id', 'location_id',
        'reorder_level',
    ];

    protected $casts = [
        'on_hand' => 'decimal:4',
        'reserved' => 'decimal:4',
        'damaged' => 'decimal:4',
        'in_transit' => 'decimal:4',
        'reorder_level' => 'decimal:4',
        'available' => 'decimal:4',
    ];

    /** Sellable available inventory = on_hand - reserved - damaged (mirrors database generated column). */
    public function getAvailableAttribute(): float
    {
        return round((float) $this->on_hand - (float) $this->reserved - (float) $this->damaged, 4);
    }

    /**
     * Scope query to rows with non-zero balance across on_hand, reserved, damaged, or in_transit.
     *
     * @param  Builder<StockLevel>  $query
     * @return Builder<StockLevel>
     */
    public function scopeHasNonZeroBalance(Builder $query): Builder
    {
        return $query->where(fn (Builder $q) => $q
            ->where('on_hand', '<>', 0)
            ->orWhere('reserved', '<>', 0)
            ->orWhere('damaged', '<>', 0)
            ->orWhere('in_transit', '<>', 0));
    }

    /**
     * Filters rows currently in an alert state — mirrors the two
     * StockLowDetected triggers in InventoryService::recordMovement:
     * a set row threshold compares against the row, while an unset row
     * threshold falls back to the variant threshold compared against the
     * branch-wide total (not the single row).
     *
     * @param  Builder<StockLevel>  $query
     * @return Builder<StockLevel>
     */
    public function scopeWhereLowStock(Builder $query): Builder
    {
        return $query
            ->join('product_variants as pv_low', 'pv_low.id', '=', 'stock_levels.product_variant_id')
            ->leftJoinSub(
                self::query()->selectRaw('branch_id, product_variant_id, COALESCE(SUM(on_hand - reserved - damaged), 0) AS branch_available')
                    ->groupBy('branch_id', 'product_variant_id'),
                'branch_totals',
                fn ($join) => $join
                    ->on('branch_totals.branch_id', '=', 'stock_levels.branch_id')
                    ->on('branch_totals.product_variant_id', '=', 'stock_levels.product_variant_id')
            )
            ->where(fn (Builder $q) => $q
                ->where(fn (Builder $row) => $row
                    ->where('stock_levels.reorder_level', '>', 0)
                    ->whereRaw('stock_levels.available <= stock_levels.reorder_level'))
                ->orWhere(fn (Builder $variant) => $variant
                    ->whereRaw('COALESCE(stock_levels.reorder_level, 0) = 0')
                    ->where('pv_low.reorder_level', '>', 0)
                    ->whereRaw('COALESCE(branch_totals.branch_available, 0) <= pv_low.reorder_level')))
            ->select('stock_levels.*');
    }

    public function variant(): BelongsTo
    {
        return $this->belongsTo(ProductVariant::class, 'product_variant_id')->withTrashed();
    }

    public function branch(): BelongsTo
    {
        return $this->belongsTo(Branch::class);
    }

    public function location(): BelongsTo
    {
        return $this->belongsTo(Location::class);
    }
}<?php

declare(strict_types=1);

namespace App\Services\Auth;

use App\Models\User;
use Illuminate\Contracts\Cache\LockTimeoutException;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Str;

/**
 * Issues and consumes one-time handoff codes for seamless staff app authentication transfers.
 */
final class StaffHandoffService
{
    private const TTL_SECONDS = 60;

    /**
     * Issue a single-use exchange code bound to the user's current credential fingerprint.
     */
    public function issue(User $user): string
    {
        $code = Str::random(64);
        Cache::put($this->key($code), ['user_id' => $user->id, 'credentials' => self::credentialFingerprint($user)], now()->addSeconds(self::TTL_SECONDS));

        return $code;
    }

    /**
     * Generate an HMAC fingerprint over user ID, email, and password hash to invalidate codes upon credential changes.
     */
    public static function credentialFingerprint(User $user): string
    {
        return hash_hmac('sha256', json_encode([$user->id, $user->email, $user->password], JSON_THROW_ON_ERROR), (string) config('app.key'));
    }

    /**
     * Atomically consume a handoff code using a mutex lock to prevent concurrent double-consumption.
     *
     * @return array{user_id:int, credentials:string}|null
     */
    public function consume(string $code): ?array
    {
        // Cache::pull alone is read-then-delete; serialize consumers so concurrent exchanges cannot issue two tokens.
        // On lock contention timeout, report the exception and treat code as consumed (null) instead of 500.
        try {
            return Cache::lock($this->key($code).':lock', 10)
                ->block(5, fn (): ?array => Cache::pull($this->key($code)));
        } catch (LockTimeoutException $exception) {
            report($exception);

            return null;
        }
    }

    private function key(string $code): string
    {
        return 'auth:handoff:'.hash('sha256', $code);
    }
}import React, { useState, useEffect, useRef, useCallback } from 'react';
import { hasPermission } from '@alfarid/utils';
import { PosHeader } from './layout/PosHeader';
import { Catalog } from './terminal/Catalog';
import { Cart } from './terminal/Cart';
import { OpenShiftGate } from './shift/OpenShiftGate';
import { CloseShiftModal } from './shift/CloseShiftModal';
import { CheckoutModal } from './checkout/CheckoutModal';
import { HoldModal } from './checkout/HoldModal';
import { HeldDrawer } from './checkout/HeldDrawer';
import { ReturnModal } from './returns/ReturnModal';
import { StockPage } from './inventory/StockPage';
import { TransfersPage } from './inventory/TransfersPage';
import { StocktakePage } from './inventory/StocktakePage';
import { Icon } from './ui/Icons';
import { useToast } from './ui/SharedUI';
import { pos as posMockService } from '../services/pos-data-source';
import { usePosCart, posCartStore } from '../stores/pos-cart.store';
import { createScanDetector } from '../lib/barcode-scanner';
import { beepError, beepSuccess } from '../lib/sound';
import { createPendingSaleManager, type PendingSaleDraft } from '../lib/pending-sale';
import { createTabCoordinator } from '../lib/tab-coordinator';
import { getLastReceipt } from '../lib/receipt-archive';
import type {
  AppScreen,
  PosShift,
  Branch,
  CashierUser,
  PosProduct,
  Customer,
  PosHeldSale,
} from '../types/pos.types';

export interface PosAppProps {
  onLogout?: () => void;
}

export function PosApp({ onLogout }: PosAppProps = {}) {
  const toast = useToast();

  const [currentScreen, setCurrentScreen] = useState<AppScreen>('terminal');
  const [currentShift, setCurrentShift] = useState<PosShift | null>(null);
  const [branch, setBranch] = useState<Branch | null>(null);
  const [cashier, setCashier] = useState<CashierUser | null>(null);
  const [starting, setStarting] = useState(true);
  const [startupError, setStartupError] = useState<string | null>(null);
  const [startupAttempt, setStartupAttempt] = useState(0);
  const canRefund = hasPermission(cashier?.perms, 'pos.sales.refund');
  const [isDark, setIsDark] = useState<boolean>(false);

  // Network & multi-tab coordination
  const [isOnline, setIsOnline] = useState<boolean>(typeof navigator !== 'undefined' ? navigator.onLine : true);
  const [hasTabConflict, setHasTabConflict] = useState<boolean>(false);
  const [pendingSale, setPendingSale] = useState<PendingSaleDraft | null>(null);
  const pendingOwner = cashier && currentShift ? `${cashier.id}:${currentShift.id}` : undefined;
  const canRecoverPending = Boolean(pendingOwner && pendingSale?.owner === pendingOwner);
  const [confirmingPending, setConfirmingPending] = useState<boolean>(false);
  const confirmingPendingRef = useRef(false);

  // Cart, customer, discount and the live server quote live in the persisted cart store.
  const cart = usePosCart((s) => s.cart);
  const setCart = usePosCart((s) => s.setCart);
  const customer = usePosCart((s) => s.customer);
  const setCustomer = usePosCart((s) => s.setCustomer);
  const discount = usePosCart((s) => s.discount);
  const setDiscount = usePosCart((s) => s.setDiscount);
  const quote = usePosCart((s) => s.quote);
  const isQuoting = usePosCart((s) => s.isQuoting);
  const lastDeleted = usePosCart((s) => s.lastDeleted);
  const [heldSales, setHeldSales] = useState<PosHeldSale[]>([]);
  const [lastAdded, setLastAdded] = useState<{ id: number; k: number } | null>(null);
  const [maxDiscountPercent, setMaxDiscountPercent] = useState<number>(100);

  // Modals state
  const [closingShift, setClosingShift] = useState<PosShift | null>(null);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState<boolean>(false);
  const [isHoldOpen, setIsHoldOpen] = useState<boolean>(false);
  const [isHeldOpen, setIsHeldOpen] = useState<boolean>(false);
  const [isReturnOpen, setIsReturnOpen] = useState<boolean>(false);

  const scanInputRef = useRef<HTMLInputElement>(null);

  const [heldCount, setHeldCount] = useState(0);

  const checkPendingSale = useCallback(() => {
    setPendingSale(createPendingSaleManager().getSaved());
  }, []);

  useEffect(() => {
    checkPendingSale();
  }, [checkPendingSale]);

  // Multi-tab broadcast channel coordination
  useEffect(() => {
    const coordinator = createTabCoordinator({
      onDuplicate: () => setHasTabConflict(true),
    });
    coordinator.start();
    return () => coordinator.destroy();
  }, []);

  // Window online/offline listener
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    let active = true;
    let unsubscribe: (() => void) | undefined;
    const refresh = async () => {
      const [shift, loadedBranch, loadedCashier] = await Promise.all([
        posMockService.getCurrentShift(), posMockService.getBranch(), posMockService.getCashier(),
      ]);
      if (!active) return;
      setCurrentShift(shift);
      setBranch(loadedBranch);
      setCashier(loadedCashier);
      setHeldCount(posMockService.getHeldCount());
      setMaxDiscountPercent(posMockService.getSettings().max_discount_percent);
    };

    setStarting(true);
    setStartupError(null);
    void posMockService.bootstrap().then(async () => {
      if (!active) return;
      unsubscribe = posMockService.subscribe(() => void refresh().catch(() => undefined));
      await refresh();
      if (active) setStarting(false);
    }).catch((error: Error) => {
      if (!active) return;
      setStartupError(error.message);
      setStarting(false);
    });
    return () => {
      active = false;
      unsubscribe?.();
    };
  }, [startupAttempt]);

  const loadHeldSales = useCallback(async () => {
    const list = await posMockService.getHeldSales();
    setHeldSales(list);
    setHeldCount(list.length);
  }, []);

  useEffect(() => {
    if (isHeldOpen && currentShift) {
      void loadHeldSales().catch((error: Error) => toast(error.message, 'bad'));
    }
  }, [isHeldOpen, currentShift?.id, loadHeldSales, toast]);

  // One cart per cashier+shift: survives refresh / power loss (key pos-cart:{userId}:{shiftId}).
  const cartShiftId = (closingShift ?? currentShift)?.id ?? null;
  useEffect(() => {
    if (cashier) posCartStore.getState().bindContext(cashier.id, cartShiftId);
  }, [cashier?.id, cartShiftId]);

  // Add a product (click, scan bar or HID scanner): beep tells the cashier the outcome.
  const handleAddToCart = useCallback(
    (p: PosProduct) => {
      const inCart = posCartStore.getState().cart.find((l) => l.id === p.id)?.qty ?? 0;
      if (p.stock <= 0 || inCart + 1 > p.stock) {
        beepError();
        toast(p.stock <= 0 ? 'الصنف نفد من المخزون' : `الرصيد المتاح ${p.stock} فقط`, 'bad');
        return;
      }
      posCartStore.getState().addItem(p);
      setLastAdded({ id: p.id, k: Date.now() });
      beepSuccess();
    },
    [toast],
  );

  // Hardware scanner: works even when the scan box is not focused.
  useEffect(() => {
    if (!currentShift || currentScreen !== 'terminal' || isCheckoutOpen || closingShift || hasTabConflict) return;
    const detect = createScanDetector({
      onScan: async (code) => {
        try {
          const p = await posMockService.lookupByBarcode(code);
          if (p) handleAddToCart(p);
          else {
            beepError();
            toast(`لا يوجد صنف بالباركود ${code}`, 'bad');
          }
        } catch {
          beepError();
          toast('تعذر البحث عن الباركود', 'bad');
        }
      },
    });
    window.addEventListener('keydown', detect, true);
    return () => window.removeEventListener('keydown', detect, true);
  }, [currentShift?.id, currentScreen, isCheckoutOpen, closingShift, hasTabConflict, handleAddToCart, toast]);

  // Pay waits for the current quote so the payment screen opens with a confirmed total.
  const handlePay = useCallback(async () => {
    if (createPendingSaleManager().getSaved()) {
      toast('يجب تأكيد الفاتورة المعلقة أولًا', 'bad');
      return;
    }
    if (isCheckoutOpen) return;
    const result = await posCartStore.getState().flushQuote();
    if (!result || posCartStore.getState().isQuoting) {
      toast(posCartStore.getState().quoteError ?? 'تعذر تأكيد أسعار الفاتورة', 'bad');
      return;
    }
    if (result.lines.some((line) => line.error)) return;
    setIsCheckoutOpen(true);
  }, [isCheckoutOpen, toast]);

  // Keyboard shortcuts (F2, F6, F8, Space, Ctrl+Z, +/-, Ctrl+P)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!currentShift || isCheckoutOpen || closingShift || hasTabConflict) return;
      const activeTag = (e.target as HTMLElement)?.tagName;
      const isInput = activeTag === 'INPUT' || activeTag === 'TEXTAREA';

      if (e.key === 'F2') {
        e.preventDefault();
        setCurrentScreen('terminal');
        setTimeout(() => scanInputRef.current?.focus(), 60);
      }
      if (e.key === 'F6') {
        e.preventDefault();
        setIsHeldOpen((o) => !o);
      }
      if (e.key === 'F8' && canRefund) {
        e.preventDefault();
        setIsReturnOpen((o) => !o);
      }
      if (e.key === ' ' && !isInput && cart.length > 0 && currentScreen === 'terminal') {
        e.preventDefault();
        void handlePay();
      }
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z' && !isInput) {
        if (posCartStore.getState().lastDeleted) {
          e.preventDefault();
          posCartStore.getState().undoDelete();
        }
      }
      if (!isInput && (e.key === '+' || e.key === '=')) {
        if (lastAdded) {
          e.preventDefault();
          const currentItem = cart.find((l) => l.id === lastAdded.id);
          if (currentItem) {
            setCart((c) => c.map((x) => (x.id === lastAdded.id ? { ...x, qty: x.qty + 1 } : x)));
          }
        }
      }
      if (!isInput && (e.key === '-' || e.key === '_')) {
        if (lastAdded) {
          e.preventDefault();
          const currentItem = cart.find((l) => l.id === lastAdded.id);
          if (currentItem) {
            setCart((c) =>
              c
                .map((x) => (x.id === lastAdded.id ? { ...x, qty: x.qty - 1 } : x))
                .filter((x) => x.qty > 0),
            );
          }
        }
      }
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'p') {
        e.preventDefault();
        const lastRc = getLastReceipt();
        if (lastRc) {
          window.print();
          toast(`طباعة آخر فاتورة (${lastRc.invoiceNumber})`);
        } else {
          toast('لا توجد فواتير سابقة للطباعة', 'bad');
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [cart, currentShift, currentScreen, isCheckoutOpen, closingShift, hasTabConflict, canRefund, handlePay, lastAdded, toast]);

  // Offer undo for 5s after a line is removed.
  const undoToastFor = useRef<number | null>(null);
  useEffect(() => {
    if (lastDeleted && undoToastFor.current !== lastDeleted.id) {
      undoToastFor.current = lastDeleted.id;
      toast('تم حذف الصنف — اضغط Ctrl+Z للتراجع');
    }
    if (!lastDeleted) undoToastFor.current = null;
  }, [lastDeleted, toast]);

  // Confirm pending sale
  const handleConfirmPendingSale = async () => {
    if (!pendingSale || !canRecoverPending || isCheckoutOpen || confirmingPendingRef.current) return;
    confirmingPendingRef.current = true;
    setConfirmingPending(true);
    try {
      const mgr = createPendingSaleManager({ owner: pendingOwner });
      await mgr.executeWithRetry(
        pendingSale.payload,
        pendingSale.key,
        (p, k) => posMockService.createSale(p, k)
      );
      posCartStore.getState().clearCart();
      setPendingSale(null);
      toast('تم تأكيد تسجيل الفاتورة المعلقة بنجاح');
    } catch (err: any) {
      toast(err?.message || 'تعذر تأكيد الفاتورة، حاول مرة أخرى', 'bad');
    } finally {
      confirmingPendingRef.current = false;
      setConfirmingPending(false);
      checkPendingSale();
    }
  };

  // Handle holding sale
  const handleHoldSale = async (note: string) => {
    if (!cart.length) return;
    await posMockService.holdSale(cart, customer, note);
    posCartStore.getState().clearCart();
    setIsHoldOpen(false);
    toast('تم تعليق الفاتورة بنجاح');
  };

  // Handle resuming held sale
  const handleResumeHeld = async (heldItem: PosHeldSale) => {
    try {
      const resumed = await posMockService.resumeHeldSale(heldItem.ref);
      const newLines = resumed.items.map((i) => {
        const p = posMockService.getProductById(i.id);
        const price = p ? p.price : 100;
        return { id: i.id, qty: i.qty, price, listPrice: price };
      });

      setCart((prev) => [...prev, ...newLines]);
      if (resumed.customer) {
        posMockService.getCustomers(resumed.customer).then((matches) => {
          if (matches.length > 0) setCustomer(matches[0]);
        });
      }
      setIsHeldOpen(false);
      setHeldSales((list) => list.filter((item) => item.ref !== heldItem.ref));
      setCurrentScreen('terminal');
      toast(`تم استرجاع الفاتورة ${resumed.ref}`);
    } catch (err: any) {
      toast(err?.message || 'تعذر استرجاع الفاتورة', 'bad');
    }
  };

  const handleDeleteHeld = async (heldItem: PosHeldSale) => {
    await posMockService.deleteHeldSale(heldItem.ref);
    setHeldSales((list) => list.filter((item) => item.ref !== heldItem.ref));
    toast(`تم حذف الفاتورة المعلقة ${heldItem.ref}`);
  };

  const handleSalePaid = () => {
    posCartStore.getState().clearCart();
    checkPendingSale();
    toast('تم تسجيل الفاتورة بنجاح');
  };

  const toggleTheme = () => {
    setIsDark((d) => !d);
    document.documentElement.classList.toggle('theme-dark');
  };

  return (
    <div className={`app ${isDark ? 'theme-dark' : 'theme-light'}`} dir="rtl">
      {/* Multi-tab conflict overlay */}
      {hasTabConflict && (
        <div
          className="tab-conflict-overlay"
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 99999,
            background: 'rgba(0,0,0,0.85)',
            color: '#fff',
            display: 'grid',
            placeItems: 'center',
            backdropFilter: 'blur(6px)',
          }}
        >
          <div style={{ maxWidth: 460, textAlign: 'center', padding: 32 }}>
            <Icon n="alert" s={48} style={{ color: 'var(--bad)', marginBottom: 16 }} />
            <h2 className="fs-22">مفتوح في نافذة أخرى</h2>
            <p className="t-2" style={{ color: 'rgba(255,255,255,0.75)', marginTop: 8 }}>
              نظام نقاط البيع مفتوح حاليًا في نافذة أو تبويب آخر. لتجنب تكرار العمليات ومشاكل التزامن، يرجى العمل من النافذة المفتوحة أو إغلاقها ثم تحديث هذه الصفحة.
            </p>
            <button
              className="btn btn-primary btn-lg"
              style={{ marginTop: 20 }}
              onClick={() => setHasTabConflict(false)}
            >
              الاستمرار في هذه النافذة
            </button>
          </div>
        </div>
      )}

      {/* Offline banner */}
      {!isOnline && (
        <div
          className="banner b-warn"
          style={{
            borderRadius: 0,
            justifyContent: 'center',
            padding: '8px 16px',
            fontSize: 13,
            fontWeight: 500,
          }}
        >
          <Icon n="wifi" s={16} />
          <span>غير متصل — سيتم تأكيد البيع عند عودة الاتصال</span>
        </div>
      )}

      {/* Unconfirmed pending sale banner */}
      {pendingSale && (
        <div
          className="banner b-bad row between"
          style={{
            borderRadius: 0,
            padding: '8px 16px',
            fontSize: 13,
            fontWeight: 500,
          }}
        >
          <div className="row gap-2">
            <Icon n="alert" s={16} />
            <span>فيه فاتورة لم يتأكد تسجيلها</span>
            {!canRecoverPending && <span>يلزم الرجوع للمسؤول إذا كانت الوردية الأصلية غير متاحة.</span>}
          </div>
          <button
            className="btn btn-sm"
            style={{
              background: '#fff',
              color: 'var(--bad)',
              fontWeight: 600,
              padding: '4px 12px',
            }}
            disabled={confirmingPending || !canRecoverPending || isCheckoutOpen}
            onClick={handleConfirmPendingSale}
          >
            {confirmingPending ? 'جارِ التأكيد…' : 'تأكيد الآن'}
          </button>
        </div>
      )}

      {starting ? (
        <div className="gate" role="status">جارِ تحميل نقطة البيع…</div>
      ) : startupError ? (
        <div className="gate">
          <div className="gate-card" role="alert">
            <p>{startupError}</p>
            <button className="btn btn-primary" onClick={() => setStartupAttempt((attempt) => attempt + 1)}>
              إعادة المحاولة
            </button>
          </div>
        </div>
      ) : !currentShift ? (
        <OpenShiftGate onOpened={(shift) => setCurrentShift(shift)} />
      ) : (
        <>
          <PosHeader
            currentScreen={currentScreen}
            onScreenChange={setCurrentScreen}
            branch={branch}
            cashier={cashier}
            shift={currentShift}
            onOpenCloseShift={() => {
              if (createPendingSaleManager().getSaved()) {
                toast('يجب تأكيد الفاتورة المعلقة قبل إغلاق الوردية', 'bad');
                return;
              }
              setClosingShift(currentShift);
            }}
            onOpenReturns={canRefund ? () => setIsReturnOpen(true) : undefined}
            isDark={isDark}
            onToggleDark={toggleTheme}
            onLogout={onLogout}
          />

          {currentScreen === 'terminal' && (
            <div className="sale">
              <Catalog
                cart={cart}
                customer={customer}
                onAdd={handleAddToCart}
                scanRef={scanInputRef}
              />
              <Cart
                cart={cart}
                setCart={setCart}
                customer={customer}
                setCustomer={setCustomer as (c: Customer | null) => void}
                discount={discount}
                setDiscount={setDiscount}
                onHold={() => setIsHoldOpen(true)}
                onHeld={() => setIsHeldOpen(true)}
                heldCount={heldCount}
                onPay={() => void handlePay()}
                onClear={() => posCartStore.getState().clearCart()}
                lastAdded={lastAdded}
                toast={toast}
                cashier={cashier}
                quote={quote}
                isQuoting={isQuoting}
                maxDiscountPercent={maxDiscountPercent}
              />
            </div>
          )}

          {currentScreen === 'stock' && <StockPage branch={branch} />}

          {currentScreen === 'transfers' && (
            <TransfersPage toast={toast} branch={branch} />
          )}

          {currentScreen === 'stocktake' && <StocktakePage toast={toast} />}

          {/* Modals & Overlays */}
          <CheckoutModal
            open={isCheckoutOpen}
            onClose={() => {
              setIsCheckoutOpen(false);
              requestAnimationFrame(() => scanInputRef.current?.focus());
            }}
            cart={cart}
            customer={customer}
            quote={quote}
            isQuoting={isQuoting}
            onPaid={handleSalePaid}
            onAttemptSettled={checkPendingSale}
            pendingOwner={pendingOwner}
            branch={branch}
            cashier={cashier}
          />

          <HoldModal
            open={isHoldOpen}
            onClose={() => setIsHoldOpen(false)}
            onHold={handleHoldSale}
            cart={cart}
            customer={customer}
          />

          <HeldDrawer
            open={isHeldOpen}
            onClose={() => setIsHeldOpen(false)}
            held={heldSales}
            onResume={handleResumeHeld}
            onDelete={handleDeleteHeld}
            cartBusy={cart.length > 0}
            branch={branch}
          />

          <ReturnModal
            open={canRefund && isReturnOpen}
            onClose={() => setIsReturnOpen(false)}
            toast={toast}
          />
        </>
      )}
      {closingShift && (
        <CloseShiftModal
          open
          shift={closingShift}
          onClose={() => setClosingShift(null)}
          onClosed={() => setClosingShift(null)}
          onCommitted={(closed) => {
            posCartStore.getState().clearCart();
            setCurrentShift(null);
            toast(`تم إغلاق الوردية #${closed.shift_number} بنجاح`);
          }}
        />
      )}
    </div>
  );
}import type {
  Branch,
  CashierUser,
  Treasury,
  ProductCategory,
  PosProduct,
  Customer,
  PosCartLine,
  ShiftStats,
  PosShift,
  PosHeldSale,
  PastSale,
  StockTransfer,
  TransferSource,
  StocktakeSession,
  CreateSalePayload,
  PosSettings,
  QuoteResult,
} from '../types/pos.types';
import type { QuoteRequest } from './pos-api.core';

const INITIAL_BRANCH: Branch = { id: 3, name: 'فرع مدينة نصر', code: 'NSR', is_active: true };

const INITIAL_CASHIER: CashierUser = {
  id: 21,
  name: 'أحمد سمير',
  initials: 'أس',
  role: 'كاشير أول',
  perms: ['pos.override_price', 'pos.discount', 'pos.sales.refund', 'transfers.create', 'transfers.receive', 'stocktakes.update'],
};

const INITIAL_TREASURIES: Treasury[] = [
  { id: 1, name: 'درج كاشير ١', code: 'DRW-01', state: 'free', last: 'آخر إغلاق أمس ١١:٤٠ م', balance: 500 },
  { id: 2, name: 'درج كاشير ٢', code: 'DRW-02', state: 'free', last: 'آخر إغلاق أمس ١٠:١٥ م', balance: 0 },
  { id: 4, name: 'درج الصالة', code: 'DRW-04', state: 'busy', last: 'مفتوح مع منى عادل', balance: 0 },
];

const INITIAL_CATS: ProductCategory[] = [
  { id: 'all', name: 'الكل' },
  { id: 'hand', name: 'شنط يد' },
