namespace App\Models;

use App\Enums\ProductStatus;
use App\Enums\SalesChannel;
use App\Models\Concerns\TracksEditVersion;
use App\Support\CatalogMedia;
use Database\Factories\CategoryFactory;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;
use Spatie\Image\Enums\Fit;
use Spatie\MediaLibrary\HasMedia;
use Spatie\MediaLibrary\InteractsWithMedia;
use Spatie\MediaLibrary\MediaCollections\Models\Media;

/**
 * Hierarchical category model organizing products into multi-level classification trees.
 */
class Category extends Model implements HasMedia
{
    /** @use HasFactory<CategoryFactory> */
    use HasFactory, InteractsWithMedia, SoftDeletes, TracksEditVersion;

    protected $fillable = ['parent_id', 'name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order', 'is_active'];

    protected $casts = ['is_active' => 'boolean', 'lock_version' => 'integer'];

    public function parent(): BelongsTo
    {
        return $this->belongsTo(Category::class, 'parent_id');
    }

    public function children(): HasMany
    {
        return $this->hasMany(Category::class, 'parent_id')->orderBy('sort_order')->orderBy('id');
    }

    public function products(): HasMany
    {
        return $this->hasMany(Product::class);
    }

    /** Active retail products for storefront category counters. */
    public function activeProducts(): HasMany
    {
        return $this->hasMany(Product::class)->publishedForRetail();
    }

    /**
     * Scope to categories that are active and whose ancestor path (up to 3 levels) is active.
     *
     * @param  Builder<Category>  $query
     * @return Builder<Category>
     */
    public function scopeActiveHierarchy(Builder $query): Builder
    {
        return $query->where('is_active', true)
            ->where(fn ($path) => $path->whereNull('parent_id')
                ->orWhereHas('parent', fn ($parent) => $parent->where('is_active', true)
                    ->where(fn ($path) => $path->whereNull('parent_id')
                        ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', true)->whereNull('parent_id')))));
    }

    public function registerMediaCollections(): void
    {
        $this->addMediaCollection('image')->singleFile()->useDisk(CatalogMedia::disk())->storeConversionsOnDisk(CatalogMedia::disk())
            ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
    }

    // Generate webp thumbnails and medium variants to avoid serving original master images in UI tiles.
    public function registerMediaConversions(?Media $media = null): void
    {
        $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
            ->performOnCollections('image');
        $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
            ->performOnCollections('image');
    }

    /**
     * Returns all recursive descendant category IDs using cycle detection.
     *
     * @return list<int> Array of descendant category IDs
     */
    public function descendantIds(): array
    {
        $ids = [];
        $seen = [$this->id => true];
        $queue = [$this->id];
        while ($queue) {
            $children = Category::whereIn('parent_id', $queue)->pluck('id')->all();
            $queue = [];
            foreach ($children as $childId) {
                if (! isset($seen[$childId])) {
                    $seen[$childId] = true;
                    $ids[] = $childId;
                    $queue[] = $childId;
                }
            }
        }

        return $ids;
    }

    /**
     * Calculates the category depth from root (root = 1), detecting circular parent references.
     *
     * @return int 1-based hierarchy depth
     *
     * @throws \RuntimeException If a cycle is detected in the parent chain
     */
    public function depth(): int
    {
        $depth = 1;
        $seen = [$this->id => true];
        $p = $this->parent;
        while ($p) {
            if (isset($seen[$p->id])) {
                throw new \RuntimeException('توجد دورة في شجرة الأقسام');
            }
            $seen[$p->id] = true;
            $depth++;
            $p = $p->parent;
        }

        return $depth;
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\ProductStatus;
use App\Enums\SalesChannel;
use App\Models\Concerns\TracksEditVersion;
use App\Support\CatalogMedia;
use Database\Factories\ProductFactory;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Support\Collection;
use Spatie\Image\Enums\Fit;
use Spatie\MediaLibrary\HasMedia;
use Spatie\MediaLibrary\InteractsWithMedia;
use Spatie\MediaLibrary\MediaCollections\Models\Media;

/**
 * Core product catalog model defining base classifications, dimensions, and shared media assets.
 */
class Product extends Model implements HasMedia
{
    /** @use HasFactory<ProductFactory> */
    use HasFactory, InteractsWithMedia, SoftDeletes, TracksEditVersion;

    protected $fillable = [
        'code', 'category_id', 'brand_id', 'supplier_id', 'name_ar', 'name_en', 'slug',
        'description_ar', 'description_en', 'material_ar', 'material_en',
        'length_cm', 'width_cm', 'height_cm', 'weight_kg', 'warranty_months', 'warranty_details',
        'country_of_origin', 'status', 'sales_channel', 'is_featured', 'sales_count', 'published_at', 'created_by', 'create_key', 'create_request_hash',
        'occasions', 'badge_en', 'badge_ar',
    ];

    protected $casts = [
        'status' => ProductStatus::class,
        'sales_channel' => SalesChannel::class,
        'is_featured' => 'boolean',
        'is_active' => 'boolean',
        'sales_count' => 'integer',
        'published_at' => 'datetime',
        'occasions' => 'array',
        'length_cm' => 'decimal:2', 'width_cm' => 'decimal:2', 'height_cm' => 'decimal:2',
        'weight_kg' => 'decimal:3',
    ];

    public function category(): BelongsTo
    {
        return $this->belongsTo(Category::class);
    }

    public function brand(): BelongsTo
    {
        return $this->belongsTo(Brand::class);
    }

    public function variants(): HasMany
    {
        // Chaperone back-populates product relationship on variants to avoid N+1 lazy queries.
        return $this->hasMany(ProductVariant::class)->orderBy('sort_order')->chaperone();
    }

    /**
     * Scope to published products available on the retail storefront.
     *
     * @param  Builder<Product>  $query
     * @return Builder<Product>
     */
    public function scopePublishedForRetail(Builder $query): Builder
    {
        return $query->where('status', ProductStatus::Published)
            ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both]);
    }

    public function registerMediaCollections(): void
    {
        $this->addMediaCollection('images')->useDisk(CatalogMedia::disk())->storeConversionsOnDisk(CatalogMedia::disk())
            ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
        $this->addMediaCollection('images_staging')->useDisk(CatalogMedia::disk())->storeConversionsOnDisk(CatalogMedia::disk())
            ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
        $this->addMediaCollection('video')->singleFile()->useDisk(CatalogMedia::disk())->storeConversionsOnDisk(CatalogMedia::disk())
            ->acceptsMimeTypes(['video/mp4', 'video/webm', 'video/quicktime']);
        $this->addMediaCollection('video_staging')->useDisk(CatalogMedia::disk())->storeConversionsOnDisk(CatalogMedia::disk())
            ->acceptsMimeTypes(['video/mp4', 'video/webm', 'video/quicktime']);
    }

    /**
     * Resolves unified collection of product and active variant media images for catalog displays.
     *
     * @return Collection<int, Media> Consolidated catalog media collection
     */
    public function catalogImages(): Collection
    {
        $variants = $this->relationLoaded('variants')
            ? $this->variants
            : $this->variants()->where('is_active', true)->with('media')->get();

        return $this->getMedia('images')->concat($variants
            ->filter(fn ($variant) => $variant->is_active && ! $variant->trashed())
            ->flatMap(fn ($variant) => $variant->getMedia('images')))->values();
    }

    public function registerMediaConversions(?Media $media = null): void
    {
        // Queue thumbnail/medium conversions to avoid holding row locks during synchronous image processing.
        $this->addMediaConversion('thumb')->fit(Fit::Crop, 300, 300)->format('webp')
            ->performOnCollections('images')->queued();
        $this->addMediaConversion('medium')->fit(Fit::Contain, 800, 800)->format('webp')
            ->performOnCollections('images')->queued();
    }
}<?php

