export interface ApiClientConfig {
  baseURL?: string;
  withCredentials?: boolean;
  getToken?: () => string | null | undefined;
  onUnauthorized?: () => void;
  /** Override for slower endpoints such as reports and exports. */
  timeout?: number;
}

let activeToken: string | null = null;
let unauthorizedHandler: (() => void) | null = null;

export function setAuthToken(token: string | null) {
  // Module-level state is shared across concurrent SSR requests in Node; restrict setAuthToken to client-side only to prevent cross-request token leaks.
  if (typeof window === 'undefined') {
    throw new Error('setAuthToken must not be called on the server -- create a per-request client with createApiClient({ getToken }) instead.');
  }
  activeToken = token;
}

export function getAuthToken(): string | null {
  return activeToken;
}

export function setUnauthorizedHandler(handler: (() => void) | null) {
  unauthorizedHandler = handler;
}

export function createApiClient(config: ApiClientConfig = {}): AxiosInstance {
  const envBaseUrl = typeof process !== 'undefined' && process.env 
    ? (process.env.NEXT_PUBLIC_API_URL || process.env.VITE_API_URL) 
    : undefined;

  const instance = axios.create({
    baseURL: resolveServiceUrl(config.baseURL || envBaseUrl || 'http://localhost:8000'),
    timeout: config.timeout ?? 30000,
    withCredentials: config.withCredentials ?? false,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-Requested-With': 'XMLHttpRequest',
    },
  });

  instance.interceptors.request.use((reqConfig: InternalAxiosRequestConfig) => {
    const existingAuth = reqConfig.headers?.Authorization ?? (reqConfig.headers as Record<string, unknown>)?.['authorization'];
    if (existingAuth) {
      return reqConfig;
    }
    const token = config.getToken ? config.getToken() : activeToken;
    if (token && reqConfig.headers) {
      reqConfig.headers.Authorization = `Bearer ${token}`;
    }
    return reqConfig;
  });

  instance.interceptors.response.use(
    (response) => response,
    (error) => {
      const isSignInRequest = ['/api/v1/auth/login', '/api/v1/auth/handoff/exchange']
        .some((path) => error.config?.url?.split('?')[0] === path);
      const currentToken = config.getToken ? config.getToken() : activeToken;
      const requestAuth = error.config?.headers?.Authorization ?? error.config?.headers?.authorization;
      const staleSession = typeof requestAuth === 'string' && requestAuth.startsWith('Bearer ')
        && requestAuth !== `Bearer ${currentToken}`;
      if (error.response?.status === 401 && !isSignInRequest && !staleSession) {
        if (config.onUnauthorized) {
          config.onUnauthorized();
        } else if (unauthorizedHandler) {
          unauthorizedHandler();
        }
      }
      return Promise.reject(error);
    }
  );

  return instance;
}

export const defaultApiClient = createApiClient();

