declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Pos;

use App\Enums\StocktakeStatus;
use App\Enums\TransferStatus;
use App\Http\Controllers\Controller;
use App\Http\Resources\Admin\StockLevelResource;
use App\Http\Resources\Admin\StockTransferResource;
use App\Models\Branch;
use App\Models\ProductVariant;
use App\Models\StockLevel;
use App\Models\Stocktake;
use App\Models\StockTransfer;
use App\Models\User;
use App\Services\BranchAccess;
use App\Services\SearchTerm;
use App\Services\StocktakeService;
use App\Services\TransferService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
use Illuminate\Validation\Rule;

/**
 * Handles POS terminal inventory queries, branch transfer requests, incoming receipts, and barcode stocktake scans.
 */
class PosStockController extends Controller
{
    public function __construct(
        private readonly TransferService $transfers,
        private readonly StocktakeService $stocktakes,
    ) {}

    /**
     * Lists current branch inventory stock levels with search and low-stock filters.
     *
     * @param Request $request Filter query request
     * @return AnonymousResourceCollection Paginated stock level resources
     */
    public function index(Request $request): AnonymousResourceCollection
    {
        $filters = $request->validate([
            'product_variant_id' => ['nullable', 'integer', 'min:1'],
            'q' => ['nullable', 'string', 'max:100'],
            'low_stock' => ['nullable', 'boolean'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
        ]);

        /** @var User $user */
        $user = $request->user('staff');

        // Non-blind count design: on_hand stays
        // visible to counters because the same handset sells from it — the
        // session relies on the snapshot/stale-movement guards at approve
        // time (StocktakeService) instead of balance secrecy.
        $levels = StockLevel::query()
            ->where('branch_id', $user->branch_id)
            ->with(['variant.product', 'location'])
            ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
            ->when($filters['q'] ?? null, function ($q, $v): void {
                // Escape LIKE wildcard characters to avoid malformed patterns and unintentional wildcards.
                $like = SearchTerm::pattern((string) $v);
                $q->whereHas('variant', fn ($vq) => $vq->where('sku', $v)
                    ->orWhere('barcode', $v)
                    ->orWhereHas('product', fn ($pq) => $pq
                        ->where('name_ar', 'LIKE', $like)
                        ->orWhere('name_en', 'LIKE', $like)));
            })
            // Matches alert thresholds: evaluates row-level minimum per location, and variant reorder point across branch totals.
            ->when($filters['low_stock'] ?? null, fn ($q) => $q->whereLowStock())
            ->orderBy('product_variant_id')
            ->paginate($filters['per_page'] ?? 15);

        return StockLevelResource::collection($levels);
    }

    /**
     * Requests stock transfer from another active branch into the cashier's branch.
     *
     * @param Request $request Transfer request payload
     * @return JsonResponse Created transfer response
     */
    public function requestTransfer(Request $request): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        abort_unless($user->can('transfers.create'), 403);

        $data = $request->validate([
            'from_branch_id' => ['required', 'integer', 'min:1',
                Rule::exists('branches', 'id')->where('is_active', true),
                Rule::notIn([$user->branch_id]),
            ],
            'items' => ['required', 'array', 'min:1', 'max:100'],
            // Reject inactive variants upfront during validation rather than during transfer approval.
            'items.*.product_variant_id' => ['required', 'integer', 'min:1', 'distinct',
                Rule::exists('product_variants', 'id')->where('is_active', true)],
            'items.*.from_location_id' => ['nullable', 'integer', 'min:1',
                Rule::exists('locations', 'id')->where('branch_id', (int) $request->input('from_branch_id')),
            ],
            'items.*.to_location_id' => ['nullable', 'integer', 'min:1',
                Rule::exists('locations', 'id')->where('branch_id', (int) $user->branch_id),
            ],
            'items.*.requested_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
            'notes' => ['nullable', 'string', 'max:500'],
        ]);

        $data['to_branch_id'] = $user->branch_id;

        $transfer = $this->transfers->create($data, $user->id, $this->requiredIdempotencyKey($request));

        return response()->json([
            'message' => 'تم إرسال طلب التحويل بنجاح وهو في انتظار الاعتماد.',
            'transfer_number' => $transfer->transfer_number,
            'id' => $transfer->id,
        ], 201);
    }

    /**
     * Confirms receipt of an incoming transfer at the cashier's branch.
     *
     * @param Request $request Receipt request payload
     * @param StockTransfer $transfer Target transfer model
     * @return JsonResponse Receipt confirmation response
     */
    public function receiveTransfer(Request $request, StockTransfer $transfer): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        abort_unless($user->can('transfers.receive'), 403);

        if ((int) $transfer->to_branch_id !== (int) $user->branch_id) {
            return response()->json(['message' => 'هذه التحويلة ليست موجهة لفرعك.'], 403);
        }

        $data = $request->validate([
            'items' => ['required', 'array', 'min:1', 'max:500'],
            'items.*.id' => ['required', 'integer', 'min:1', 'distinct',
                Rule::exists('stock_transfer_items', 'id')->where('stock_transfer_id', $transfer->id),
            ],
            'items.*.received_qty' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
        ]);

        $quantities = [];
        foreach ($data['items'] as $item) {
            $quantities[(int) $item['id']] = (float) $item['received_qty'];
        }

        $transfer = $this->transfers->receive($transfer, $quantities, $user->id);

        return response()->json([
            'message' => 'تم تأكيد استلام التحويلة بنجاح وتم رفع المخزون.',
            'id' => $transfer->id,
            'status' => $transfer->status->value,
        ]);
    }

    /**
     * Records barcode scan count against an open stocktake session.
     *
     * @param Request $request Scan request containing barcode and optional quantity
     * @param Stocktake $stocktake Target stocktake session
     * @return JsonResponse Scan registration response
     */
    public function scan(Request $request, Stocktake $stocktake): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        abort_unless($user->can('stocktakes.update'), 403);

        if ((int) $stocktake->branch_id !== (int) $user->branch_id) {
            return response()->json(['message' => 'جلسة الجرد لا تتبع فرعك.'], 403);
        }
        app(BranchAccess::class)->assertBranch($user->id, $stocktake->branch_id);

        if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
            return response()->json(['message' => 'جلسة الجرد ليست مفتوحة.'], 422);
        }

        $data = $request->validate([
            'barcode' => ['required', 'string', 'max:100'],
            'qty' => ['nullable', 'numeric', 'decimal:0,4', 'min:0.0001', 'max:99999'],
            'qty_words' => ['nullable', 'string', 'max:50'],
            'scan_id' => ['nullable', 'uuid'],
        ]);

        // Voice count input: parse spoken Arabic quantities while keeping system_qty hidden from non-approvers.
        $qty = isset($data['qty']) ? (float) $data['qty'] : 1;
        if (! isset($data['qty']) && isset($data['qty_words'])) {
            $spoken = \App\Services\SpokenQuantity::parse($data['qty_words']);
            if ($spoken === null || $spoken < 1) {
                return response()->json(['message' => 'العدد المنطوق مش واضح؛ قوله تاني أو اكتبه رقمًا.'], 422);
            }
            $qty = $spoken;
        }

        $variant = ProductVariant::query()
            ->where('barcode', $data['barcode'])
            ->where('is_active', true)
            ->first();

        if ($variant === null) {
            return response()->json([
                'message' => 'لم يُعثر على صنف بهذا الباركود.',
                'barcode' => $data['barcode'],
            ], 404);
        }

        $before = $stocktake->items->firstWhere('product_variant_id', $variant->id)?->counted_qty;

        $stocktake = $this->stocktakes->incrementItemCount($stocktake, $variant->id, $qty, $user->id, $data['scan_id'] ?? null);

        $item = $stocktake->items->firstWhere('product_variant_id', $variant->id);

        $response = [
            'message' => 'تم تسجيل المسح بنجاح.',
            'product_variant_id' => $variant->id,
            'sku' => $variant->sku,
            'counted_qty' => $item?->counted_qty,
        ];
        if (($data['scan_id'] ?? null) !== null && (float) ($item?->counted_qty ?? 0) === (float) ($before ?? 0)) {
            $response['duplicate'] = true;
        }
        if ($user->can('stocktakes.approve')) {
            $response['system_qty'] = $item?->system_qty;
        }

        return response()->json($response);
    }

    /**
     * Lists incoming shipped transfers targeted at the cashier's branch.
     */
    public function incoming(Request $request): AnonymousResourceCollection
    {
        /** @var User $user */
        $user = $request->user('staff');
        $branchId = (int) $user->branch_id;
        app(BranchAccess::class)->assertBranch($user->id, $branchId);

        $transfers = StockTransfer::query()
            ->where('to_branch_id', $branchId)
            ->where('status', TransferStatus::Shipped)
            ->with(['fromBranch', 'toBranch', 'items.variant.product', 'items.fromLocation', 'items.toLocation'])
            ->orderByDesc('shipped_at')
            ->orderByDesc('id')
            ->get();

        return StockTransferResource::collection($transfers);
    }

    /**
     * Lists active transfer source branches and warehouses excluding the cashier's own branch.
     */
    public function sources(Request $request): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        $branchId = (int) $user->branch_id;
        app(BranchAccess::class)->assertBranch($user->id, $branchId);

        $branches = Branch::query()
            ->where('is_active', true)
            ->where('id', '!=', $branchId)
            ->orderBy('id')
            ->get()
            ->map(fn (Branch $b): array => [
                'id' => $b->id,
                'name' => $b->getAttribute('name_ar') ?? $b->name,
                'code' => $b->code,
                'type' => $b->type instanceof \BackedEnum ? $b->type->value : (string) $b->type,
            ])
            ->values()
            ->all();

        return response()->json(['data' => $branches]);
    }

    /**
     * Retrieves the latest active (draft or in_progress) stocktake session for the cashier's branch.
     *
     * Enforces blind counting by hiding system_qty and variance_qty unless the staff member has stocktakes.approve.
     */
    public function currentStocktake(Request $request): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        $branchId = (int) $user->branch_id;
        app(BranchAccess::class)->assertBranch($user->id, $branchId);

        $stocktake = Stocktake::query()
            ->where('branch_id', $branchId)
            ->whereIn('status', [StocktakeStatus::Draft, StocktakeStatus::InProgress])
            ->with(['items.variant.product'])
            ->latest('id')
            ->first();

        if ($stocktake === null) {
            return response()->json(['data' => null]);
        }

        $canApprove = $user->can('stocktakes.approve');

        $items = $stocktake->items->map(function ($item) use ($canApprove): array {
            $row = [
                'id' => $item->id,
                'product_variant_id' => $item->product_variant_id,
                'sku' => $item->relationLoaded('variant') ? $item->variant?->sku : null,
                'barcode' => $item->relationLoaded('variant') ? $item->variant?->barcode : null,
                'counted_qty' => $item->counted_qty !== null ? (float) $item->counted_qty : null,
            ];

            if ($canApprove) {
                $row['system_qty'] = $item->system_qty !== null ? (float) $item->system_qty : null;
                $row['difference'] = $item->difference !== null ? (float) $item->difference : null;
                $row['variance_qty'] = $item->difference !== null ? (float) $item->difference : null;
            }

            return $row;
        })->values()->all();

        return response()->json([
            'data' => [
                'id' => $stocktake->id,
                'stocktake_number' => $stocktake->stocktake_number,
                'branch_id' => $stocktake->branch_id,
                'location_id' => $stocktake->location_id,
                'status' => $stocktake->status->value,
                'notes' => $stocktake->notes,
                'items' => $items,
                'created_at' => $stocktake->created_at,
                'updated_at' => $stocktake->updated_at,
            ],
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerStatus;
use App\Enums\PriceListType;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\PriceList;
use App\Models\PriceListItem;
use App\Models\ProductVariant;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Carbon\Carbon;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Collection;

/**
 * Central pricing engine across storefront, wholesale portal, POS, and admin backoffice.
 *
 * Evaluation hierarchy:
 * 1. Customer-specific price list (customer_specific)
 * 2. Customer group price list (customer_group)
 * 3. Channel price list (wholesale/distributor for approved accounts, otherwise retail).
 *    Wholesale/distributor channels without a matching item fall back to active retail lists.
 * 4. Channel base price (wholesale_price for wholesale/distributor, then retail_price).
 *
 * Customer group discount percentages apply on top of tier 3/4 channel outcomes without
 * overriding customer-specific or group-specific price lists.
 * Within each tier: branch-specific list first, highest qualifying min_qty, highest priority, lowest price.
 */
class PricingService
{
    private array $catalogContexts = [];

    /**
     * Resolves cache key and public visibility context for customer catalog listings.
     *
     * @return array{key: string, public_retail: bool}
     */
    public function catalogContext(?Customer $customer): array
    {
        if ($customer === null || $customer->status !== CustomerStatus::Approved) {
            return ['key' => 'retail', 'public_retail' => true];
        }

        return $this->catalogContexts[$customer->id] ??= $this->resolveCatalogContext($customer);
    }

    /**
     * Builds the unique catalog pricing context key for an approved customer.
     */
    private function resolveCatalogContext(Customer $customer): array
    {
        $customer->loadMissing('customerGroup');
        $group = $customer->customerGroup?->is_active ? $customer->customerGroup : null;
        $specific = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->exists();
        $channel = $this->channelFor($customer);
        $public = $channel === PriceListType::Retail && $group === null && ! $specific;

        return ['key' => $public ? 'retail' : $channel->value.':group:'.($group?->id ?? 'none').($specific ? ':customer:'.$customer->id : ''), 'public_retail' => $public];
    }

    /**
     * Preloads the per-customer pricing context once per listing and passes
     * it down — resolve()/tiersFor() otherwise re-query the customer group on
     * every variant (15 products x variants x calls per page).
     *
     * @return array{channel: PriceListType, eligible: bool, group: object|null}
     */
    public function contextFor(?Customer $customer, ?array $variantIds = null): array
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        if ($eligible) {
            $customer->loadMissing('customerGroup');
        }
        $group = $eligible && $customer->customerGroup?->is_active ? $customer->customerGroup : null;

        $channel = $this->channelFor($customer);
        $context = ['channel' => $channel, 'eligible' => $eligible, 'group' => $group];
        if ($variantIds !== null) {
            $context['items'] = $this->eligibleItems(null, PHP_FLOAT_MAX, null, Carbon::now(), $variantIds)
                ->where(function ($q) use ($channel, $eligible, $customer, $group): void {
                    $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                    if ($eligible) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($group !== null) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $group->id));
                    }
                })
                ->addSelect('price_lists.type as pricing_type', 'price_lists.branch_id as pricing_branch_id', 'price_lists.priority as pricing_priority')
                ->get()->groupBy('product_variant_id');
        }

        return $context;
    }

    /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
    public function withStorePrice(Builder $variants, ?Customer $customer): Builder
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        $channel = $this->channelFor($customer);
        $group = $eligible ? $customer->customerGroup : null;
        $group = $group?->is_active ? $group : null;
        $factor = $this->discountFactor($group?->discount_percentage ?? '0');
        $items = $this->eligibleItems(null, 1, null, Carbon::now())
            ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
                $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                if ($eligible) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                        ->where('price_lists.customer_id', $customer->id));
                }
                if ($group !== null) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                        ->where('price_lists.customer_group_id', $group->id));
                }
            })
            ->select([])
            ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
            ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
        $items = $this->ordered($items)->limit(1);

        // Mirror basePrice() hierarchy in SQL: wholesale channels fallback to wholesale_price before retail_price.
        $fallback = in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            ? 'COALESCE(product_variants.wholesale_price, product_variants.retail_price)'
            : 'product_variants.retail_price';

        // resolve() switches the basis to retail when a wholesale customer
        // falls back to a retail list. Preserve that effective channel in SQL.
        $baseItems = (clone $items)->select([])->selectRaw("COALESCE(CASE WHEN price_lists.type = 'retail' THEN product_variants.retail_price ELSE ".$fallback." END, price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END)", [$factor]);

        return $variants->select('product_variants.*')
            ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), '.$fallback.' * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor])
            ->selectRaw('ROUND(COALESCE(('.$baseItems->toSql().'), '.$fallback.')::numeric, 2) AS store_base_price', $baseItems->getBindings());
    }

    /**
     * Resolves the effective unit price, base reference price, and pricing source for a variant.
     *
     * @param  float  $qty  Purchasing quantity used for volume tier matching.
     * @param  int|null  $branchId  Optional branch restriction for branch-specific price lists.
     * @param  array{channel: PriceListType, eligible: bool, group: object|null, items?: Collection}|null  $ctx  Preloaded pricing context.
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     *
     * @throws BusinessException If quantity is non-positive or item has no valid price.
     */
    public function resolve(
        ProductVariant $variant,
        ?Customer $customer = null,
        float $qty = 1,
        ?int $branchId = null,
        ?array $ctx = null,
    ): array {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();

        // Reuse preloaded customer pricing context if supplied by bulk callers to prevent redundant queries.
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $pick = fn (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null): ?PriceListItem => $this->pickWinningItem($type, $ownerField, $ownerId, $variant, $qty, $branchId, $baseQuery, $ctx);

        // Priority 1: Customer-specific pricing.
        if ($eligibleCustomer) {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 2: Customer group pricing.
        $group = $ctx['group'];
        if ($group !== null) {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 3: Customer channel price list (wholesale, distributor, or retail).
        $item = $pick($channel);

        // Wholesale/distributor channels without matched items fall back to active retail price lists.
        if ($item === null && $channel !== PriceListType::Retail) {
            $item = $pick(PriceListType::Retail);

            if ($item !== null) {
                $channel = PriceListType::Retail;
            }
        }

        if ($item !== null) {
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $channelSource = $channel->value;
        } elseif ($this->basePrice($variant, $channel) === null) {
            // Priority 4 is impossible: unpriced item without matching price list or base price.
            throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
        } else {
            // Priority 4: Channel base price when no price list matches.
            $channelPrice = $this->basePrice($variant, $channel);
            $channelListId = null;
            $channelSource = 'base_price';
        }

        // Apply customer group discount percentage on top of channel list/base price.
        if ($group !== null && (float) $group->discount_percentage > 0) {
            return $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );
        }

        return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
    }

    /**
     * Resolves the effective unit price with a per-layer explanation waterfall.
     *
     * @return array{final: array, layers: list<array>, notes: list<string>}
     */
    public function trace(ProductVariant $variant, ?Customer $customer = null, float $qty = 1, ?int $branchId = null, ?array $ctx = null): array
    {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $group = $ctx['group'];
        $layers = [];
        $notes = [];

        if ($customer !== null
            && $customer->isCommercialTier()
            && $customer->status !== CustomerStatus::Approved) {
            $notes[] = 'العميل جملة لكنه مش معتمد، فاتسعّر قطاعي.';
        }

        $pick = fn (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null): ?PriceListItem => $this->pickWinningItem($type, $ownerField, $ownerId, $variant, $qty, $branchId, $baseQuery, $ctx);

        $tieNote = function (PriceListType $type, ?string $ownerField, ?int $ownerId, ?PriceListItem $winner) use ($ctx, $baseQuery, $branchId, &$notes): void {
            if ($winner === null || (isset($ctx['items']) && $branchId === null)) {
                return;
            }
            $top = $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
                ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))
                ->limit(2)->get(['price_list_items.id', 'price_list_items.min_qty', 'price_list_items.price', 'price_lists.priority', 'price_lists.branch_id']);
            if ($top->count() === 2
                && (int) $top[0]->priority === (int) $top[1]->priority
                && (float) $top[0]->min_qty === (float) $top[1]->min_qty
                && ($top[0]->branch_id === null) === ($top[1]->branch_id === null)
                && (float) $top[0]->price !== (float) $top[1]->price) {
                $notes[] = 'فيه قائمتين بنفس الأولوية، فكسبت الأرخص.';
            }
        };

        $skippedRest = function (array $names) use (&$layers): void {
            foreach ($names as $n) {
                $layers[] = ['layer' => $n, 'status' => 'skipped', 'reason' => 'طبقة أعلى كسبت.'];
            }
        };

        if (! $eligibleCustomer) {
            $layers[] = ['layer' => 'customer_specific', 'status' => 'not_eligible', 'reason' => 'العميل مش معتمد أو زائر، فقوائم العملاء الخاصة مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            if ($customer !== null) {
                $specificId = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->orderByDesc('id')->value('id');
                if ($specificId !== null) {
                    $notes[] = "عنده قائمة خاصة رقم {$specificId}، بس العميل مش approved، فالقائمة دي مش بتتطبق.";
                }
            }
        } else {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerSpecific, 'customer_id', $customer->id, $item);
                $layers[] = ['layer' => 'customer_specific', 'status' => 'won', 'reason' => 'قائمة العميل الخاصة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['customer_group', 'channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_specific', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة العميل الخاصة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group === null) {
            $layers[] = ['layer' => 'customer_group', 'status' => 'not_eligible', 'reason' => 'العميل مش في مجموعة نشطة، فقوائم المجموعات مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        } else {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerGroup, 'customer_group_id', $group->id, $item);
                $layers[] = ['layer' => 'customer_group', 'status' => 'won', 'reason' => 'قائمة المجموعة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_group', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة المجموعة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        $item = $pick($channel);
        $channelWon = false;
        $channelPrice = null;
        $channelListId = null;
        $channelSource = $channel->value;
        if ($item !== null) {
            $tieNote($channel, null, null, $item);
            $channelWon = true;
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $layers[] = ['layer' => 'channel', 'status' => 'won', 'reason' => "قائمة القناة ({$channel->value}) كسبت.", 'price_list_id' => $channelListId, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
        } else {
            $layers[] = ['layer' => 'channel', 'status' => 'no_match', 'reason' => "مفيش بند مطابق في قائمة القناة ({$channel->value}).", 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon && $channel !== PriceListType::Retail) {
            $retailItem = $pick(PriceListType::Retail);
            if ($retailItem !== null) {
                $tieNote(PriceListType::Retail, null, null, $retailItem);
                $channel = PriceListType::Retail;
                $channelWon = true;
                $channelPrice = (string) $retailItem->price;
                $channelListId = (int) $retailItem->price_list_id;
                $channelSource = $channel->value;
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'won', 'reason' => 'القناة وقعت على قائمة قطاعي بديلة.', 'price_list_id' => $channelListId, 'price' => (float) $retailItem->price, 'min_qty' => (float) $retailItem->min_qty];
            } else {
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'no_match', 'reason' => 'مفيش بند قطاعي بديل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            }
        } else {
            $layers[] = ['layer' => 'retail_fallback', 'status' => 'skipped', 'reason' => $channelWon ? 'القناة كسبت، فمش محتاج بديل قطاعي.' : 'القناة قطاعي بالفعل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon) {
            $base = $this->basePrice($variant, $channel);
            if ($base === null) {
                throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
            }
            $channelPrice = $base;
            $channelListId = null;
            $channelSource = 'base_price';
            $layers[] = ['layer' => 'base_price', 'status' => 'won', 'reason' => 'مفيش قوائم مطابقة، فاتسعّر بالسعر الأساسي.', 'price_list_id' => null, 'price' => (float) $base, 'min_qty' => null];
        } else {
            $layers[] = ['layer' => 'base_price', 'status' => 'skipped', 'reason' => 'قائمة كسبت، فالسعر الأساسي مش مستخدم.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group !== null && (float) $group->discount_percentage > 0) {
            $layers[] = ['layer' => 'group_discount', 'status' => 'won', 'reason' => "خصم المجموعة {$group->discount_percentage}% اتطبق على سعر القناة/الأساسي.", 'price_list_id' => $channelListId, 'price' => null, 'min_qty' => null];
            $final = $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );

            return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
        }

        $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'مفيش خصم مجموعة يتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        $final = $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);

        return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
    }

    /**
     * Returns the step-ladder volume pricing tiers applicable to a customer for a variant.
     *
     * @return list<array{min_qty: float, unit_price: float}>}
     * @return list<array{min_qty: float, unit_price: float}>
     */
    public function tiersFor(ProductVariant $variant, ?Customer $customer, ?array $ctx = null, ?int $branchId = null): array
    {
        $now = Carbon::now();
        // Reuse preloaded customer pricing context when available to prevent redundant group queries.
        $ctx ??= $this->contextFor($customer);
        $channel = $ctx['channel'];
        $eligible = $ctx['eligible'];
        $groupId = $ctx['group']?->id;

        $breakpoints = isset($ctx['items']) && $branchId === null
            ? ($ctx['items'][$variant->id] ?? collect())->pluck('min_qty')->map(fn ($v) => (float) $v)
            : $this->eligibleItems($variant, PHP_FLOAT_MAX, $branchId, $now)
                ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
                    $q->where('price_lists.type', $channel->value)
                        ->orWhere('price_lists.type', PriceListType::Retail->value);
                    if ($eligible) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($groupId !== null) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $groupId));
                    }
                })
                ->pluck('price_list_items.min_qty')
                ->map(fn ($v) => (float) $v)
                ->unique()
                ->sort()
                ->values();

        $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();

        return $points
            ->map(fn (float $minQty) => [
                'min_qty' => $minQty,
                'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty), $branchId, $ctx)['unit_price'],
            ])
            ->values()
            ->all();
    }

    /**
     * Resolves the pricing channel enum: approved wholesale/distributor accounts use their channel; all others use Retail.
     */
    private function channelFor(?Customer $customer): PriceListType
    {
        if ($customer?->isWholesaleApproved()) {
            return PriceListType::from($customer->type->value);
        }

        return PriceListType::Retail;
    }

    private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
    {
        // Wholesale channels prefer wholesale_price and fall back to retail_price when unassigned.
        if (in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            && $variant->wholesale_price !== null) {
            return (string) $variant->wholesale_price;
        }

        return $variant->retail_price === null ? null : $variant->base_price;
    }

    /**
     * Returns the base catalog reference price for a variant under the customer's channel.
     */
    public function basePriceForCustomer(ProductVariant $variant, ?Customer $customer): ?string
    {
        return $this->basePrice($variant, $this->channelFor($customer));
    }

    /**
     * Converts a percentage discount string (e.g. "15.00") into a decimal multiplication factor (0.85).
     */
    private function discountFactor(string $percentage): string
    {
        return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
    }

    /**
     * Query scope for active price list items matching variant, quantity threshold, branch, and current time.
     */
    private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now, ?array $variantIds = null): Builder
    {
        return PriceListItem::query()
            ->select('price_list_items.*')
            ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
            ->where('price_lists.is_active', true)
            ->when($variant !== null,
                fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
                fn ($q) => $variantIds !== null
                    ? $q->whereIn('price_list_items.product_variant_id', $variantIds)
                    : $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
            ->where('price_list_items.min_qty', '<=', $qty)
            ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
            ->where(function ($q) use ($branchId): void {
                $q->whereNull('price_lists.branch_id');
                if ($branchId !== null) {
                    $q->orWhere('price_lists.branch_id', $branchId);
                }
            });
    }

    /**
     * Pick the winning price list item matching the specified type and ownership scope.
     */
    private function pickWinningItem(
        PriceListType $type,
        ?string $ownerField,
        ?int $ownerId,
        ProductVariant $variant,
        float $qty,
        ?int $branchId,
        Builder $baseQuery,
        array $ctx,
    ): ?PriceListItem {
        if (isset($ctx['items']) && $branchId === null) {
            return ($ctx['items'][$variant->id] ?? collect())
                ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
                ->sort(function ($a, $b): int {
                    return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
                        ?: ((float) $b->min_qty <=> (float) $a->min_qty)
                        ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
                        ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
                        ?: ((int) $a->id <=> (int) $b->id);
                })->first();
        }

        return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
            ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
    }

    /**
     * Sorts candidate price list items: branch-specific first, highest min_qty, highest priority, lowest price.
     */
    private function ordered(Builder $query): Builder
    {
        return $query
            ->orderByRaw('price_lists.branch_id IS NULL ASC')
            ->orderByDesc('price_list_items.min_qty')
            ->orderByDesc('price_lists.priority')
            ->orderBy('price_list_items.price')->orderBy('price_list_items.id');
    }

    /**
     * Formats rounded pricing amounts and metadata into standard pricing response payload.
     *
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     */
    private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
    {
        return [
            'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'source' => $source,
            'price_list_id' => $priceListId,
        ];
    }

    /**
     * Applies charm and psychological price rounding schemes.
     */
    public static function applyRounding(float $price, string $rounding): float
    {
        if ($price <= 0) {
            return round($price, 2);
        }

        return match ($rounding) {
            'nearest_5' => round($price / 5.0) * 5.0,
            'nearest_10' => round($price / 10.0) * 10.0,
            'end_with_9' => max(9.0, floor($price / 10.0) * 10.0 + 9.0),
            'end_with_99' => max(99.0, round($price / 100.0) * 100.0 - 1.0),
            default => round($price, 2),
        };
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\TreasuryTransactionType;
use App\Enums\TreasuryTransferStatus;
use App\Exceptions\BusinessException;
use App\Models\Branch;
use App\Models\PosShift;
use App\Models\Treasury;
use App\Models\TreasuryTransaction;
use App\Models\TreasuryTransfer;
use App\Models\User;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * Single entry point for treasury mutations, enforcing balance integrity and audit logging.
 */
class TreasuryService
{
    public function __construct(private readonly SettingService $settings) {}

    /**
     * Creates a new treasury account and posts optional opening balance.
     *
     * @param  array<string, mixed>  $data  Treasury attributes
     * @param  User  $actor  Staff user creating the treasury
     * @param  string  $opening  Initial opening balance amount
     * @return Treasury Created treasury model
     */
    public function createAccount(array $data, User $actor, string $opening = '0.00'): Treasury
    {
        $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);

        return DB::transaction(function () use ($data, $actor, $opening): Treasury {
            $treasury = Treasury::create($data + ['current_balance' => '0.00']);
            if (bccomp($opening, '0', 2) !== 0) {
                $this->record([
                    'treasury_id' => $treasury->id,
                    'type' => TreasuryTransactionType::OpeningBalance,
                    'amount' => $opening,
                    'created_by' => $actor->id,
                    'notes' => "رصيد افتتاحي #{$treasury->code}",
                ]);
            }

            return $treasury->refresh();
        });
    }

    /**
     * Updates treasury account parameters with branch and unsettled shift validation.
     *
     * @param  Treasury  $treasury  Target treasury
     * @param  array<string, mixed>  $data  Updated attributes
     * @param  User  $actor  Staff user initiating update
     * @return Treasury Refreshed treasury model
     *
     * @throws BusinessException If type changed, unsettled shifts exist, or cross-branch move is blocked
     */
    public function updateAccount(Treasury $treasury, array $data, User $actor): Treasury
    {
        if (array_key_exists('branch_id', $data)) {
            $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);
        }

        return DB::transaction(function () use ($treasury, $data, $actor): Treasury {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (isset($data['type']) && $data['type'] !== $locked->type->value) {
                throw new BusinessException('نوع الخزينة غير قابل للتغيير.');
            }
            $unsettled = $locked->shifts()->whereIn('status', ['open', 'closed_pending_approval'])->exists();
            if (array_key_exists('branch_id', $data) && $data['branch_id'] != $locked->branch_id
                && ($unsettled || bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists())) {
                throw new BusinessException('لا يمكن نقل خزينة لها رصيد أو سجل حركات إلى فرع آخر.');
            }
            if ($unsettled && array_key_exists('is_active', $data) && ! $data['is_active']) {
                throw new BusinessException('لا يمكن تعطيل درج له وردية لم تُسوَّ.');
            }
            $locked->update($data);

            return $locked;
        });
    }

    /**
     * Deletes an unused treasury account with zero balance and no transaction history.
     *
     * @param  Treasury  $treasury  Target treasury
     * @param  User  $actor  Staff user initiating deletion
     *
     * @throws BusinessException If treasury has non-zero balance, transactions, or shifts
     */
    public function deleteAccount(Treasury $treasury, User $actor): void
    {
        DB::transaction(function () use ($treasury, $actor): void {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists() || $locked->shifts()->exists()) {
                throw new BusinessException('لا يمكن حذف خزينة لها رصيد أو سجل حركات أو ورديات.');
            }
            $locked->delete();
        });
    }

    private function assertAccountBranch(User $actor, ?int $branchId): void
    {
        $branches = app(BranchAccess::class);
        if ($branchId === null) {
            $branches->assertCentralAccess($actor);
        } else {
            $branches->assertBranch($actor->id, $branchId);
        }
    }

    /**
     * Records a financial transaction and updates treasury balance under a row lock.
     *
     * @param array{
     *     treasury_id: int,
     *     shift_id?: int|null,
     *     type: TreasuryTransactionType,
     *     amount: float|string,
     *     reference_type?: string|null,
     *     reference_id?: int|null,
     *     created_by: int,
     *     notes?: string|null,
     * } $data Transaction payload
     * @return TreasuryTransaction Created transaction record
     *
     * @throws BusinessException If treasury is inactive or insufficient funds
     */
    public function record(array $data): TreasuryTransaction
    {
        return DB::transaction(function () use ($data): TreasuryTransaction {
            /** @var Treasury $treasury */
            $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
            if ($treasury->branch_id !== null) {
                app(BranchAccess::class)->lockActiveBranch((int) $treasury->branch_id);
            }

            if (! $treasury->is_active && ! in_array($data['type'], [TreasuryTransactionType::ExpenseReversal, TreasuryTransactionType::CustomerReceiptReversal], true)) {
                throw new BusinessException('الخزينة غير نشطة.');
            }

            $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
            $balanceAfter = BigDecimal::of((string) $treasury->current_balance)->plus($amount)->toScale(2);

            // Bank accounts support overdrafts; physical safes and POS drawers cannot go negative.
            if ($balanceAfter->isNegative() && $treasury->type->value !== 'bank_account') {
                throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
            }

            $transaction = TreasuryTransaction::create([
                'treasury_id' => $treasury->id,
                'shift_id' => $data['shift_id'] ?? null,
                'type' => $data['type'],
                'amount' => (string) $amount,
                'balance_after' => (string) $balanceAfter,
                'reference_type' => $data['reference_type'] ?? null,
                'reference_id' => $data['reference_id'] ?? null,
                'created_by' => $data['created_by'],
                'notes' => $data['notes'] ?? null,
                'created_at' => now(),
            ]);

            $treasury->current_balance = (string) $balanceAfter;
            $treasury->save();

            return $transaction;
        });
    }

    /**
     * Approves and executes a pending treasury transfer between two accounts.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to approve
     * @param  int  $approverId  User approving the transfer
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending, self-approved, or unauthorized
     */
    public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
            }
            // Segregation of duties: creator cannot approve their own transfer.
            if ((int) $transfer->created_by === $approverId) {
                throw new BusinessException('يجب أن يعتمد تحويل الخزينة موظف آخر غير منشئه.');
            }
            $treasuries = $this->lockTreasuries([$transfer->from_treasury_id, $transfer->to_treasury_id], $approverId);
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            $absAmount = (string) BigDecimal::of((string) $transfer->amount)->abs()->toScale(2, RoundingMode::HalfUp);

            $this->recordTransferPair(
                $transfer->from_treasury_id,
                $transfer->to_treasury_id,
                $absAmount,
                TreasuryTransfer::class,
                $transfer->id,
                $approverId,
                "تحويل #{$transfer->transfer_number} صادر",
                "تحويل #{$transfer->transfer_number} وارد"
            );

            $transfer->update([
                'status' => TreasuryTransferStatus::Approved,
                'approved_by' => $approverId,
            ]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Reconciles POS cash drawer variance and transfers closing cash to the branch main safe.
     *
     * @param  PosShift  $shift  Completed POS shift
     * @param  int  $approverId  Manager approving the shift settlement
     *
     * @throws BusinessException If main safe is missing or unauthorized
     */
    public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
    {
        DB::transaction(function () use ($shift, $approverId): void {
            // Deterministic selection picks the oldest active safe when multiple exist.
            $mainSafe = Treasury::query()
                ->where('branch_id', $shift->branch_id)
                ->where('type', 'main_safe')
                ->where('is_active', true)
                ->orderBy('id')
                ->first();

            if ($mainSafe === null) {
                throw new BusinessException('يلزم وجود خزنة رئيسية نشطة لاعتماد الوردية وتسوية رصيد الدرج.');
            }

            $locked = $this->lockTreasuries([$shift->treasury_id, $mainSafe->id]);
            app(BranchAccess::class)->lockActiveBranches($locked->pluck('branch_id')->filter());
            $drawer = $locked->get($shift->treasury_id);
            $amount = (string) BigDecimal::of((string) $shift->actual_closing_cash)->toScale(2, RoundingMode::HalfUp);
            $difference = BigDecimal::of((string) $shift->actual_closing_cash)
                ->minus((string) $drawer->current_balance)->toScale(2);
            if (! $difference->isZero()) {
                $this->record([
                    'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
                    'type' => $difference->isNegative() ? TreasuryTransactionType::CashShortage : TreasuryTransactionType::CashOverage,
                    'amount' => (string) $difference, 'reference_type' => PosShift::class,
                    'reference_id' => $shift->id, 'created_by' => $approverId,
                    'notes' => 'تسوية فرق النقدية للوردية '.$shift->shift_number,
                ]);
            }

            if (BigDecimal::of($amount)->isLessThanOrEqualTo('0')) {
                return;
            }

            $this->recordTransferPair(
                $shift->treasury_id,
                $mainSafe->id,
                $amount,
                PosShift::class,
                $shift->id,
                $approverId,
                "ترحيل إغلاق وردية #{$shift->shift_number}",
                "ترحيل إغلاق وردية #{$shift->shift_number}"
            );
        });
    }

    /**
     * Creates a pending transfer request between two treasuries.
     *
     * @param  array<string, mixed>  $data  Transfer parameters
     * @param  int  $userId  Creator identifier
     * @return TreasuryTransfer Created pending transfer
     *
     * @throws BusinessException If source equals destination or unauthorized
     */
    public function createTransfer(array $data, int $userId): TreasuryTransfer
    {
        return DB::transaction(function () use ($data, $userId): TreasuryTransfer {
            $treasuries = Treasury::query()->whereIn('id', [$data['from_treasury_id'], $data['to_treasury_id']])->get();
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            if ($data['from_treasury_id'] === $data['to_treasury_id']) {
                throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
            }

            $number = $this->settings->generateNextNumber('treasury_transfer');

            return TreasuryTransfer::create([
                'transfer_number' => $number,
                'from_treasury_id' => $data['from_treasury_id'],
                'to_treasury_id' => $data['to_treasury_id'],
                'amount' => $data['amount'],
                'status' => TreasuryTransferStatus::Pending,
                'created_by' => $userId,
                'notes' => $data['notes'] ?? null,
            ]);
        }, 3);
    }

    /**
     * Rejects a pending treasury transfer without altering account balances.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to reject
     * @param  int  $approverId  User rejecting the transfer
     * @param  string|null  $reason  Optional audit reason (kept for the AI finance tools)
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending
     */
    public function rejectTransfer(TreasuryTransfer $transfer, int $approverId, ?string $reason = null): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId, $reason): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
            }
            // Rejections carry no financial movement, avoiding unnecessary row locking contention.
            $transfer->update(['status' => TreasuryTransferStatus::Rejected, 'approved_by' => $approverId, 'rejection_reason' => $reason]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Acquires pessimistic locks on specified treasuries in consistent primary key order to prevent deadlocks.
     *
     * @param  list<int>  $ids  Treasury identifiers
     * @param  int|null  $userId  User to verify branch access against
     * @return Collection<int, Treasury> Locked treasuries keyed by ID
     */
    public function lockTreasuries(array $ids, ?int $userId = null): Collection
    {
        $treasuries = Treasury::query()->whereIn('id', $ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');
        if ($userId !== null) {
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
        }

        return $treasuries;
    }

    /**
     * Record matching outbound and inbound transactions for a treasury-to-treasury transfer.
     */
    private function recordTransferPair(
        int $fromTreasuryId,
        int $toTreasuryId,
        string $amount,
        string $referenceType,
        int $referenceId,
        int $createdBy,
        string $outNotes,
        string $inNotes
    ): void {
        $this->record([
            'treasury_id' => $fromTreasuryId,
            'type' => TreasuryTransactionType::TransferOut,
            'amount' => '-'.$amount,
            'reference_type' => $referenceType,
            'reference_id' => $referenceId,
            'created_by' => $createdBy,
            'notes' => $outNotes,
        ]);

        $this->record([
            'treasury_id' => $toTreasuryId,
            'type' => TreasuryTransactionType::TransferIn,
            'amount' => $amount,
            'reference_type' => $referenceType,
            'reference_id' => $referenceId,
            'created_by' => $createdBy,
            'notes' => $inNotes,
        ]);
    }
}export * from './inventory';

