        Route::pattern('treasury', '[0-9]{1,18}');
        Route::pattern('expense', '[0-9]{1,18}');
        Route::pattern('treasury_transfer', '[0-9]{1,18}');
        Route::pattern('shift', '[0-9]{1,18}');

        Route::apiResource('treasuries', TreasuryController::class);

